public static class StrengthStarsNumericExtension
{
	private const int TotalStarsCount = 5;

	private const int MultiplierPlayer = 50;

	private const int MultiplierTeam = 500;

	private const decimal StarsFactor = 0.2m;

	private static readonly string[] _starsFull = new string[7] { "star_gray", "star_yellow", "star_red", "star_blue", "star_purple", "star_magenta", "star_cyan" };

	private static readonly string[] _starsHalf = new string[6] { "star_yellow_gray", "star_red_yellow", "star_blue_red", "star_purple_blue", "star_magenta_purple", "star_cyan_magenta" };

	private static int MaxTier => _starsFull.Length - 2;

	private static List<string> GetFullStars(int tier, int count)
	{
		return (from _ in Enumerable.Range(0, count)
			select _starsFull[tier]).ToList();
	}

	public static string[] GetStrengthStars(this decimal strength, bool forPlayer = true)
	{
		if (strength < 0m)
		{
			strength = default(decimal);
		}
		int num = (forPlayer ? 50 : 500);
		int num2 = Math.Min((int)Math.Floor(strength / (decimal)num), MaxTier);
		decimal num3 = (strength - (decimal)(num2 * num)) / ((decimal)num * 0.2m);
		int num4 = Math.Min((int)Math.Floor(num3), 5);
		int num5 = ((num4 < 5 && num3 - (decimal)num4 >= 0.5m) ? 1 : 0);
		int count = 5 - num4 - num5;
		List<string> fullStars = GetFullStars(num2 + 1, num4);
		if (num5 > 0)
		{
			fullStars.Add(_starsHalf[num2]);
		}
		fullStars.AddRange(GetFullStars(num2, count));
		return fullStars.ToArray();
	}
}
