		public AuthenticationManager(ICoreHelperService coreHelperService, ICrypterService crypterService, IDeviceService deviceService, IPopupService popupService, IAuthService authService)
			: base(coreHelperService, crypterService, deviceService, popupService, authService)
		{
		}

		public void Reset()
		{
			_authService.Token = string.Empty;
			TeamId = Guid.Empty;
			UserId = Guid.Empty;
		}

		public async Task<JsonUser> Authenticate(JsonUser user)
		{
			JsonUser jsonUser = await ExecuteApiAsync(user, _api.Authenticate);
			if (jsonUser != null)
			{
				SetNewUser(jsonUser);
			}
			return jsonUser;
		}

		public void SetNewUser(JsonUser user)
		{
			_authService.Token = user.Token;
			UserId = user.ID;
			TeamId = user.TeamID;
			ManagerName = user.ManagerName;
			IsAdmin = user.IsAdmin;
			_coreHelperService.JsonUser = user;
			AppAnalytics.Instance.SetUserId(UserId);
			AppAnalytics.Instance.TrackUserLevel(user.Level);
			ComponentFactory.Resolve<IAdService>().SetUserId(UserId);
		}

