	public abstract class BaseService<T>
	{
		protected T _api;

		private readonly IPopupService _popupService;

		protected readonly IDeviceService _deviceService;

		protected readonly ICoreHelperService _coreHelperService;

		protected readonly ICrypterService _crypterService;

		protected readonly IAuthService _authService;

		protected abstract string ServiceName { get; }

		public BaseService(ICoreHelperService coreHelperService, ICrypterService crypterService, IDeviceService deviceService, IPopupService popupService, IAuthService authService)
		{
			_deviceService = deviceService;
			_popupService = popupService;
			_coreHelperService = coreHelperService;
			_crypterService = crypterService;
			_authService = authService;
			_api = GenerateApi(URLHelper.BaseServiceUrl + ServiceName);
			Log.Info($"Url for {this}: {URLHelper.BaseServiceUrl}");
		}

		private static T GenerateApi(string url)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_000d: Expected O, but got Unknown
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Expected O, but got Unknown
			return RestService.For<T>(url, new RefitSettings((IHttpContentSerializer)new NewtonsoftJsonContentSerializer(), (IUrlParameterFormatter)null, (IFormUrlEncodedParameterFormatter)null));
		}

		protected async Task<TResult> ExecuteApiAsync<TResult>(TResult serviceObject, Func<TResult, string, string, Task<TResult>> endpoint) where TResult : IServiceObject
		{
			await URLHelper.CheckNetworkState();
			TResult result = default(TResult);
			bool needToRequest = true;
			int counter = 0;
			while (needToRequest)
			{
				if (_authService.IsUserPunished)
				{
					Log.Info("User is punished before - cancel");
					return default(TResult);
				}
				if (!(await CheckAuthentication(serviceObject)))
				{
					Log.Info("Token did not set - quiting");
					return default(TResult);
				}
				string name = CultureInfo.CurrentUICulture.Name;
				serviceObject.Culture = name;
				string locale = _deviceService.GetLocale();
				serviceObject.Locale = locale;
				string utcOffset = TimeZoneInfo.Local.BaseUtcOffset.ToString();
				serviceObject.UtcOffset = utcOffset;
				_crypterService.Sign(serviceObject);
				try
				{
					result = await endpoint(serviceObject, _deviceService.AppVersion, "youthlist,htmligm,friendlist,indtrainings");
				}
				catch (ApiException ex)
				{
					ApiException ex2 = ex;
					AppAnalytics.Instance.TrackError((Exception)(object)ex2);
				}
				catch (Exception ex3)
				{
					AppAnalytics.Instance.TrackError(ex3);
				}
				await _popupService.ShowErrorIfAny(result);
				if (result != null)
				{
					Log.Info($"Request result is not null = {result.Status}");
					ResponseStatus status = result.Status;
					if ((uint)(status - 2) > 1u)
					{
						return result;
					}
					_authService.Reset();
				}
				counter++;
				if (counter > 2)
				{
					Log.Info("Repeat cycle finished");
					Log.Info("Show generic error");
					await _popupService.ShowErrorMessageAsync();
					return default(TResult);
				}
				Log.Info("Repeating");
			}
			return result;
		}

		protected async Task<bool> CheckAuthentication(IRequestObject request)
		{
			if (string.IsNullOrEmpty(_authService.Token))
			{
				AuthResponse authResponse = await _authService.Login();
				if (authResponse == null || authResponse.Status != ResponseStatus.OK || !string.IsNullOrEmpty(authResponse.ErrorMessage))
				{
					return false;
				}
			}
			request.Token = _authService.Token;
			if (_coreHelperService.JsonUser != null)
			{
				_coreHelperService.JsonUser.Token = _authService.Token;
			}
			return true;
		}
	}
