	public class HttpMessageHandlerLogging : DelegatingHandler
	{
		private readonly string[] _types = new string[6] { "html", "text", "xml", "json", "txt", "x-www-form-urlencoded" };

		public HttpMessageHandlerLogging(HttpMessageHandler httpMessageHandler = null)
			: base(httpMessageHandler ?? new HttpClientHandler())
		{
		}

		protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
		{
			StringBuilder sb = new StringBuilder();
			sb.AppendLine();
			sb.AppendLine("========= Request =========");
			sb.AppendLine($"{request.Method} {request.RequestUri.PathAndQuery}");
			if (request.Content != null && (request.Content is StringContent || IsTextBasedContentType(request.Headers) || IsTextBasedContentType(request.Content.Headers)))
			{
				sb.AppendLine("Request content: " + await request.Content.ReadAsStringAsync());
			}
			sb.AppendLine("===========================");
			sb.AppendLine();
			Log.Info(sb.ToString());
			sb.Clear();
			DateTime start = DateTime.Now;
			HttpResponseMessage response = await base.SendAsync(request, cancellationToken);
			DateTime now = DateTime.Now;
			sb.AppendLine();
			sb.AppendLine("========= Response =========");
			HttpResponseMessage httpResponseMessage = response;
			sb.AppendLine($"From: {request.RequestUri.PathAndQuery} {(int)httpResponseMessage.StatusCode} {httpResponseMessage.ReasonPhrase}");
			sb.AppendLine($"Duration: {now - start}");
			if (httpResponseMessage.Content != null && (httpResponseMessage.Content is StringContent || IsTextBasedContentType(httpResponseMessage.Headers) || IsTextBasedContentType(httpResponseMessage.Content.Headers)))
			{
				sb.AppendLine("Response content: " + string.Join("", (await httpResponseMessage.Content.ReadAsStringAsync()).Cast<char>().Take(4000)) + "...");
			}
			sb.AppendLine("============================");
			sb.AppendLine();
			Log.Info(sb.ToString());
			return response;
		}

		private bool IsTextBasedContentType(HttpHeaders headers)
		{
			if (!headers.TryGetValues("Content-Type", out IEnumerable<string> values))
			{
				return false;
			}
			string header = string.Join(" ", values).ToLowerInvariant();
			return _types.Any((string t) => header.Contains(t));
		}
	}
