	public class TeamManager : BaseService<ITeamApi>, ITeamManager
	{
		private readonly ILocalNotificationService _localNotificationService;

		private readonly IAuthenticationService _authenticationService;

		protected override string ServiceName => $"{GameServices.TeamService}.svc";

		public TeamManager(ICoreHelperService coreHelperService, ICrypterService crypterService, IDeviceService deviceService, IPopupService popupService, IAuthService authService, ILocalNotificationService localNotificationService, IAuthenticationService authenticationService)
			: base(coreHelperService, crypterService, deviceService, popupService, authService)
		{
			_localNotificationService = localNotificationService;
			_authenticationService = authenticationService;
		}

		public async Task<JsonUser> SaveUser(JsonUser user)
		{
			JsonUser jsonUser = await ExecuteApiAsync(user, _api.SaveUser);
			if (jsonUser != null && string.IsNullOrEmpty(user.ErrorMessage))
			{
				_coreHelperService.JsonUser = jsonUser;
				_coreHelperService.JsonTeam.User = jsonUser;
			}
			return jsonUser;
		}

		public async Task<JsonDefinitions> GetDefinitions(JsonDefinitions definitions)
		{
			definitions.Emblems = new List<GT.Core.Json.Member.JsonEmblem>
			{
				new GT.Core.Json.Member.JsonEmblem()
			};
			definitions.Trikots = new List<GT.Core.Json.Member.JsonTrikot>
			{
				new GT.Core.Json.Member.JsonTrikot()
			};
			JsonDefinitions jsonDefinitions = await _authenticationService.GetDefinitions(definitions);
			if (jsonDefinitions != null)
			{
				_coreHelperService.JsonDefinitions = jsonDefinitions;
				_localNotificationService.UpdateNewSeason();
			}
			return jsonDefinitions;
		}

		public async Task<GT.Core.Json.JsonTeam> GetTeam(GT.Core.Json.JsonTeam team, bool update)
		{
			GT.Core.Json.JsonTeam jsonTeam = await ExecuteApiAsync(team, _api.GetTeam);
			if (jsonTeam != null)
			{
				IAuthService authService = ComponentFactory.Resolve<IAuthService>();
				authService.Token = jsonTeam.User?.Token;
				Log.Info("set new token: " + authService.Token);
				if (update)
				{
					if (jsonTeam.Team != null && !string.IsNullOrEmpty(jsonTeam.Team.StarterPackageDate))
					{
						_coreHelperService.SpecialOfferDate = _coreHelperService.ParseDate(jsonTeam.Team.StarterPackageDate);
					}
					INotificationManager notificationManager = ComponentFactory.Resolve<INotificationManager>();
					if (_coreHelperService.JsonUser != null)
					{
						notificationManager.Unsubscribe(_coreHelperService.JsonUser.ID.ToString().ToLower());
					}
					_coreHelperService.JsonTeam = jsonTeam;
					_coreHelperService.JsonUser = jsonTeam.User;
					if (jsonTeam.User != null)
					{
						notificationManager.SubscribeToChannel(jsonTeam.User.ID.ToString().ToLower());
					}
				}
				else
				{
					_coreHelperService.JsonTeamUI = jsonTeam;
					_coreHelperService.JsonUserUI = jsonTeam.User;
				}
			}
			return jsonTeam;
		}

		public async Task<JsonRemoveEmails> RemoveEmails(JsonRemoveEmails emails)
		{
			JsonRemoveEmails result = null;
			try
			{
				result = await ExecuteApiAsync(emails, _api.RemoveEmail);
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
			return result;
		}

		public async Task<GT.Core.Json.JsonStadium> GetStadium2(GT.Core.Json.JsonStadium stadium, bool update)
		{
			GT.Core.Json.JsonStadium jsonStadium = await ExecuteApiAsync(stadium, _api.GetStadium2);
			if (jsonStadium != null)
			{
				if (update)
				{
					_coreHelperService.JsonStadium = jsonStadium;
				}
				else
				{
					_coreHelperService.JsonStadiumUI = jsonStadium;
				}
			}
			return jsonStadium;
		}

		public async Task<JsonPressRelease> CreatePressRelease(JsonPressRelease pressRelease)
		{
			JsonPressRelease result = await ExecuteApiAsync(pressRelease, _api.CreatePressRelease);
			if (result != null && string.IsNullOrEmpty(pressRelease.ErrorMessage))
			{
				await GetTeam(new GT.Core.Json.JsonTeam(), update: true);
			}
			return result;
		}

		public async Task<JsonPressRelease> DeletePressRelease(JsonPressRelease pressRelease)
		{
			JsonPressRelease result = await ExecuteApiAsync(pressRelease, _api.CreatePressRelease);
			if (result != null && string.IsNullOrEmpty(result.ErrorMessage))
			{
				await GetTeam(new GT.Core.Json.JsonTeam(), update: true);
			}
			return result;
		}

		public async Task<GT.Core.Json.JsonTeamLike> DeleteTeamLike(GT.Core.Json.JsonTeamLike teamLike)
		{
			GT.Core.Json.JsonTeamLike result = await ExecuteApiAsync(teamLike, _api.TeamLike);
			if (result != null && string.IsNullOrEmpty(result.ErrorMessage))
			{
				await GetTeam(new GT.Core.Json.JsonTeam(), update: true);
			}
			return result;
		}

		public async Task<JsonLeague> GetLeague(JsonLeague league, bool update)
		{
			JsonLeague jsonLeague = await ExecuteApiAsync(league, _api.GetLeague);
			if (jsonLeague != null)
			{
				if (update)
				{
					_coreHelperService.JsonLeague = jsonLeague;
				}
				else
				{
					_coreHelperService.JsonLeagueUI = jsonLeague;
				}
			}
