	public class NavigationPath
	{
		private const string Dot = ".";

		private static readonly string[] _menuSeparator = new string[1] { "." };

		public MenuItemIdentifier MenuId { get; private set; }

		public int TabIndex { get; private set; }

		public SubmenuIdentifier SubmenuId { get; private set; }

		public static NavigationPath FromTutorialStep(TutorialStep tutorialStep)
		{
			NavigationPath navigationPath = new NavigationPath();
			string text = tutorialStep.Screen ?? string.Empty;
			if (text.Contains("."))
			{
				string[] array = text.Split(_menuSeparator, StringSplitOptions.None);
				text = array[0];
				if (array.Length > 1 && int.TryParse(array[1], out var result))
				{
					navigationPath.TabIndex = result;
				}
			}
			if (Enum.TryParse<MenuItemIdentifier>(text, out var result2))
			{
				navigationPath.MenuId = result2;
			}
			if (Enum.TryParse<SubmenuIdentifier>(tutorialStep.Submenu, out var result3))
			{
				navigationPath.SubmenuId = result3;
			}
			return navigationPath;
		}

		public override string ToString()
		{
			return $"[{MenuId}, tab: {TabIndex}]";
		}
	}
