	public class MatchReportEntryData
	{
		public Severity EntrySeverity { get; set; }

		public EventType Type { get; set; }

		public bool IsAdditionalTime { get; set; }

		public bool IsHomeTeamEvent { get; set; }

		public string KeyPlayerName { get; set; }

		public string KeyPlayerName2 { get; set; }

		public int Minute { get; set; }

		public string Message { get; set; }

		public int HomeTeamGoals { get; set; }

		public int AwayTeamGoals { get; set; }

		public int HomeTeamGoalshots { get; set; }

		public int AwayTeamGoalshots { get; set; }

		public int HomeTeamCorners { get; set; }

		public int AwayTeamCorners { get; set; }

		public int HomeTeamOffside { get; set; }

		public int AwayTeamOffside { get; set; }

		public int HomeTeamActions { get; set; }

		public int AwayTeamActions { get; set; }

		public int HomeTeamFouls { get; set; }

		public int AwayTeamFouls { get; set; }

		public int HomeTeamYellowCards { get; set; }

		public int AwayTeamYellowCards { get; set; }

		public int HomeTeamRedCards { get; set; }

		public int AwayTeamRedCards { get; set; }

		public int Second { get; set; }

		public bool IsMinuteVisible { get; set; }

		public string ExtendedMessage => $"{Message} / Type = [{Type}]";

		public EventSource EventSource => Type switch
		{
			EventType.MatchInfo => EventSource.Both, 
			EventType.KickOff => EventSource.Both, 
			EventType.Halftime => EventSource.Both, 
			EventType.End => EventSource.Both, 
			EventType.Statistic => EventSource.Both, 
			_ => (!IsHomeTeamEvent) ? EventSource.Away : EventSource.Home, 
		};
	}
