		public List<LineUp> HomeLineUp { get; set; }

		[XmlElement]
		public List<LineUp> AwayLineUp { get; set; }

		public bool GetVictoryForMyTeamInMatch(JsonExtendedMatch match)
		{
			if (match == null || MatchEvents == null || MatchEvents.Count == 0)
			{
				return false;
			}
			GT.Core.Json.Member.JsonTeam jsonTeam = ComponentFactory.Resolve<ICoreHelperService>()?.JsonTeam?.Team;
			if (jsonTeam == null)
			{
				return false;
			}
			MatchReportEntry matchReportEntry = MatchEvents[MatchEvents.Count - 1];
			bool num = matchReportEntry.HomeTeamGoals > matchReportEntry.AwayTeamGoals && match.HomeTeamID == jsonTeam.ID;
			bool flag = matchReportEntry.HomeTeamGoals < matchReportEntry.AwayTeamGoals && match.AwayTeamID == jsonTeam.ID;
			return num || flag;
		}
	}
