	public static class ComponentRegistry
	{
		private static IInjectionContainer _container;

		public static IInjectionContainer Container
		{
			get
			{
				if (_container == null)
				{
					_container = new SimpleInjectorService();
				}
				return _container;
			}
		}

		public static void Reset()
		{
			_container = new SimpleInjectorService();
		}

		public static void Register<T>() where T : class
		{
			Container.Register<T>();
		}

		public static void Register<T>(T instance) where T : class
		{
			Container.Register(instance);
		}

		public static void RegisterCollection<T>(Type[] implementations) where T : class
		{
			Container.RegisterCollection<T>(implementations);
		}

		public static void Register<T, TN>() where T : class where TN : class, T
		{
			Log.Info($"registering {typeof(T)}");
			Container.Register<T, TN>();
		}

		public static void RegisterTransient<T, TN>() where T : class where TN : class, T
		{
			Container.RegisterTransient<T, TN>();
		}
	}
