	public struct CoreColor
	{
		public float R;

		public float G;

		public float B;

		public CoreColor(float r, float g, float b)
		{
			R = r;
			G = g;
			B = b;
		}
	}
	public static class ColorHelper
	{
		public static CoreColor AddLuminosity(this CoreColor color, float delta)
		{
			ConvertToHsl(color.R, color.G, color.B, out var h, out var s, out var l);
			h = h.Clamp(0f, 1f);
			s = s.Clamp(0f, 1f);
			l = (l + delta).Clamp(0f, 1f);
			ConvertToRgb(h, s, l, out var r, out var g, out var b);
			return new CoreColor(r, g, b);
		}

		private static void ConvertToRgb(float hue, float saturation, float luminosity, out float r, out float g, out float b)
		{
			if (luminosity == 0f)
			{
				r = (g = (b = 0f));
				return;
			}
			if (saturation == 0f)
			{
				r = (g = (b = luminosity));
				return;
			}
			float num = ((luminosity <= 0.5f) ? (luminosity * (1f + saturation)) : (luminosity + saturation - luminosity * saturation));
			float num2 = 2f * luminosity - num;
			float[] array = new float[3]
			{
				hue + 1f / 3f,
				hue,
				hue - 1f / 3f
			};
			float[] array2 = new float[3];
			for (int i = 0; i < 3; i++)
			{
				if (array[i] < 0f)
				{
					array[i] += 1f;
				}
				if (array[i] > 1f)
				{
					array[i] -= 1f;
				}
				if (6.0 * (double)array[i] < 1.0)
				{
					array2[i] = num2 + (num - num2) * array[i] * 6f;
				}
				else if (2.0 * (double)array[i] < 1.0)
				{
					array2[i] = num;
				}
				else if (3.0 * (double)array[i] < 2.0)
				{
					array2[i] = num2 + (num - num2) * (2f / 3f - array[i]) * 6f;
				}
				else
				{
					array2[i] = num2;
				}
			}
			r = array2[0];
			g = array2[1];
			b = array2[2];
		}

		private static void ConvertToHsl(float r, float g, float b, out float h, out float s, out float l)
		{
			float val = Math.Max(r, g);
			val = Math.Max(val, b);
			float val2 = Math.Min(r, g);
			val2 = Math.Min(val2, b);
			l = (val2 + val) / 2f;
			if ((double)l <= 0.0)
			{
				h = (s = (l = 0f));
				return;
			}
			float num = (s = val - val2);
			if ((double)s > 0.0)
			{
				s /= ((l <= 0.5f) ? (val + val2) : (2f - val - val2));
				float num2 = (val - r) / num;
				float num3 = (val - g) / num;
				float num4 = (val - b) / num;
				if (r == val)
				{
					h = ((g == val2) ? (5f + num4) : (1f - num3));
				}
				else if (g == val)
				{
					h = ((b == val2) ? (1f + num2) : (3f - num4));
				}
				else
				{
					h = ((r == val2) ? (3f + num3) : (5f - num2));
				}
				h /= 6f;
			}
			else
			{
				h = 0f;
				s = 0f;
			}
		}
	}
