	public static class NumericExtention
	{
		private static readonly Random _rnd = new Random();

		public static int GetRandom(this int value)
		{
			return _rnd.Next(value);
		}

		public static int ToInt(this float floatValue)
		{
			return (int)Math.Round(floatValue);
		}

		public static int ToInt(this double doubleValue)
		{
			return (int)Math.Round(doubleValue);
		}

		public static float ToFloat(this decimal doubleValue)
		{
			return (float)doubleValue;
		}

		public static bool IsIndexFor(this int index, ICollection list)
		{
			if (list == null)
			{
				return false;
			}
			if (index > -1)
			{
				return index < list.Count;
			}
			return false;
		}

		public static string TrimNumber(this long number, int length)
		{
			string text = number.ToString();
			if (text.Length > length)
			{
				return text.Substring(text.Length - length);
			}
			return $"{number:D6}";
		}

		public static string ToShortValue(this int value)
		{
			return ((long)value).ToShortValue();
		}

		public static string ToShortValue(this long value)
		{
			string valueText = value.ToString();
			if (value <= 0)
			{
				return valueText;
			}
			int num = 1000000000;
			string[] array = new string[3] { "B", "M", "K" };
			foreach (string symbol in array)
			{
				if (ConvertToShortValue(value, num, symbol, out valueText))
				{
					break;
				}
				num /= 1000;
			}
			return valueText;
		}

		private static bool ConvertToShortValue(long value, int module, string symbol, out string valueText)
		{
			if (value >= module)
			{
				double num = (double)value / (double)module;
				int num2 = 3 - Math.Truncate(num).ToString().Length;
				if (num2 >= 0)
				{
					valueText = $"{Math.Round(num, num2)}{symbol}";
					return true;
				}
			}
			valueText = value.ToString("N0");
			return false;
		}

		public static int Clamp(this int value, int min, int max)
		{
			if (value < min)
			{
				value = min;
			}
			if (value > max)
			{
				value = max;
			}
			return value;
		}

		public static decimal Clamp(this decimal value, decimal min, decimal max)
		{
			if (value < min)
			{
				value = min;
			}
			if (value > max)
			{
				value = max;
			}
			return value;
		}

