	public static class TaskExtension
	{
		public static async void FireAndForgetSafeAsync(this Task task)
		{
			try
			{
				await task;
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
		}
	}
	public static class TimeSpanExtension
	{
		private static readonly string Days = "StadiumView#Days".Translate();

		private static readonly string DayLong = "Day".Translate();

		private static readonly string DaysLong = "Days".Translate();

		private static readonly string[] StringSeparator = new string[1] { "|" };

		private const string TimeFormat = "hh\\:mm\\:ss";

		public static string ToLocalizedString(this TimeSpan? timeSpan, bool onlyDays = false)
		{
			if (!timeSpan.HasValue)
			{
				return string.Empty;
			}
			return timeSpan.Value.ToLocalizedString(onlyDays);
		}

		public static string ToLocalizedString(this TimeSpan timeSpan, bool onlyDays = false)
		{
			if (timeSpan.TotalDays >= 1.0)
			{
				if (onlyDays)
				{
					int num = (int)Math.Ceiling(timeSpan.TotalDays);
					string text = DaysLong;
					if (DaysLong.Contains(StringSeparator[0]))
					{
						string text2 = num.ToString();
						int.TryParse(text2[text2.Length - 1].ToString(), out var result);
						bool flag = result >= 2 && result <= 4 && (num < 5 || num > 20);
						text = DaysLong.Split(StringSeparator, StringSplitOptions.None)[(!flag) ? 1u : 0u];
					}
					return $"{num} {((num > 1) ? text : DayLong)}";
				}
				return string.Format("{0}{1} {2}", timeSpan.Days, Days, timeSpan.ToString("hh\\:mm\\:ss"));
			}
			return timeSpan.ToString("hh\\:mm\\:ss");
		}
	}
	public static class TypeExtension
	{
		private static readonly Dictionary<Type, Dictionary<string, PropertyInfo>> _properties = new Dictionary<Type, Dictionary<string, PropertyInfo>>();

		public static Dictionary<string, PropertyInfo> GetPropertyDictionary(this Type type)
		{
			if (!_properties.ContainsKey(type))
			{
				_properties[type] = type.GetProperties().ToDictionary((PropertyInfo x) => x.Name);
			}
			return _properties[type];
		}
	}
