	public class SimpleInjectorService : IInjectionContainer
	{
		private Container _container;

		public SimpleInjectorService()
		{
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Expected O, but got Unknown
			_container = new Container();
		}

		public T Resolve<T>() where T : class
		{
			return _container.GetInstance<T>();
		}

		public IEnumerable<T> ResolveAll<T>() where T : class
		{
			return _container.GetAllInstances<T>();
		}

		public object Resolve(Type type)
		{
			return _container.GetInstance(type);
		}

		public IEnumerable<object> ResolveAll(Type type)
		{
			return _container.GetAllInstances(type);
		}

		public void Register<T>() where T : class
		{
			_container.Register<T>((Lifestyle)(object)Lifestyle.Singleton);
		}

		public void Register<T, TN>() where T : class where TN : class, T
		{
			_container.Register<T, TN>((Lifestyle)(object)Lifestyle.Singleton);
		}

		public void RegisterTransient<T, TN>() where T : class where TN : class, T
		{
			_container.Register<T, TN>(Lifestyle.Transient);
		}

		public void Register<T>(T instance) where T : class
		{
			_container.Register<T>((Func<T>)(() => instance), (Lifestyle)(object)Lifestyle.Singleton);
		}

		public void RegisterCollection<T>(Type[] implementations) where T : class
		{
			_container.Collection.Register<T>(implementations);
		}
	}
