	public class BuildingData
	{
		private DateTime? _buildStartValue;

		private DateTime? _buildEndValue;

		[DataMember(EmitDefaultValue = false)]
		public Guid Id { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Name { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Description { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string EffectName { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int CurrentValue { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int MaxValue { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int NewValue { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string BuildStart { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string BuildEnd { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public long Earnings { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int Utilization { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal UpgradeCost { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal UpgradeCostPremium { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal DailyCost { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal DailyCostIncrease { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal Profit { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string ProfitSign { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal ProfitIncrease { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal Duration { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int Capacity { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool HasWarning { get; set; }

		public bool IsUnderConstruction => BuildEndValue > DateTime.UtcNow;

		public DateTime BuildStartValue
		{
			get
			{
				DateTime valueOrDefault = _buildStartValue.GetValueOrDefault();
				if (!_buildStartValue.HasValue)
				{
					valueOrDefault = BuildStart.ParseToDate();
					_buildStartValue = valueOrDefault;
					return valueOrDefault;
				}
				return valueOrDefault;
			}
		}

		public DateTime BuildEndValue
		{
			get
			{
				DateTime valueOrDefault = _buildEndValue.GetValueOrDefault();
				if (!_buildEndValue.HasValue)
				{
					valueOrDefault = BuildEnd.ParseToDate();
					_buildEndValue = valueOrDefault;
					return valueOrDefault;
				}
				return valueOrDefault;
			}
		}

		public double TotalBuildSeconds
		{
			get
			{
				if (!IsUnderConstruction)
				{
					return 0.0;
				}
				return (BuildEndValue - BuildStartValue).TotalSeconds;
			}
		}

		public int GetSpeedupPrice(int speedupCost)
		{
			if (!IsUnderConstruction)
			{
				return 0;
			}
			DateTime dateTime = ((BuildStartValue > DateTime.UtcNow) ? BuildStartValue : DateTime.UtcNow);
			double totalMinutes = (BuildEndValue - dateTime).TotalMinutes;
			return (int)Math.Max(0.0, Math.Ceiling(totalMinutes)) * speedupCost;
		}
	}
