		public string Message { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsAdmin { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsMine { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsNewUser { get; set; }

		public DateTime DateValue => Date.ParseToDate();

		public DateTime DateGroup { get; set; }

		public string Header { get; set; }

		public ICommand TapCommand => new AsyncCommand(TapMessage);

		private async Task TapMessage()
		{
			if (!IsMine && !IsAdmin)
			{
				ComponentFactory.Resolve<ISoundManager>().PlaySound(Sounds.Button);
				ComparePopupViewModel popupViewModel = new ComparePopupViewModel(showClub: true)
				{
					TeamId = TeamId
				};
				await ComponentFactory.Resolve<IPopupService>().ShowPopupAsync(popupViewModel);
			}
		}
	}
