	[DataContract]
	public class LeagueTableData
	{
		[DataMember(EmitDefaultValue = false)]
		public Guid Id { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Name { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal Strength { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Logo { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Country { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsOnline { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsMine { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public LeagueTableValue Matches { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public LeagueTableValue Wins { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public LeagueTableValue Losses { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public LeagueTableValue Draws { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public LeagueTableValue GoalsScored { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public LeagueTableValue GoalsReceived { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public LeagueTableValue Points { get; set; }

		public int TotalPoints => Points.Home + Points.Away;

		public int TotalMatches => Matches.Home + Matches.Away;

		public int GoalDifference => GoalsScored.Home + GoalsScored.Away - GoalsReceived.Home - GoalsReceived.Away;

		public TableCellColor GetTeamColor()
		{
			if (!IsMine)
			{
				return TableCellColor.Default;
			}
			return TableCellColor.Highlight;
		}

		public int GetWins(bool home, bool away)
		{
			return (home ? Wins.Home : 0) + (away ? Wins.Away : 0);
		}

		public int GetLosses(bool home, bool away)
		{
			return (home ? Losses.Home : 0) + (away ? Losses.Away : 0);
		}

		public int GetDraws(bool home, bool away)
		{
			return (home ? Draws.Home : 0) + (away ? Draws.Away : 0);
		}

		public int GetTotalPoints(bool home, bool away)
		{
			return (home ? Points.Home : 0) + (away ? Points.Away : 0);
		}

		public int GetTotalMatches(bool home, bool away)
		{
			return (home ? Matches.Home : 0) + (away ? Matches.Away : 0);
		}

		public int GetGoalsScored(bool home, bool away)
		{
			return (home ? GoalsScored.Home : 0) + (away ? GoalsScored.Away : 0);
		}

		public int GetGoalsReceived(bool home, bool away)
		{
			return (home ? GoalsReceived.Home : 0) + (away ? GoalsReceived.Away : 0);
		}

		public int GetGoalDifference(bool home, bool away)
		{
			return GetGoalsScored(home, away) - GetGoalsReceived(home, away);
		}
	}
