	[Serializable]
	[DataContract]
	public class LineupPlayerData : SquadPlayerData
	{
		[DataMember(EmitDefaultValue = false)]
		public List<PositionStrength> Positions { get; set; }

		public decimal GetStrengthForPositionId(Guid positionId)
		{
			if (!base.IsReady)
			{
				return 0m;
			}
			if (Positions == null || Positions.Count == 0)
			{
				return 0m;
			}
			return Positions.FirstOrDefault((PositionStrength x) => x.PositionId == positionId)?.Strength ?? 0m;
		}
	}
