	[Serializable]
	[DataContract]
	public class MatchData : BaseMatchData
	{
		[DataMember(EmitDefaultValue = false)]
		public string HomeCountry { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string AwayCountry { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int HomeScore { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int AwayScore { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public Guid OpponentTeamId { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int HomeStrength { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int AwayStrength { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool HasLineup { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string HomeTrikot { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string AwayTrikot { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsFriendly { get; set; }

		public bool HasScore
		{
			get
			{
				if (HomeScore > -1)
				{
					return AwayScore > -1;
				}
				return false;
			}
		}

		public string GetMatchScore()
		{
			if (!HasScore)
			{
				return "- : -";
			}
			return $"{HomeScore} : {AwayScore}";
		}

		public TableCellColor GetFixtureColor()
		{
			if (!HasScore)
			{
				return TableCellColor.Default;
			}
			return TableCellColor.Accent;
		}

		public TableCellColor GetTeamColor()
		{
			if (base.MyTeam < 1)
			{
				return TableCellColor.Default;
			}
			return TableCellColor.Highlight;
		}
	}
