	[Serializable]
	[DataContract]
	public class NewLineupStatusData : BaseMatchData
	{
		[DataMember(EmitDefaultValue = false)]
		public LineupStatus LineupStatus { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsLeagueMatch { get; set; }

		public ICommand ShowWarningCommand => new Command(ShowPopUp);

		public ICommand ShowLineupCommand { get; set; }

		[IgnoreDataMember]
		public string TutorialControlId { get; set; }

		private void ShowPopUp()
		{
			ComponentFactory.Resolve<IPopupService>().ShowOkMessage(((LineupStatus == LineupStatus.Incomplete) ? "LineupIncompleteMessage" : "NoLineupMessage").Translate());
