	[Serializable]
	[DataContract]
	public class OfferData
	{
		[DataMember(EmitDefaultValue = false)]
		public long Current { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public long Previous { get; set; }

		public decimal Change
		{
			get
			{
				if (Previous <= 0)
				{
					return 0m;
				}
				return (decimal)(Current - Previous) / (decimal)Previous * 100m;
			}
		}
	}
