	[Serializable]
	[DataContract]
	public class SquadPlayerData : PlayerData
	{
		private ICommand _showWarningCommand;

		private static readonly string[] _skillNames = (from x in Skill.GetAllSkills()
			select x.Translate()).ToArray();

		private static readonly string[] _lightTrikots = new string[25]
		{
			"trikot4", "trikot6", "trikot8", "trikot9", "trikot11", "trikot13", "trikot16", "trikot17", "trikot22", "trikot24",
			"trikot29", "trikot36", "trikot39", "trikot41", "trikot42", "trikot45", "trikot49", "trikot54", "trikot29", "trikot31",
			"trikot32", "trikot40", "trikot44", "trikot47", "trikot51"
		};

		[DataMember(EmitDefaultValue = false)]
		public decimal Experience { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal Fitness { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Body { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Gloves { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Shoes { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal Salary { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal MarketValue { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string Origin { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal[] Skills { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int MainSkill { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int[] BonusSkills { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int YellowCards { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool HasRedCard { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int Injured { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsForSale { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal SellPrice { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal TransfermarketFee { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal TransfermarketMaxOffer { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal TransfermarketMinOffer { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int TransfermarketMaxHours { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsUpgraded { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal MaxUpgradeStrength { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public int Shirt { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool CanExtendContract { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool HasIndividualTraining { get; set; }

		[IgnoreDataMember]
		public double SliderMaxUpgradeStrength => (double)Math.Max(base.Strength, MaxUpgradeStrength);

		[IgnoreDataMember]
		public string ShirtName { get; set; }

		[IgnoreDataMember]
		public bool IsShirtLight => _lightTrikots.Contains(ShirtName);

		public ICommand ShowWarningCommand => _showWarningCommand ?? (_showWarningCommand = new Command(ShowWarningPopup));

		public bool OldAge => base.Age >= 34;

		public bool GoodTalent => base.Talent >= 9;

		public bool HasContract => base.EndDateValue > DateTime.UtcNow;

		public bool IsReady
		{
			get
			{
				if (HasContract && Injured <= 0)
				{
					return !HasRedCard;
				}
				return false;
			}
		}

		public decimal Penalty => Skills[13];

		public decimal Freekick => Skills[12];

		public decimal Corner => Skills[11];

		public string InjuredDaysText => TimeSpan.FromDays(Injured).ToLocalizedString(onlyDays: true);

		public List<SkillProgressData> GetSkillDetails(bool impactOnly = false)
		{
			List<int> usedSkills = new List<int>();
			List<SkillProgressData> list = new List<SkillProgressData>();
			if (!impactOnly)
			{
				list.AddRange(new SkillProgressData[4]
				{
					new SkillProgressData("Talent".Translate(), base.Talent, 10m)
					{
						IsInt = true,
						IsHighlighted = (base.Talent > 8)
					},
					new SkillProgressData("Experience".Translate(), Experience, 150m)
					{
						IsInt = true
					},
					new SkillProgressData("Fitness".Translate(), Fitness)
					{
						IsInt = true
					},
					new SkillProgressData()
				});
			}
			AddSkill(list, usedSkills, MainSkill, main: true);
			int[] bonusSkills = BonusSkills;
			foreach (int index in bonusSkills)
			{
				AddSkill(list, usedSkills, index, main: false, bonus: true);
			}
			if (impactOnly)
			{
				return list;
			}
			list.Add(new SkillProgressData());
			for (int j = 0; j < _skillNames.Length; j++)
			{
				AddSkill(list, usedSkills, j);
			}
			return list;
		}

		private void AddSkill(List<SkillProgressData> skills, List<int> usedSkills, int index, bool main = false, bool bonus = false)
		{
			if (!usedSkills.Contains(index))
			{
				usedSkills.Add(index);
				skills.Add(new SkillProgressData(_skillNames[index], Skills[index], 100m, main, bonus));
			}
		}

		private void ShowWarningPopup()
		{
			ComponentFactory.Resolve<IPopupService>().ShowOkMessage("CareerEndInfo".Translate());
		}

		public void UpdateStrengthAndSkillsFrom(SquadPlayerData player)
		{
			if (player == null)
			{
				return;
			}
			base.Strength = player.Strength;
			if (Skills != null && player.Skills != null && Skills.Length == player.Skills.Length)
			{
				for (int i = 0; i < Skills.Length; i++)
				{
					Skills[i] = player.Skills[i];
				}
			}
		}
	}
