	public class AppAnalytics
	{
		private const string ApiExceptionKey = "apiexception";

		private const string EnvironmentKey = "environment";

		private const string DebugValue = "debug";

		private const string ReleaseValue = "release";

		private static readonly Lazy<AppAnalytics> _instance = new Lazy<AppAnalytics>(() => new AppAnalytics());

		private readonly List<IAnalyticsService> _services;

		private const int UserEngagedLevel = 80;

		public static AppAnalytics Instance => _instance.Value;

		public AppAnalytics()
		{
			_services = new List<IAnalyticsService>();
		}

		public void RegisterAnalyticsService(IAnalyticsService analytics)
		{
			_services.Add(analytics);
		}

		public void SetUserId(Guid id)
		{
			if (id == Guid.Empty)
			{
				return;
			}
			foreach (IAnalyticsService service in _services)
			{
				service.SetUserId(id);
			}
		}

		public void TrackEvent(AnalyticsEvent analyticsEvent)
		{
			foreach (IAnalyticsService service in _services)
			{
				service.TrackEvent(analyticsEvent);
			}
		}

		public void TrackScreen(string screenName)
		{
			foreach (IAnalyticsService service in _services)
			{
				service.TrackEvent(AnalyticsEvent.Screen, AnalyticsKey.Name, screenName);
			}
		}

		public void TrackError(Exception ex, Dictionary<string, string> properties = null)
		{
			if (properties == null)
			{
				properties = new Dictionary<string, string>();
			}
			ApiException ex2 = (ApiException)(object)((ex is ApiException) ? ex : null);
			if (ex2 != null)
			{
				properties.Add("apiexception", ex2.Content);
			}
			properties.Add("environment", "release");
			foreach (IAnalyticsService service in _services)
			{
				service.TrackError(ex, properties);
			}
		}

		public void TrackPurchase(string id, string currency, double price)
		{
			foreach (IAnalyticsService service in _services)
			{
				service.TrackPurchase(id, currency, price);
			}
		}

		public void TrackUserLevel(int userLevel)
		{
			TrackUserEngaged(userLevel);
			string text = Preferences.Get(AnalyticsEvent.UserRanking.ToString(), string.Empty);
			if (!string.IsNullOrEmpty(text))
			{
				return;
			}
			string text2 = GetManagerRanking(userLevel).ToLower();
			if (text == text2)
			{
				return;
			}
			Preferences.Set(AnalyticsEvent.UserRanking.ToString(), text2);
			int managerRankIndex = GetManagerRankIndex(userLevel);
			foreach (IAnalyticsService service in _services)
			{
				service.TrackEvent(AnalyticsEvent.UserRanking, AnalyticsKey.Level, managerRankIndex);
			}
		}

		private void TrackUserEngaged(int level)
		{
			if (level < 80 || Preferences.Get(AnalyticsEvent.UserEngaged.ToString(), false))
			{
				return;
			}
			foreach (IAnalyticsService service in _services)
			{
				service.TrackEvent(AnalyticsEvent.UserEngaged, AnalyticsKey.Success, true);
			}
			Preferences.Set(AnalyticsEvent.UserEngaged.ToString(), true);
		}

		private string GetManagerRanking(int level)
		{
			string[] array = new string[10] { "Rookie", "Trainee", "Amateur", "Motivator", "Experienced", "Advanced", "Pro", "Champion", "Elite", "Master" };
			int num = GetManagerRankIndex(level).Clamp(0, array.Length - 1);
			return array[num];
		}

		private int GetManagerRankIndex(int level)
		{
			if (level >= 0 && level < 200)
			{
				return 0;
			}
			if (level >= 200 && level < 400)
			{
				return 1;
			}
			if (level >= 400 && level < 800)
			{
				return 2;
			}
			if (level >= 800 && level < 1200)
			{
				return 3;
			}
			if (level >= 1200 && level < 1600)
			{
				return 4;
			}
			if (level >= 1600 && level < 2400)
			{
				return 5;
			}
			if (level >= 2400 && level < 3200)
			{
				return 6;
			}
			if (level >= 3200 && level < 4000)
			{
				return 7;
			}
			if (level >= 4000 && level < 4800)
			{
				return 8;
			}
			return 9;
		}
	}
