	public class AuthService : BaseBackendService<IAuthApi>, IAuthService
	{
		private readonly ICredentialService _credentialService;

		protected override string ServiceUrl => URLHelper.NewBackendUrl + "api/";

		protected override string ServiceName => "Authentication";

		public string Token { get; set; }

		public bool IsAdmin { get; private set; }

		public Guid UserId { get; private set; }

		public bool IsUserPunished { get; private set; }

		public AuthService()
		{
			Token = "000";
			_credentialService = ComponentFactory.Resolve<ICredentialService>();
		}

		public async Task<AuthResponse> Login()
		{
			AuthRequest authRequest = await _credentialService.GetCredentials();
			bool flag = false;
			switch ((AuthMethod)authRequest.AuthMethod)
			{
			case AuthMethod.LoginAndPassword:
				flag = !string.IsNullOrEmpty(authRequest.Login) && !string.IsNullOrEmpty(authRequest.Password);
				break;
			case AuthMethod.Facebook:
			case AuthMethod.Apple:
				flag = !string.IsNullOrEmpty(authRequest.AuthId);
				break;
			}
			if (!flag)
			{
				return new AuthResponse
				{
					Status = ResponseStatus.InvalidRequest
				};
			}
			return await LoginInternal(authRequest);
		}

		public async Task<AuthResponse> Login(string authId, AuthMethod method)
		{
			AuthRequest request = new AuthRequest
			{
				AuthId = authId,
				AuthMethod = (int)method
			};
			return await LoginInternal(request);
		}

		public async Task<AuthResponse> Login(string login, string password)
		{
			string password2 = _crypterService.CreateMD5(password);
			AuthRequest request = new AuthRequest
			{
				Login = login,
				Password = password2,
				AuthMethod = 0
			};
			return await LoginInternal(request);
		}

		private async Task<AuthResponse> LoginInternal(AuthRequest request)
		{
			Log.Info($"Login with method: {request.AuthMethod}");
			PrepareRequest(request);
			Sign(request);
			await URLHelper.CheckNetworkState();
			AuthResponse result = null;
			int counter = 0;
			while (result == null)
			{
				try
				{
					result = await _api.Login(request, _deviceService.AppVersion, "youthlist,htmligm,friendlist,indtrainings");
				}
				catch (ApiException ex)
				{
					ApiException ex2 = ex;
					AppAnalytics.Instance.TrackError((Exception)(object)ex2);
				}
				catch (Exception ex3)
				{
					AppAnalytics.Instance.TrackError(ex3);
				}
				if (result != null && result.Punishment > 0 && !string.IsNullOrEmpty(result.Message))
				{
					Log.Info($"User is punished = {result.Punishment} ({result.Message})");
					result.ErrorMessage = null;
					if (!IsUserPunished)
					{
						await _popupService.ShowOkMessageAsync("Info".Translate(), result.Message);
					}
					if (result.Punishment > 1)
					{
						IsUserPunished = true;
						Reset();
						ComponentFactory.Resolve<INavigationService>().NavigateTo(ScreenIdentifier.Login);
						Log.Info("Navigated to login");
						return null;
					}
					IsUserPunished = false;
				}
				else
				{
					IsUserPunished = false;
					await _popupService.ShowErrorIfAny(result);
				}
				counter++;
				if (counter > 2)
				{
					await _popupService.ShowErrorMessageAsync("", Character.Anna);
					return null;
				}
			}
			if (result.Status == ResponseStatus.OK)
			{
				Token = result.Token;
				IsAdmin = result.IsAdmin;
				Log.Info($"User is admin = {IsAdmin}");
				UserId = result.UserId;
				AppAnalytics.Instance.SetUserId(result.UserId);
				AppAnalytics.Instance.TrackUserLevel(result.Level);
				ComponentFactory.Resolve<INotificationManager>().SubscribeToChannel(result.UserId.ToString().ToLower());
				ComponentFactory.Resolve<IAdService>().SetUserId(result.UserId);
				await _credentialService.SaveCredentials(request);
			}
			return result;
		}

		public void Reset()
		{
			Token = string.Empty;
		}
	}
	public abstract class BackendService<T> : BaseBackendService<T> where T : class
	{
		private readonly IAuthService _authService;

		protected virtual bool ShouldCheckAuthentication => true;

		protected BackendService()
		{
			_authService = ComponentFactory.Resolve<IAuthService>();
		}

		protected async Task<bool> CheckAuthentication(IRequestObject request)
		{
			await URLHelper.CheckNetworkState();
			if (string.IsNullOrEmpty(_authService.Token))
			{
				AuthResponse authResponse = await _authService.Login();
				if (authResponse == null || authResponse.Status != ResponseStatus.OK || !string.IsNullOrEmpty(authResponse.ErrorMessage))
				{
					request.Token = null;
					return false;
				}
			}
			request.Token = _authService.Token;
			return true;
		}

		protected async Task<TResult> CallApi<TRequest, TResult>(Func<TRequest, string, string, Task<TResult>> endPoint, TRequest request = null, bool showErrorMessage = true) where TRequest : class, IRequestObject, new() where TResult : class, IResponseObject, new()
		{
			if (request == null)
			{
				request = new TRequest();
			}
			TResult result = null;
			int counter = 0;
			while (result == null)
			{
				if (ShouldCheckAuthentication)
				{
					if (_authService.IsUserPunished)
					{
						return null;
					}
					if (!(await CheckAuthentication(request)))
					{
						return null;
					}
				}
				PrepareRequest(request);
				Sign(request);
				try
				{
					result = await endPoint(request, _deviceService.AppVersion, "youthlist,htmligm,friendlist,indtrainings");
				}
				catch (ApiException ex)
				{
					ApiException ex2 = ex;
					AppAnalytics.Instance.TrackError((Exception)(object)ex2);
				}
				catch (Exception ex3)
				{
					AppAnalytics.Instance.TrackError(ex3);
				}
				if (showErrorMessage)
				{
					await _popupService.ShowErrorIfAny(result);
				}
				if (result != null)
				{
					ResponseStatus status = result.Status;
					if ((uint)(status - 2) > 1u)
					{
						return result;
					}
					_authService.Reset();
				}
				counter++;
				if (counter > 2)
				{
					if (showErrorMessage)
					{
						await _popupService.ShowErrorMessageAsync();
					}
					return null;
				}
			}
			return result;
		}
	}
