	public abstract class BaseBackendService<T> where T : class
	{
		protected T _api;

		protected IPopupService _popupService;

		protected IDeviceService _deviceService;

		protected ICrypterService _crypterService;

		private readonly int _platformCode;

		protected abstract string ServiceUrl { get; }

		protected abstract string ServiceName { get; }

		protected BaseBackendService()
		{
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Expected O, but got Unknown
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			//IL_004a: Expected O, but got Unknown
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			_popupService = ComponentFactory.Resolve<IPopupService>();
			_deviceService = ComponentFactory.Resolve<IDeviceService>();
			_crypterService = ComponentFactory.Resolve<ICrypterService>();
			_api = RestService.For<T>(ServiceUrl + ServiceName, new RefitSettings((IHttpContentSerializer)new NewtonsoftJsonContentSerializer(), (IUrlParameterFormatter)null, (IFormUrlEncodedParameterFormatter)null));
			_platformCode = ((DeviceInfo.Platform == DevicePlatform.Android) ? 1 : 0);
			Log.Info($"[URL] - {this} - {ServiceUrl}{ServiceName}");
		}

		protected void PrepareRequest(IRequestObject request)
		{
			request.Locale = _deviceService.GetLocale();
			request.Platform = _platformCode;
			request.UtcOffset = TimeZoneInfo.Local.BaseUtcOffset.ToString();
			request.Culture = CultureInfo.CurrentUICulture.Name;
		}

		protected void Sign(IRequestObject request)
		{
			_crypterService.Sign(request);
		}
	}
	public class BaseCredentialService : ICredentialService
	{
		private const string LoginKey = "gt_login";

		private const string PasswordKey = "gt_password";

		private const string AuthMethodKey = "gt_authmethod";

		private const string FacebookIdKey = "facebook_id";

		public event EventHandler LoggedOut;

		public async Task<AuthRequest> GetCredentials()
		{
			AuthRequest result = new AuthRequest();
			AuthMethod authMethod = await GetAuthMethod();
			Log.Info($"> get creds for method: {authMethod}");
			switch (authMethod)
			{
			case AuthMethod.LoginAndPassword:
			{
				Tuple<string, string> tuple = await GetLoginAndPassword();
				result.Login = tuple.Item1;
				result.Password = tuple.Item2;
				if (string.IsNullOrEmpty(result.Login) || string.IsNullOrEmpty(result.Password))
				{
					authMethod = AuthMethod.None;
				}
				break;
			}
			case AuthMethod.Facebook:
			{
				AuthRequest authRequest = result;
				authRequest.AuthId = await GetFacebookId();
				if (string.IsNullOrEmpty(result.AuthId))
				{
					authMethod = AuthMethod.None;
				}
				break;
			}
			case AuthMethod.Apple:
			{
				AuthRequest authRequest = result;
				authRequest.AuthId = await GetAppleId();
				if (string.IsNullOrEmpty(result.AuthId))
				{
					authMethod = AuthMethod.None;
				}
				break;
			}
			}
			result.AuthMethod = (int)authMethod;
			Log.Info("> creds: login: " + result.Login + ", pass: " + result.Password + ", id: " + result.AuthId);
			return result;
		}

		protected virtual async Task<AuthMethod> GetAuthMethod()
		{
			AuthMethod result = AuthMethod.None;
			try
			{
				string text = await SecureStorage.GetAsync("gt_authmethod");
				if (!string.IsNullOrEmpty(text) && int.TryParse(text, out var result2))
				{
					result = (AuthMethod)result2;
				}
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
			return result;
		}

		protected virtual async Task<Tuple<string, string>> GetLoginAndPassword()
		{
			string login = string.Empty;
			string password = string.Empty;
			try
			{
				login = await SecureStorage.GetAsync("gt_login");
				password = await SecureStorage.GetAsync("gt_password");
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
			return new Tuple<string, string>(login, password);
		}

		protected virtual async Task<string> GetFacebookId()
		{
			string facebookID = string.Empty;
			try
			{
				facebookID = await SecureStorage.GetAsync("facebook_id");
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
			return facebookID;
		}

		protected virtual Task<string> GetAppleId()
		{
			return Task.FromResult(string.Empty);
		}

		public async Task<bool> SaveCredentials(AuthRequest auth)
		{
			_ = 2;
			try
			{
				await SecureStorage.SetAsync("gt_authmethod", auth.AuthMethod.ToString());
				switch ((AuthMethod)auth.AuthMethod)
				{
				case AuthMethod.LoginAndPassword:
					await UpdateLoginPassword(auth.Login, auth.Password);
					break;
				case AuthMethod.Facebook:
					await UpdateFacebookId(auth.AuthId);
					break;
				}
				return true;
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
				return false;
			}
		}

		public Task<bool> SaveCredentials(JsonUser user)
		{
			AuthMethod authMethod = AuthMethod.LoginAndPassword;
			string authId = string.Empty;
			if (!string.IsNullOrEmpty(user.AppleId))
			{
				authMethod = AuthMethod.Apple;
				authId = user.AppleId;
			}
			else if (!string.IsNullOrEmpty(user.FacebookId))
			{
				authMethod = AuthMethod.Facebook;
				authId = user.FacebookId;
			}
			return SaveCredentials(new AuthRequest
			{
				Login = user.ManagerName,
				Password = user.Password,
				AuthId = authId,
				AuthMethod = (int)authMethod
			});
		}

		public void Logout()
		{
			SecureStorage.RemoveAll();
			Preferences.Clear();
			ComponentFactory.Resolve<INotificationManager>().CancelNotification();
			URLHelper.SetServer(URLHelper.UseProd);
			this.LoggedOut?.Invoke(this, EventArgs.Empty);
		}

		public async Task UpdateLoginPassword(string login, string password)
		{
			if (!string.IsNullOrEmpty(login))
			{
				await SecureStorage.SetAsync("gt_login", login);
			}
			if (!string.IsNullOrEmpty(password))
			{
				await SecureStorage.SetAsync("gt_password", password);
			}
		}

		public async Task UpdateFacebookId(string userId)
		{
			await SecureStorage.SetAsync("facebook_id", userId);
		}

		public async Task<bool> IsLoggedIn()
		{
			AuthRequest authRequest = await GetCredentials();
			bool result = false;
			switch ((AuthMethod)authRequest.AuthMethod)
			{
			case AuthMethod.LoginAndPassword:
				result = !string.IsNullOrEmpty(authRequest.Login) && !string.IsNullOrEmpty(authRequest.Password);
				break;
			case AuthMethod.Facebook:
			case AuthMethod.Apple:
				result = !string.IsNullOrEmpty(authRequest.AuthId);
				break;
			}
			return result;
		}
	}
