	{
		private List<CountryData> _countries;

		protected override string ServiceName => "Common";

		protected override bool ShouldCheckAuthentication => false;

		public async Task<CountryData> GetDefaultCountry()
		{
			if (_countries == null)
			{
				await GetCountries();
			}
			string locale = ComponentFactory.Resolve<IDeviceService>().GetLocale();
			if (!string.IsNullOrEmpty(locale) && locale.Length >= 2)
			{
				locale = locale.Substring(locale.Length - 2).ToLower();
			}
			else
			{
				locale = "de";
			}
			return _countries.FirstOrDefault((CountryData x) => x.Short.ToLower() == locale) ?? _countries.FirstOrDefault((CountryData x) => x.Short == "de") ?? _countries.First();
		}

		public async Task<List<CountryData>> GetCountries()
		{
			if (_countries == null)
			{
				_countries = (await CallApi(_api.GetCountries, new RequestObject()))?.Countries;
			}
			return _countries;
		}

