		public List<JsonExtendedPlayer> CurrentStatePlayers { get; set; }

		public GT.Core.Json.JsonPlayer JsonPlayer
		{
			get
			{
				if (_jsonPlayer == null && JsonTeam != null && JsonTeam.Team != null)
				{
					string value = Preferences.Get("JsonPlayer" + JsonTeam.Team.ID, string.Empty);
					if (!string.IsNullOrEmpty(value))
					{
						_jsonPlayer = JsonConvert.DeserializeObject<GT.Core.Json.JsonPlayer>(value.Decompress());
					}
				}
				return _jsonPlayer;
			}
			set
			{
				_jsonPlayer = value;
				_jsonPlayerLastUpdate = GetDate();
				if (_deviceService.IsPad)
				{
					_notificationsService.NotifyObservers(_jsonPlayer, "JsonPlayer");
				}
				if (value != null && value.Players != null && JsonTeam != null && JsonTeam.Team != null)
				{
					string value2 = JsonConvert.SerializeObject((object)value);
					Preferences.Set("JsonPlayer" + JsonTeam.Team.ID, value2.Compress());
					if (string.IsNullOrEmpty(Preferences.Get("BeforeStatePlayers" + JsonTeam.Team.ID, string.Empty)))
					{
						BeforeStatePlayers = new List<JsonExtendedPlayer>(value.Players);
						string value3 = JsonConvert.SerializeObject((object)BeforeStatePlayers);
						if (!string.IsNullOrEmpty(value3))
						{
							Preferences.Set("BeforeStatePlayers" + JsonTeam.Team.ID, value3.Compress());
							Preferences.Set("CurrentStatePlayers" + JsonTeam.Team.ID, value3.Compress());
						}
						return;
					}
					string text = Preferences.Get("BeforeStatePlayers" + JsonTeam.Team.ID, string.Empty);
					if (!string.IsNullOrEmpty(text) && text.StartsWith("#cmp#"))
					{
						string text2 = text.Decompress();
						BeforeStatePlayers = JsonConvert.DeserializeObject<List<JsonExtendedPlayer>>(text2);
					}
					string text3 = Preferences.Get("CurrentStatePlayers" + JsonTeam.Team.ID, string.Empty);
					if (!string.IsNullOrEmpty(text3) && text3.StartsWith("#cmp#"))
					{
						string text4 = text3.Decompress();
						CurrentStatePlayers = JsonConvert.DeserializeObject<List<JsonExtendedPlayer>>(text4);
					}
					bool flag = false;
					if (!string.IsNullOrEmpty(text3) && CurrentStatePlayers != null)
					{
						foreach (JsonExtendedPlayer player in value.Players)
						{
							JsonExtendedPlayer jsonExtendedPlayer = CurrentStatePlayers.FirstOrDefault((JsonExtendedPlayer p) => p.ID.Equals(player.ID));
							if (jsonExtendedPlayer != null && (jsonExtendedPlayer.BallControl != player.BallControl || jsonExtendedPlayer.Cornerkick != player.Cornerkick || jsonExtendedPlayer.Defence != player.Defence || jsonExtendedPlayer.Duel != player.Duel || jsonExtendedPlayer.Experience != player.Experience || jsonExtendedPlayer.Flanks != player.Flanks || jsonExtendedPlayer.Form != player.Form || jsonExtendedPlayer.Freekick != player.Freekick || jsonExtendedPlayer.Header != player.Header || jsonExtendedPlayer.Keeper != player.Keeper || jsonExtendedPlayer.OneOnOne != player.OneOnOne || jsonExtendedPlayer.Passing != player.Passing || jsonExtendedPlayer.Penalty != player.Penalty || jsonExtendedPlayer.Playmaking != player.Playmaking || jsonExtendedPlayer.Shots != player.Shots || jsonExtendedPlayer.Speed != player.Speed))
							{
								flag = true;
								break;
							}
						}
					}
					else
					{
						flag = true;
					}
					if (flag)
					{
						string text5 = JsonConvert.SerializeObject((object)value.Players);
						if (!string.IsNullOrEmpty(text5))
						{
							text5 = text5.Compress();
						}
						if (string.IsNullOrEmpty(text3))
						{
							text3 = text5;
						}
						Preferences.Set("BeforeStatePlayers" + JsonTeam.Team.ID, text3);
						BeforeStatePlayers = CurrentStatePlayers;
						Preferences.Set("CurrentStatePlayers" + JsonTeam.Team.ID, text5);
						CurrentStatePlayers = value.Players;
					}
				}
				else if (JsonTeam != null && JsonTeam.Team != null)
				{
					string value4 = Preferences.Get("JsonPlayer" + JsonTeam.Team.ID, string.Empty);
					if (!string.IsNullOrEmpty(value4))
					{
						_jsonPlayer = JsonConvert.DeserializeObject<GT.Core.Json.JsonPlayer>(value4.Decompress());
					}
				}
			}
		}

