		public bool StadiumIsInBuildMode()
		{
			bool flag = false;
			List<JsonStadiumBuildingProperty> stadiumBuildingProperties = JsonStadium.StadiumBuildingProperties;
			List<JsonStadiumBuildingPropertyValue> stadiumBuildingPropertyValues = JsonStadium.StadiumBuildingPropertyValues;
			foreach (JsonStadiumBuildingProperty buildingProperty in stadiumBuildingProperties)
			{
				JsonStadiumBuildingPropertyValue jsonStadiumBuildingPropertyValue = stadiumBuildingPropertyValues.FirstOrDefault((JsonStadiumBuildingPropertyValue pv) => pv.StadiumBuildingID.Equals(buildingProperty.StadiumBuildingID) && pv.StadiumBuildingPropertyID.Equals(buildingProperty.ID));
				if (jsonStadiumBuildingPropertyValue != null && !string.IsNullOrEmpty(jsonStadiumBuildingPropertyValue?.BuildEnd))
				{
					flag = ParseDate(jsonStadiumBuildingPropertyValue.BuildEnd) >= GetDate();
					if (flag)
					{
						break;
					}
				}
			}
			return flag;
		}

