			return DateTime.Now.AddSeconds(ServerDateOffset);
		}

		public double GetServerDateOffset(string date)
		{
			DateTime result;
			try
			{
				result = DateTime.ParseExact(date, new string[28]
				{
					"MM/dd/yyyy hh:mm tt", "MM/d/yyyy hh:mm tt", "M/dd/yyyy hh:mm tt", "MM/dd/yy hh:mm tt", "MM/d/yy hh:mm tt", "M/dd/yy hh:mm tt", "mm/dd/yyyy hh:mm tt", "mm/d/yyyy hh:mm tt", "m/dd/yyyy hh:mm tt", "m/dd/yy hh:mm tt",
					"mm/d/yy hh:mm tt", "m/dd/yy hh:mm tt", "MM/dd/yyyy hh:mm:ss tt", "MM/d/yyyy hh:mm:ss tt", "M/dd/yyyy hh:mm:ss tt", "MM/dd/yy hh:mm:ss tt", "MM/d/yy hh:mm:ss tt", "M/dd/yy hh:mm:ss tt", "mm/dd/yyyy hh:mm:ss tt", "mm/d/yyyy hh:mm:ss tt",
					"m/dd/yyyy hh:mm:ss tt", "mm/dd/yy hh:mm:ss tt", "mm/d/yy hh:mm:ss tt", "m/dd/yy hh:mm:ss tt", "dd.MM.yyyy", "dd.MM.yyyy HH:mm:ss", "dd.MM.yyyy HH:mm", "dd/MM/yyyy HH:mm:ss"
				}, CultureInfo.CurrentCulture, DateTimeStyles.AssumeUniversal);
			}
			catch
			{
				DateTime.TryParse(date, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out result);
			}
			return (result - DateTime.Now).TotalSeconds;
		}

		public DateTime? ParseDate(string date)
		{
			return ParseDate(date, ignoreDST: false);
		}

		public DateTime? ParseDate(string date, bool ignoreDST)
		{
			DateTime result = DateTime.Now;
			if (!string.IsNullOrEmpty(date))
			{
				try
				{
					result = DateTime.ParseExact(date, new string[29]
					{
						"MM/dd/yyyy hh:mm tt", "MM/d/yyyy hh:mm tt", "M/dd/yyyy hh:mm tt", "MM/dd/yy hh:mm tt", "MM/d/yy hh:mm tt", "M/dd/yy hh:mm tt", "mm/dd/yyyy hh:mm tt", "mm/d/yyyy hh:mm tt", "m/dd/yyyy hh:mm tt", "m/dd/yy hh:mm tt",
						"mm/d/yy hh:mm tt", "m/dd/yy hh:mm tt", "MM/dd/yyyy hh:mm:ss tt", "MM/d/yyyy hh:mm:ss tt", "M/dd/yyyy hh:mm:ss tt", "MM/dd/yy hh:mm:ss tt", "MM/d/yy hh:mm:ss tt", "M/dd/yy hh:mm:ss tt", "mm/dd/yyyy hh:mm:ss tt", "mm/d/yyyy hh:mm:ss tt",
						"m/dd/yyyy hh:mm:ss tt", "mm/dd/yy hh:mm:ss tt", "mm/d/yy hh:mm:ss tt", "m/dd/yy hh:mm:ss tt", "dd.MM.yyyy", "dd.MM.yyyy HH:mm:ss", "dd.MM.yyyy HH:mm", "dd/MM/yyyy HH:mm", "dd/MM/yyyy"
					}, CultureInfo.CurrentCulture, DateTimeStyles.AssumeUniversal);
				}
				catch
				{
					DateTime.TryParse(date, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out result);
				}
			}
			if (result > DateTime.Parse("01.01.0001"))
			{
				if (ignoreDST && result.IsDaylightSavingTime())
				{
					result = result.AddHours(-1.0);
				}
				return result;
			}
			return null;
		}

