		public bool DateContainsText(string date)
		{
			if (!date.Contains("Misc#Today".Translate()) && !date.Contains("Misc#Tomorrow".Translate()))
			{
				return date.Contains("Misc#Yesterday".Translate());
			}
			return true;
		}

		public string GetDateText(DateTime? date, bool includeTime)
		{
			if (date.HasValue)
			{
				string text = date.Value.ToGTShortDateString();
				if (includeTime)
				{
					text = text + " " + date.Value.ToGTShortTimeString();
				}
				return text;
			}
			return null;
		}

		public string GetDateText(DateTime? date, bool includeTime, bool includeSeconds)
		{
			if (date.HasValue)
			{
				DateTimeFormatInfo dateTimeFormat = CultureInfo.CurrentCulture.DateTimeFormat;
				string text = "dd.MM.yy";
				string text2 = "HH:mm" + (includeSeconds ? ":ss" : string.Empty);
				if (date.Value.Date == GetDate().Date)
				{
					if (!includeTime)
					{
						return "Misc#Today".Translate();
					}
					return "Misc#Today".Translate() + " " + "Misc#At".Translate() + " " + date.Value.ToString(text2, dateTimeFormat);
				}
				if (date.Value.Date == GetDate().AddDays(1.0).Date)
				{
					if (!includeTime)
					{
						return "Misc#Tomorrow".Translate();
					}
					return "Misc#Tomorrow".Translate() + " " + "Misc#At".Translate() + " " + date.Value.ToString(text2, dateTimeFormat);
				}
				if (date.Value.Date == GetDate().AddDays(-1.0).Date)
				{
					if (!includeTime)
					{
						return "Misc#Yesterday".Translate();
					}
					return "Misc#Yesterday".Translate() + " " + "Misc#At".Translate() + " " + date.Value.ToString(text2, dateTimeFormat);
				}
				if (!includeTime)
				{
					return date.Value.ToString(text, dateTimeFormat);
				}
				return date.Value.ToString(text, dateTimeFormat) + " " + date.Value.ToString(text2, dateTimeFormat);
			}
			return null;
		}

		public List<League> SortLeagueTable(List<JsonExtendedTeam_League> team_League)
		{
			List<League> res = new List<League>();
			team_League.ForEach(delegate(JsonExtendedTeam_League tl)
			{
				res.Add(new League
				{
					TeamID = tl.TeamID,
					Position = tl.Position,
					TeamName = tl.TeamName,
					Matches = tl.MatchesHome + tl.MatchesAway,
					Wins = tl.WinsHome + tl.WinsAway,
					Draws = tl.DrawsHome + tl.DrawsAway,
					Losses = tl.LossesHome + tl.LossesAway,
					GoalsScored = tl.GoalsScoredHome + tl.GoalsScoredAway,
					GoalsAgainst = tl.GoalsAgainstHome + tl.GoalsAgainstAway,
					Points = tl.PointsHome + tl.PointsAway
				});
			});
			return res.OrderBy((League l) => l.Position).ToList();
		}

		public List<League> SortLeagueHomeTable(List<JsonExtendedTeam_League> team_League)
		{
			List<League> list = new List<League>();
			for (int i = 0; i < team_League.Count; i++)
			{
				League league = new League
				{
					TeamID = team_League[i].TeamID,
					Position = team_League[i].PositionHome,
					TeamName = team_League[i].TeamName,
					Matches = team_League[i].MatchesHome,
					Wins = team_League[i].WinsHome,
					Draws = team_League[i].DrawsHome,
					Losses = team_League[i].LossesHome,
					GoalsScored = team_League[i].GoalsScoredHome,
					GoalsAgainst = team_League[i].GoalsAgainstHome,
					Points = team_League[i].PointsHome
				};
				league.GoalsDifference = league.GoalsScored - league.GoalsAgainst;
				list.Add(league);
			}
			return list.OrderBy((League l) => l.Position).ToList();
		}

		public List<League> SortLeagueAwayTable(List<JsonExtendedTeam_League> team_League)
		{
			List<League> list = new List<League>();
			for (int i = 0; i < team_League.Count; i++)
			{
				League league = new League
				{
					TeamID = team_League[i].TeamID,
					Position = team_League[i].PositionAway,
					TeamName = team_League[i].TeamName,
					Matches = team_League[i].MatchesAway,
					Wins = team_League[i].WinsAway,
					Draws = team_League[i].DrawsAway,
					Losses = team_League[i].LossesAway,
					GoalsScored = team_League[i].GoalsScoredAway,
					GoalsAgainst = team_League[i].GoalsAgainstAway,
					Points = team_League[i].PointsAway
				};
				league.GoalsDifference = league.GoalsScored - league.GoalsAgainst;
				list.Add(league);
			}
			return list.OrderBy((League l) => l.Position).ToList();
		}

		public int GetManagerRankIndex(decimal ranking)
		{
			if (ranking >= 0m && ranking < 200m)
			{
				return 0;
			}
			if (ranking >= 200m && ranking < 400m)
			{
				return 1;
			}
			if (ranking >= 400m && ranking < 800m)
			{
				return 2;
			}
			if (ranking >= 800m && ranking < 1200m)
			{
				return 3;
			}
			if (ranking >= 1200m && ranking < 1600m)
			{
				return 4;
			}
			if (ranking >= 1600m && ranking < 2400m)
			{
				return 5;
			}
			if (ranking >= 2400m && ranking < 3200m)
			{
				return 6;
			}
			if (ranking >= 3200m && ranking < 4000m)
			{
				return 7;
			}
			if (ranking >= 4000m && ranking < 4800m)
			{
				return 8;
			}
			return 9;
		}

		public string GetManagerRanking(decimal ranking, bool raw = false)
		{
			string[] array = new string[10] { "Misc#ManagerRank#Layman", "Misc#ManagerRank#Trainee", "Misc#ManagerRank#Amateur", "Misc#ManagerRank#Competent", "Misc#ManagerRank#Experienced", "Misc#ManagerRank#Advanced", "Misc#ManagerRank#Professional", "Misc#ManagerRank#Champion", "Misc#ManagerRank#Elite", "Misc#ManagerRank#Master" };
			int num = GetManagerRankIndex(ranking).Clamp(0, array.Length - 1);
			string value = array[num];
			if (!raw)
			{
				return value.Translate();
			}
			ILocalizationService localizationService = ComponentFactory.Resolve<ILocalizationService>();
			return value.Translate(localizationService.DefaultLocale);
		}

		public string GetTeamMood(decimal mood)
		{
			if (mood >= 0m && mood < 20m)
			{
				return "Misc#Mood#Angry".Translate();
			}
			if (mood >= 20m && mood < 40m)
			{
				return "Misc#Mood#Stressed".Translate();
			}
			if (mood >= 40m && mood < 60m)
			{
				return "Misc#Mood#Pleased".Translate();
			}
			if (mood >= 60m && mood < 80m)
			{
				return "Misc#Mood#Happy".Translate();
			}
			return "Misc#Mood#Paradisiac".Translate();
		}

		public decimal GetPlayerStrengthByPositionID(JsonExtendedPlayer player, Guid positionID)
		{
			decimal result = default(decimal);
			if (positionID == Guids.Position_Keeper || positionID == Guids.Position_KeeperBench)
			{
				return player.KeeperStrength;
			}
			if (positionID == Guids.Position_DefenderCenter || positionID == Guids.Position_DefenderBench)
			{
				return player.DefenceCenterStrength;
			}
			if (positionID == Guids.Position_DefenderRight || positionID == Guids.Position_DefenderLeft)
			{
				return player.DefenceFlankStrength;
			}
			if (positionID == Guids.Position_MidfielderCenter || positionID == Guids.Position_MidfielderBench)
			{
				return player.MidCenterStrength;
			}
			if (positionID == Guids.Position_MidfielderRight || positionID == Guids.Position_MidfielderLeft)
			{
				return player.MidFlankStrength;
			}
			if (positionID == Guids.Position_StrikerCenter || positionID == Guids.Position_StrikerBench)
			{
				return player.StrikerCenterStrength;
			}
			if (positionID == Guids.Position_StrikerRight || positionID == Guids.Position_StrikerLeft)
			{
				return player.StrikerFlankStrength;
			}
			return result;
		}

		public decimal GetMoodModifier()
		{
			JsonMoodModifier[] obj = JsonDefinitions.MoodModifiers?.OrderByDescending((JsonMoodModifier x) => x.Mood)?.ToArray();
			decimal num = obj?.LastOrDefault()?.Modifier ?? 1m;
			int mood = (JsonTeam?.Team?.Mood).GetValueOrDefault();
			return obj?.FirstOrDefault((JsonMoodModifier x) => x.Mood <= mood)?.Modifier ?? num;
		}

		public int GetFavouritePositionIndex(JsonExtendedPlayer player)
		{
			int result = 1;
			switch (player.Position)
			{
