				result = "Midfielder".Translate();
			}
			if (position == 0)
			{
				result = "Keeper".Translate();
			}
			if (position == 5 || position == 6)
			{
				result = "Striker".Translate();
			}
			return result;
		}

		private Skill GetPlayerMainSkill(JsonExtendedPlayer player)
		{
			switch (player.Position)
			{
			case 0:
				return new Skill
				{
					IsMain = true,
					Name = "Keeper".Translate(),
					Value = player.Keeper
				};
			case 1:
			case 2:
				return new Skill
				{
					IsMain = true,
					Name = "Defence".Translate(),
					Value = player.Defence
				};
			case 3:
			case 4:
				return new Skill
				{
					IsMain = true,
					Name = "Playmaking".Translate(),
					Value = player.Playmaking
				};
			default:
				return new Skill
				{
					IsMain = true,
					Name = "Shots".Translate(),
					Value = player.Shots
				};
			}
		}

		private List<Skill> GetPlayerBonusSkills(JsonExtendedPlayer player)
		{
			if (player.BonusSkills == null || player.BonusSkills.Count == 0)
			{
				return new List<Skill>();
			}
			return player.BonusSkills.Select(delegate(Guid x)
			{
				Skill skillFromSkillID = GetSkillFromSkillID(x, player);
				skillFromSkillID.IsBonus = true;
				return skillFromSkillID;
			}).ToList();
		}

