			IEnumerable<Skill> collection = from x in GetPlayerBonusSkills(player)
				where x.Name != mainSkill.Name
				select x;
			List<Skill> skills = new List<Skill>();
			skills.Add(mainSkill);
			skills.AddRange(collection);
			IEnumerable<Skill> collection2 = new List<Skill>
