				},
				new Skill
				{
					Name = "Shots".Translate(),
					Value = player.Shots
				},
				new Skill
				{
					Name = "Passing".Translate(),
					Value = player.Passing
				},
				new Skill
				{
					Name = "BallControl".Translate(),
					Value = player.BallControl
				},
				new Skill
				{
					Name = "Duel".Translate(),
					Value = player.Duel
				},
				new Skill
				{
					Name = "OneOnOne".Translate(),
					Value = player.OneOnOne
				},
				new Skill
				{
					Name = "Header".Translate(),
					Value = player.Header
				},
				new Skill
				{
					Name = "Speed".Translate(),
					Value = player.Speed
				},
				new Skill
				{
					Name = "Flanks".Translate(),
					Value = player.Flanks
				},
				new Skill
				{
					Name = "Cornerkick".Translate(),
					Value = player.Cornerkick
				},
				new Skill
				{
					Name = "Freekick".Translate(),
					Value = player.Freekick
				},
				new Skill
				{
					Name = "Penalty".Translate(),
					Value = player.Penalty
				}
			}.Where((Skill x) => !skills.Any((Skill s) => s.Name == x.Name));
			skills.AddRange(collection2);
			return skills;
		}

