		public string GetHomeTrikot(Guid teamID)
		{
			string result = "trikot0";
			List<JsonTeam_Trikot> list = new List<JsonTeam_Trikot>();
			if (teamID == JsonTeam.Team.ID)
			{
				list = JsonTeam.Trikots;
			}
			else if (JsonTeamUI != null)
			{
				list = JsonTeamUI.Trikots;
			}
			if (list != null)
			{
				JsonTeam_Trikot homeTrikot = list.FirstOrDefault((JsonTeam_Trikot t) => t.IsHome.Equals(obj: true));
				if (homeTrikot != null)
				{
					GT.Core.Json.Member.JsonTrikot jsonTrikot = JsonDefinitions.Trikots.FirstOrDefault((GT.Core.Json.Member.JsonTrikot t) => t.ID.Equals(homeTrikot.TrikotID));
					if (jsonTrikot != null)
					{
						result = jsonTrikot.Name;
					}
				}
			}
			return result;
		}

