		public decimal GetStadiumSize(bool isMe)
		{
			GT.Core.Json.JsonStadium jsonStadium = JsonStadium;
			if (!isMe)
			{
				jsonStadium = JsonStadiumUI;
			}
			if (jsonStadium != null && jsonStadium.StadiumBuildingProperties != null)
			{
				IEnumerable<JsonStadiumBuildingProperty> enumerable = jsonStadium.StadiumBuildingProperties.Where((JsonStadiumBuildingProperty s) => s.ID.Equals(Guid.Parse("6841898a-1a0a-4b66-90e4-f52cf4720fb8")) || s.ID.Equals(Guid.Parse("8bfa436e-5080-4732-82bf-9279794e8bb7")) || s.ID.Equals(Guid.Parse("6ad08b4e-c787-4ff3-8517-c67dfdb27bcd")));
				decimal result = default(decimal);
				if (jsonStadium.StadiumBuildingPropertyValues != null)
				{
					foreach (JsonStadiumBuildingProperty property in enumerable)
					{
						JsonStadiumBuildingPropertyValue jsonStadiumBuildingPropertyValue = jsonStadium.StadiumBuildingPropertyValues.FirstOrDefault((JsonStadiumBuildingPropertyValue s) => s.StadiumBuildingPropertyID.Equals(property.ID));
						if (jsonStadiumBuildingPropertyValue != null)
						{
							result += (decimal)jsonStadiumBuildingPropertyValue.CurrentValue;
						}
					}
				}
				return result;
			}
			return 0m;
		}

		public int GetStadiumLevelID()
		{
			return GetStadiumLevelID(isMe: true);
		}

		public int GetStadiumLevelID(bool isMe)
		{
			decimal stadiumSize = GetStadiumSize(isMe);
			return GetStadiumLevelIDBySize(Convert.ToInt32(stadiumSize));
		}

		public int GetStadiumLevelIDBySize(int stadiumSize)
		{
			if (stadiumSize <= 5000)
			{
				return 1;
			}
			if (stadiumSize > 5000 && stadiumSize <= 15000)
			{
				return 2;
			}
			if (stadiumSize > 15000 && stadiumSize <= 30000)
			{
				return 3;
			}
			if (stadiumSize > 30000 && stadiumSize <= 50000)
			{
				return 4;
			}
			return 5;
		}

		public int GetStadiumLevelID2(bool isMe)
		{
			decimal stadiumSize = GetStadiumSize(isMe);
			if (stadiumSize <= 5000m)
			{
				return 1;
			}
			if (stadiumSize > 5000m && stadiumSize <= 10000m)
			{
				return 2;
			}
			if (stadiumSize > 10000m && stadiumSize <= 20000m)
			{
				return 3;
			}
			if (stadiumSize > 20000m && stadiumSize <= 30000m)
			{
				return 4;
			}
			if (stadiumSize > 30000m && stadiumSize <= 40000m)
			{
				return 5;
			}
			if (stadiumSize > 40000m && stadiumSize <= 50000m)
			{
				return 6;
			}
			if (stadiumSize > 50000m && stadiumSize <= 60000m)
			{
				return 7;
			}
			if (stadiumSize > 60000m && stadiumSize <= 70000m)
			{
				return 8;
			}
			if (stadiumSize > 70000m && stadiumSize <= 90000m)
			{
				return 9;
			}
			if (stadiumSize > 90000m && stadiumSize <= 125000m)
			{
				return 10;
			}
			return 11;
		}
	}
	public class LeagueComparer : IComparer<League>
	{
		public int Compare(League x, League y)
		{
			if (x.Points > y.Points)
			{
				return 1;
			}
			if (x.Points < y.Points)
			{
				return -1;
			}
			if (x.GoalsDifference > y.GoalsDifference)
			{
				return 1;
			}
			if (x.GoalsDifference < y.GoalsDifference)
			{
				return -1;
			}
			return string.Compare(x.TeamName, y.TeamName);
		}
	}
	public class CrypterService : ICrypterService
	{
		private const string _salt = "21F090935F6E49C2C797F69BBAAD8402ABD2EE0B667A8B44EA7DD4374267A75D7AD972A119482D15A4127461DB1DC347C1A63AE5F1CCFAACFF1B72A7F0A281B";

		public void Sign(IRequestObject obj)
		{
			obj.Signature = null;
			obj.Signature = CreateMD5(JsonConvert.SerializeObject((object)obj));
		}

		public string CreateMD5(string value)
		{
			MD5CryptoServiceProvider mD5CryptoServiceProvider = new MD5CryptoServiceProvider();
			StringBuilder stringBuilder = new StringBuilder();
			byte[] bytes = Encoding.ASCII.GetBytes(value + "21F090935F6E49C2C797F69BBAAD8402ABD2EE0B667A8B44EA7DD4374267A75D7AD972A119482D15A4127461DB1DC347C1A63AE5F1CCFAACFF1B72A7F0A281B");
			byte[] array = mD5CryptoServiceProvider.ComputeHash(bytes);
			foreach (byte b in array)
			{
				stringBuilder.Append(b.ToString("x2").ToLower());
			}
			return stringBuilder.ToString();
		}
	}
