		public async Task<int> GetLadderLineupStatus()
		{
			LineupStatusInfo lineupStatusInfo = new LineupStatusInfo();
			lineupStatusInfo.Matches = new MatchInfo[1]
			{
				new MatchInfo
				{
					IsLadder = true
				}
			};
			LineupStatusInfo info = lineupStatusInfo;
			LineupStatusData lineupStatusData = await GetLineupStatus(info);
			if (lineupStatusData.Matches != null && lineupStatusData.Matches.Length != 0)
			{
				return lineupStatusData.Matches[0].Warning;
			}
			return 2;
		}
	}
