	public class NavigationEventArgs : EventArgs
	{
		public ScreenIdentifier Screen { get; }

		public int TabIndex { get; }

		public NavigationEventArgs(ScreenIdentifier screen, int tabIndex)
		{
			Screen = screen;
			TabIndex = tabIndex;
		}
	}
	public class NavigationService : INavigationService
	{
		private readonly Dictionary<ScreenIdentifier, Type> _screenTypes;

		private readonly Dictionary<ScreenIdentifier, int> _screenTabs;

		private readonly Dictionary<ScreenIdentifier, Func<Task<bool>>> _screenCanLeave;

		private INavigator _navigator;

		private ScreenIdentifier _lastScreen;

		private ScreenIdentifier _currentScreen;

		public event EventHandler<NavigationEventArgs> Navigated;

		public NavigationService()
		{
			_screenTypes = new Dictionary<ScreenIdentifier, Type>();
			_screenTabs = new Dictionary<ScreenIdentifier, int>();
			_screenCanLeave = new Dictionary<ScreenIdentifier, Func<Task<bool>>>();
		}

		private int GetScreenTab(ScreenIdentifier screen)
		{
			if (!_screenTabs.TryGetValue(screen, out var value))
			{
				return 0;
			}
			return value;
		}

		public void NavigateTo(ScreenIdentifier screen, int tabIndex)
		{
			NavigateTo(screen);
			MoveToTab(tabIndex);
		}

		public void NavigateTo(ScreenIdentifier screen)
		{
			NavigateTo(screen, goForward: true);
		}

		private void NavigateTo(ScreenIdentifier screen, bool goForward)
		{
			if (screen != ScreenIdentifier.None && _currentScreen != screen)
			{
				ShellViewModel shellViewModel = ComponentFactory.Resolve<ShellViewModel>();
				shellViewModel.Title = string.Empty;
				shellViewModel.CharacterImageName = string.Empty;
				_lastScreen = (goForward ? _currentScreen : ScreenIdentifier.None);
				_currentScreen = screen;
				if (_screenTypes.TryGetValue(screen, out var value))
				{
					ComponentFactory.Resolve<ResourcesViewModel>().IsPurchaseAvailable = screen != ScreenIdentifier.Shop;
					_navigator.NavigateTo(value, screen.IsGameScreen(), screen.IsModal());
				}
				OnNavigated(screen, GetScreenTab(screen));
				AppAnalytics.Instance.TrackScreen(screen.ToString());
				NotificationHelper.Instance.UpdateInactivity();
			}
		}

		public void MoveToTab(int tabIndex)
		{
			if (tabIndex != GetScreenTab(_currentScreen))
			{
				_navigator.SelectTab(tabIndex);
				_screenTabs[_currentScreen] = tabIndex;
				OnNavigated(_currentScreen, tabIndex);
			}
		}

		private void OnNavigated(ScreenIdentifier screen, int tabIndex)
		{
			this.Navigated?.Invoke(this, new NavigationEventArgs(screen, tabIndex));
		}

		public void NavigateBack()
		{
			if (_lastScreen != ScreenIdentifier.None)
			{
				NavigateBackTask().FireAndForgetSafeAsync();
			}
		}

		private async Task NavigateBackTask()
		{
			Func<Task<bool>> value;
			bool flag = _screenCanLeave.TryGetValue(_currentScreen, out value) && value != null;
			if (flag)
			{
				flag = !(await value());
			}
			if (!flag && !_lastScreen.IsModal())
			{
				NavigateTo(_lastScreen, goForward: false);
			}
		}

		public void SetNavigator(INavigator navigator)
		{
			_navigator = navigator;
		}

		public void Register(ScreenIdentifier screen, Type viewType)
		{
			_screenTypes[screen] = viewType;
		}

		public ScreenIdentifier GetCurrentScreen()
		{
			return _currentScreen;
		}

		public void ReportTabChanged(int tabIndex)
		{
			_screenTabs[_currentScreen] = tabIndex;
			OnNavigated(_currentScreen, tabIndex);
		}

		public void SetCanLeave(ScreenIdentifier screen, Func<Task<bool>> canLeave)
		{
			_screenCanLeave[screen] = canLeave;
		}

		public int GetCurrentTabIndex()
		{
			return GetScreenTab(_currentScreen);
		}
	}
