	public struct NotificationData
	{
		private const string _specialId = "special_id";

		public readonly string Id;

		public readonly string Title;

		public readonly string Message;

		public readonly string Icon;

		public readonly string Parameter;

		public readonly ScreenIdentifier Screen;

		public readonly int Position;

		public bool IsSpecial => Id == "special_id";

		public NotificationData(string id, string title, string message, string icon, string parameter = "", string screen = "", string position = "")
		{
			Id = id;
			Title = title;
			Message = message;
			Icon = icon;
			Parameter = parameter;
			Screen = (Enum.TryParse<ScreenIdentifier>(screen, out var result) ? result : ScreenIdentifier.None);
			Position = (int.TryParse(position, out var result2) ? result2 : 0);
		}

		public NotificationData(string inAppMessage, ScreenIdentifier screen = ScreenIdentifier.None)
		{
			Id = "special_id";
			Title = string.Empty;
			Icon = string.Empty;
			Message = inAppMessage;
			Parameter = string.Empty;
			Screen = screen;
			Position = 0;
		}
	}
	public class NotificationHelper
	{
		private static class NotificationId
		{
			public static string Stadium => "Stadium";

			public static string MainSponsor => "MainSponsor";

			public static string SecondarySponsor => "SecondarySponsor";

			public static string SeasonStart1 => "SeasonStart1";

			public static string SeasonStart2 => "SeasonStart2";

			public static string SeasonEnd1 => "SeasonEnd1";

			public static string SeasonEnd2 => "SeasonEnd2";

			public static string Training(Guid playerId)
			{
				return $"{playerId}-training";
			}

			public static string Contract(Guid playerId, bool before)
			{
				return string.Format("{0}-contract{1}", playerId, before ? "-before" : string.Empty);
			}

			public static string Transfermarket5(Guid playerId)
			{
				return $"{playerId}-transfer5";
			}

			public static string Transfermarket30(Guid playerId)
			{
				return $"{playerId}-transfer30";
			}

			public static string Inactivity(int number)
			{
				return $"Inactivity-{number}";
			}
		}

		private const string InactivityUpdatedKey = "inactivity_updated";

		private const string SeasonUpdatedKey = "season_updated";

		private const int NotificationInactivityCount = 3;

		private readonly IPreferencesService _preferencesService;

		private readonly INotificationManager _notificationManager;

		private static readonly Lazy<NotificationHelper> _instance = new Lazy<NotificationHelper>(() => new NotificationHelper());

		public static NotificationHelper Instance => _instance.Value;

		private NotificationHelper()
		{
			_preferencesService = ComponentFactory.Resolve<IPreferencesService>();
			_notificationManager = ComponentFactory.Resolve<INotificationManager>();
		}

		public void RemoveAllPlayerNotifications(Guid playerId)
		{
		}

		public void UpdateStadium(string buildingName = null, DateTime endDate = default(DateTime))
		{
			_notificationManager.CancelNotification(NotificationId.Stadium);
			if (_preferencesService.IsBuildingCompleteEnabled && !(endDate == default(DateTime)))
			{
				UpdateStadiumTask(buildingName, endDate).FireAndForgetSafeAsync();
			}
		}

		private async Task UpdateStadiumTask(string buildingName, DateTime endDate)
		{
			if (string.IsNullOrEmpty(buildingName) && endDate != default(DateTime))
			{
				UnderConstructionResponse underConstructionResponse = await ComponentFactory.Resolve<INewStadiumService>().GetUnderConstruction();
				if (underConstructionResponse == null || underConstructionResponse.Status != ResponseStatus.OK || underConstructionResponse.Building == null)
				{
					return;
				}
				buildingName = underConstructionResponse.Building.Name;
				endDate = underConstructionResponse.Building.BuildEndValue;
			}
			_notificationManager.SendNotification(new NotificationData(NotificationId.Stadium, "LocalNotificationBuildingCompleteTitle".Translate(), buildingName + ". " + "LocalNotificationBuildingCompleteBody".Translate(), "menu_stadium"), endDate.ToLocalTime());
		}

		public void AddTransfermarket(TransfermarketPlayerData player)
		{
			_notificationManager.CancelNotification(NotificationId.Transfermarket5(player.ID), NotificationId.Transfermarket30(player.ID));
			if (_preferencesService.IsAuctionEndSoonEnabled)
			{
				_notificationManager.SendNotification(new NotificationData(NotificationId.Transfermarket5(player.ID), "LocalNotificationAuctionEndsTitle".Translate(), string.Format("LocalNotificationAuctionEnds5mBody".Translate(), player.Name), "menu_transfermarket"), player.EndDateValue.ToLocalTime().AddMinutes(-5.0));
				_notificationManager.SendNotification(new NotificationData(NotificationId.Transfermarket30(player.ID), "LocalNotificationAuctionEndsTitle".Translate(), string.Format("LocalNotificationAuctionEnds30mBody".Translate(), player.Name), "menu_transfermarket"), player.EndDateValue.ToLocalTime().AddMinutes(-30.0));
			}
		}

		public void UpdateInactivity(bool forceUpdate = false)
		{
			if (!forceUpdate && "inactivity_updated".WasUpdatedToday())
			{
				return;
			}
			_notificationManager.CancelNotification((from x in Enumerable.Range(1, 3)
				select NotificationId.Inactivity(x)).ToArray());
			if (!_preferencesService.IsReturnInviteEnabled)
			{
				return;
			}
			DateTime now = DateTime.Now;
			for (int num = 1; num <= 3; num++)
			{
				string title;
				string message;
				switch (num)
				{
				case 1:
					title = "LocalNotificationInactive1Title".Translate();
					message = "LocalNotificationInactive1Body".Translate();
					break;
				case 2:
					title = "LocalNotificationInactive2Title".Translate();
					message = "LocalNotificationInactive2Body".Translate();
					break;
				default:
					title = "LocalNotificationInactive3Title".Translate();
					message = "LocalNotificationInactive3Body".Translate();
					break;
				}
				_notificationManager.SendNotification(new NotificationData(NotificationId.Inactivity(num), title, message, string.Empty), now.AddDays(num * 3));
			}
		}

		public void UpdateNewSeason(string currentSeasonStartDate = null)
		{
			if (!"season_updated".WasUpdatedToday())
			{
				_notificationManager.CancelNotification(NotificationId.SeasonStart1, NotificationId.SeasonStart2, NotificationId.SeasonEnd1, NotificationId.SeasonEnd2);
				if (_preferencesService.IsSeasonInformationEnabled)
				{
					UpdateNewSeasonTask(currentSeasonStartDate).FireAndForgetSafeAsync();
				}
			}
		}

		private async Task UpdateNewSeasonTask(string currentSeasonStartDate)
		{
			if (string.IsNullOrEmpty(currentSeasonStartDate))
			{
				currentSeasonStartDate = await ComponentFactory.Resolve<ICommonService>().GetSeasonInfo();
			}
			DateTime dateTime = currentSeasonStartDate.ParseToDate().ToLocalTime().Date.AddHours(9.0);
			DateTime dateTime2 = dateTime.AddDays(30.0);
			_notificationManager.SendNotification(new NotificationData(NotificationId.SeasonStart1, "LocalNotificationSeasonStartTitle".Translate(), "LocalNotificationSeasonStart1dayBody".Translate(), string.Empty), dateTime2.AddDays(-1.0));
			_notificationManager.SendNotification(new NotificationData(NotificationId.SeasonEnd2, "LocalNotificationSeasonStartTitle".Translate(), "LocalNotificationSeasonStart3dayBody".Translate(), string.Empty), dateTime2.AddDays(-3.0));
			_notificationManager.SendNotification(new NotificationData(NotificationId.SeasonEnd1, "LocalNotificationSeasonEndTitle".Translate(), "LocalNotificationSeasonEndBody".Translate(), string.Empty), dateTime.AddDays(25.0));
			_notificationManager.SendNotification(new NotificationData(NotificationId.SeasonEnd2, "LocalNotificationSeasonEndTitle".Translate(), "LocalNotificationSeasonEndBody".Translate(), string.Empty), dateTime.AddDays(28.0));
		}
	}
