	public class ResourceService : IResourceService
	{
		private readonly INewTeamService _teamService;

		private readonly IPopupService _popupService;

		private IResourceUpdatedDelegate _resourceUpdatedDelegate;

		public static IResourceService Current => ComponentFactory.Resolve<IResourceService>();

		public long Money { get; private set; }

		public long GTStars { get; private set; }

		public long Medipacks { get; private set; }

		public bool IsSuspended { get; set; }

		public ResourceService(INewTeamService teamService, IPopupService popupService)
		{
			_teamService = teamService;
			_popupService = popupService;
		}

		public void Update()
		{
			UpdateAsync().FireAndForgetSafeAsync();
		}

		public async Task UpdateAsync()
		{
			if (IsSuspended)
			{
				return;
			}
			Money = 0L;
			GTStars = 0L;
			Medipacks = 0L;
			while (Money == 0L && GTStars == 0L && Medipacks == 0L)
			{
				ResourcesResponse resourcesResponse = await _teamService.GetMyResources();
				if (resourcesResponse == null)
				{
					return;
				}
				Money = (long)resourcesResponse.Money;
				GTStars = (long)resourcesResponse.GTStars;
				Medipacks = (long)resourcesResponse.Medipacks;
			}
			_resourceUpdatedDelegate?.Updated();
		}

		public async Task<bool> Spent(int value, bool isPremium, string title = null, string question = null, Character character = Character.Coach)
		{
			return (!isPremium) ? (await SpentMoney(value)) : (await SpentGTStars(value, title, question, character));
		}

		public async Task<bool> SpentMoney(int value)
		{
			await UpdateAsync();
			if (Money < value)
			{
				_popupService.DisplayNoMoney();
				return false;
			}
			Money -= value;
			_resourceUpdatedDelegate?.Updated();
			return true;
		}

		public async Task<bool> SpentMoney(int value, string title = null, string question = null, Character character = Character.Coach)
		{
			await UpdateAsync();
			if (Money < value)
			{
				_popupService.DisplayNoMoney();
				return false;
			}
			bool flag = string.IsNullOrEmpty(question);
			if (!flag)
			{
				flag = await _popupService.ShowYesNoMessageAsync(title, question, character);
			}
			if (flag)
			{
				Money -= value;
				_resourceUpdatedDelegate?.Updated();
				return true;
			}
			return false;
		}

		public async Task<bool> SpentGTStars(int value, string title = null, string question = null, Character character = Character.Coach)
		{
			if (!(await CheckGTStars(value)))
			{
				return false;
			}
			bool flag = string.IsNullOrEmpty(question);
			if (!flag)
			{
				flag = await _popupService.ShowYesNoMessageAsync(title, question, character);
			}
			if (flag)
			{
				AddGTStars(-value);
				return true;
			}
			return false;
		}

		public async Task<bool> CheckGTStars(int value)
		{
			await UpdateAsync();
			if (GTStars < value)
			{
				_popupService.DisplayNoGTStars();
				return false;
			}
			return true;
		}

		public void AddGTStars(int value)
		{
			GTStars += value;
			_resourceUpdatedDelegate?.Updated();
		}

		public async Task<bool> SpentMedipacks(int value, string title = null, string question = null, Character character = Character.Coach)
		{
			await UpdateAsync();
			if (Medipacks < value)
			{
				_popupService.DisplayNoMedipacks();
				return false;
			}
			bool flag = string.IsNullOrEmpty(question);
			if (!flag)
			{
				flag = await _popupService.ShowYesNoMessageAsync(title, question, character);
			}
			if (flag)
			{
				AddMedipacks(-value);
				return true;
			}
			return false;
		}

		public void AddMedipacks(int value)
		{
			Medipacks += value;
			_resourceUpdatedDelegate?.Updated();
		}

		public void SetUpdatedDelegate(IResourceUpdatedDelegate resourceUpdatedDelegate)
		{
			_resourceUpdatedDelegate = resourceUpdatedDelegate;
		}
	}
