	[DataContract]
	public class TransfermarketBid : RequestObject
	{
		[DataMember(EmitDefaultValue = false)]
		public Guid TransfermarketId { get; set; }
	}
	public class TransfermarketBidEventArgs : EventArgs
	{
		public JsonRealtimeBid BidInfo { get; }

		public TransfermarketBidEventArgs(JsonRealtimeBid bid)
		{
			BidInfo = bid;
		}
	}
	public class TransfermarketBidService : ITransfermarketBidService
	{
		private readonly Random _rnd;

		private readonly HubConnection _hub;

		private bool _isConnected;

		public event EventHandler<TransfermarketBidEventArgs> BidUpdated;

		public TransfermarketBidService()
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Expected O, but got Unknown
			_rnd = new Random();
			_hub = HubConnectionBuilderHttpExtensions.WithUrl((IHubConnectionBuilder)new HubConnectionBuilder(), URLHelper.NewBackendUrl + "/auc").Build();
			_hub.Closed += OnHubClosed;
			HubConnectionExtensions.On<JsonRealtimeBid>(_hub, "Bidded", (Action<JsonRealtimeBid>)BidReceivedHub);
		}

		private void BidReceivedHub(JsonRealtimeBid bidInfo)
		{
			Log.Info($"*** Bid updated from Hub {bidInfo.AuctionID} = {bidInfo.Bid} ({bidInfo.BidTeamName}) = {bidInfo.EndDate}");
			BidReceived(bidInfo);
		}

		private void BidReceived(JsonRealtimeBid bidInfo)
		{
			EventHandler<TransfermarketBidEventArgs> eventHandler = this.BidUpdated;
			if (eventHandler != null)
			{
				eventHandler?.Invoke(this, new TransfermarketBidEventArgs(bidInfo));
			}
		}

		private async Task OnHubClosed(Exception ex)
		{
			Log.Info("*** hub connection closed: " + ex?.Message);
			_isConnected = false;
			if (ex != null)
			{
				await Task.Delay(100 + _rnd.Next(200));
				await Connect();
			}
		}

		public async Task Connect()
		{
			if (_isConnected || (int)_hub.State != 0)
			{
				return;
			}
			try
			{
				await _hub.StartAsync(default(CancellationToken));
				_isConnected = true;
				Log.Info("*** hub connected: " + _hub.ConnectionId);
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
				Log.Info("*** hub connection error: " + ex.Message);
			}
		}
	}
