		private async Task<UpdateUserResponse> UpdateUser(UpdateUserRequest request)
		{
			return await CallApi(_api.UpdateUser, request);
		}

		public async Task<bool> UpdateUser(UserData userData)
		{
			IShell shell = ComponentFactory.Resolve<IShell>();
			shell.StartProgress();
			UpdateUserResponse updateUserResponse = await UpdateUser(new UpdateUserRequest
			{
				UserData = userData
			});
			shell.StopProgress();
			if (updateUserResponse == null || updateUserResponse.Status != ResponseStatus.OK)
			{
				return false;
			}
			if (updateUserResponse.EmailReward > 0m || updateUserResponse.FacebookReward > 0m)
			{
				string message = ((updateUserResponse.EmailReward > 0m) ? "ShopSetEmail" : "ShopSetFacebook").Translate();
				TutorialPopupViewModel popupViewModel = new TutorialPopupViewModel("ShopSuccessTitle".Translate(), message, new ProductData
				{
					GTStars = (int)(updateUserResponse.EmailReward + updateUserResponse.FacebookReward)
				});
				await ComponentFactory.Resolve<IPopupService>().ShowPopupAsync(popupViewModel);
			}
			if (!string.IsNullOrEmpty(userData.FacebookId))
			{
				ICredentialService credentialService = ComponentFactory.Resolve<ICredentialService>();
				AuthRequest authRequest = await credentialService.GetCredentials();
				if (authRequest.AuthMethod == 1)
				{
					authRequest.AuthId = userData.FacebookId;
					await credentialService.SaveCredentials(authRequest);
				}
			}
			return true;
		}

		public async Task<bool> ShowUpdateUserPopup(UserData userData)
		{
			IPopupService popupService = ComponentFactory.Resolve<IPopupService>();
			UserDataPopupViewModel popup = new UserDataPopupViewModel
			{
				Login = userData.Name,
				Email = userData.Email
			};
			if (await popupService.ShowPopupAsync(popup) != PopupResult.Done)
			{
				return false;
			}
			UserData newUser = new UserData
			{
				Name = popup.Login,
				Email = popup.Email,
				Password = (string.IsNullOrEmpty(popup.Password) ? null : _crypterService.CreateMD5(popup.Password))
			};
			if (!(await UpdateUser(newUser)))
			{
				return false;
			}
			if (userData.Name != newUser.Name || !string.IsNullOrEmpty(popup.Password))
			{
				ICredentialService credentialService = ComponentFactory.Resolve<ICredentialService>();
				AuthRequest authRequest = await credentialService.GetCredentials();
				if (authRequest.AuthMethod == 0)
				{
					authRequest.Login = ((userData.Name != newUser.Name) ? newUser.Name : authRequest.Login);
					authRequest.Password = ((!string.IsNullOrEmpty(popup.Password)) ? newUser.Password : authRequest.Password);
					await credentialService.SaveCredentials(authRequest);
				}
			}
			string email = userData.Email;
			userData.Name = newUser.Name;
			userData.Email = newUser.Email;
			if (_helpshiftUserData != null && _helpshiftUserData.Status == ResponseStatus.OK)
			{
				_helpshiftUserData.ManagerName = newUser.Name;
			}
			return newUser.Email != email;
		}

		public async Task<bool> DeleteAccount()
		{
			if (!(await _popupService.ShowYesNoMessageAsync("DeleteAccount".Translate(), "DeleteAccountMessage".Translate(), Character.Anna)))
			{
				return false;
			}
			HelpshiftUserResponse userInfo = await GetHelpshiftUserInfo();
			string text = await _popupService.ShowEntryPopupAsync("DeleteAccount".Translate(), string.Format("DeleteAccountConfirm".Translate(), userInfo.ManagerName), "DeleteAccount".Translate());
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			if (text.ToLower() != userInfo.ManagerName.ToLower())
			{
				await _popupService.ShowOkMessageAsync("DeleteAccount".Translate(), string.Format("DeleteAccountVerificationFailed".Translate(), text, userInfo.ManagerName), Character.AnnaPoint);
				return false;
			}
			IShell shell = ComponentFactory.Resolve<IShell>();
			shell.StartProgress();
			ResponseObject responseObject = await CallApi(_api.DeleteAccount, new RequestObject());
			shell.StopProgress();
			if (responseObject == null || responseObject.Status != ResponseStatus.OK)
			{
				return false;
			}
			await _popupService.ShowOkMessageAsync("DeleteAccountSuccessTitle".Translate(), "DeleteAccountSuccessMessage".Translate(), Character.AnnaCheer);
			return true;
		}
	}
