	public class TutorialManager
	{
		private const string StartTopicId = "General#1";

		private const string ResetTopicId = "";

		private const string PadTopicId = "IpadStart";

		private const string PadFinishTopicId = "Reward#2";

		private const string MenuPrefix = "menu_";

		private const string MenuItemPrefix = "menu_item_";

		private const string DropdownItemPrefix = "dropdown_item_";

		private const string ContextMenuPrefix = "context_menu_button";

		private const string ContextMenuItemPrefix = "context_menu_";

		private static readonly Lazy<TutorialManager> _instance = new Lazy<TutorialManager>(() => new TutorialManager());

		private readonly ITutorialService _tutorialService;

		private readonly ITutorialController _tutorialController;

		private readonly IDeviceService _deviceService;

		private TutorialStep _currentStep;

		private TutorialStep _suspendedStep;

		private bool _restored;

		private bool _inited;

		private readonly List<TutorialPopupViewModel> _tutorialPopups;

		public static TutorialManager Instance => _instance.Value;

		public bool InProgress
		{
			get
			{
				if (_currentStep == null)
				{
					return _suspendedStep != null;
				}
				return true;
			}
		}

		public IAsyncCommand FinishTutorialStepCommand { get; }

		public Dictionary<string, string> Parameters { get; }

		public string SuspendedControlId => _suspendedStep?.ControlID;

		public bool CanSkip
		{
			get
			{
				TutorialStep currentStep = _currentStep;
				if (currentStep == null || !currentStep.CanSkip)
				{
					return _suspendedStep?.CanSkip ?? false;
				}
				return true;
			}
		}

		public event EventHandler TutorialFinished;

		public TutorialManager()
		{
			FinishTutorialStepCommand = new AsyncCommand(FinishTutorialStep);
			_tutorialService = ComponentFactory.Resolve<ITutorialService>();
			_tutorialController = ComponentFactory.Resolve<ITutorialController>();
			_deviceService = ComponentFactory.Resolve<IDeviceService>();
			Parameters = new Dictionary<string, string>();
			_tutorialPopups = new List<TutorialPopupViewModel>();
		}

		private NavigationPath GetPath(TutorialStep tutorialStep)
		{
			return NavigationPath.FromTutorialStep(tutorialStep);
		}

		public void ControlActivated(string controlID)
		{
			if (_currentStep != null && !(_currentStep.ControlID != controlID))
			{
				Log.Info("... control activated: " + controlID);
				LockUI();
				_tutorialController.HideTutorialServiceViews();
				_deviceService.PerformAfterDelay(FinishCurrentStep, GetDelayAfterControlActivated());
			}
		}

		private int GetDelayAfterControlActivated()
		{
			return _currentStep.TopicID switch
			{
				"TransferMarket#1" => 3000, 
				"TransferMarket#13" => 2000, 
				"Training#3" => 1000, 
				"Ladder#12" => 2000, 
				"Ladder#14" => 2000, 
				"Ladder#16" => 4000, 
				_ => _currentStep.ControlID.StartsWith("menu_") ? 2000 : 1000, 
			};
		}

		public int GetMenuScrollIndex()
		{
			return _currentStep?.TopicID switch
			{
				"General#4" => 10, 
				"TransferMarket#17" => 7, 
				"Lineup#15" => 8, 
				"Training#12" => 12, 
				_ => 0, 
			};
		}

		public void RestartAnimations()
		{
			_tutorialController.RestartAnimations();
		}

		public void Reset()
		{
			_currentStep = null;
			_suspendedStep = null;
			_restored = false;
		}

		public void Init()
		{
			if (!_inited)
			{
				_inited = true;
				LockUI();
				if (_tutorialController.GetIsDummyTutorial())
				{
					InitDummyTutorial().FireAndForgetSafeAsync();
					return;
				}
				_restored = false;
				UpdateTutorial().FireAndForgetSafeAsync();
			}
		}

		private async Task InitDummyTutorial()
		{
			TutorialResponse tutorialResponse = await _tutorialService.GetTutorial();
			Log.Info("... ipad tutorial: " + tutorialResponse?.CurrentStep?.TopicID);
			if (tutorialResponse?.CurrentStep == null)
			{
				OnTutorialFinished();
				return;
			}
			if (!IsCurrentTopicIn("General#1", "IpadStart", "Reward#2"))
			{
				await ResetPadTo("Reward#2");
				return;
			}
			if (tutorialResponse.CurrentStep.TopicID == "General#1")
			{
				await ResetPadTo("IpadStart");
				return;
			}
			Log.Info("... ipad tutorial updating");
			Update(tutorialResponse.CurrentStep);
		}

		private async Task ResetPadTo(string topicId)
		{
			_restored = true;
			Log.Info("... ipad tutorial reset to " + topicId);
			await ResetTutorialTask(topicId);
		}

		public void Continue()
		{
			if (_suspendedStep == null)
			{
				return;
			}
			LockUI();
			Log.Info("... continue tutorial step " + _suspendedStep.TopicID);
			_deviceService.PerformAfterDelay(delegate
			{
				if (IsStepPerformed(_suspendedStep, isContinue: true))
				{
					_restored = true;
					_deviceService.PerformAfterDelay(_tutorialController.UnlockUI, 500L);
				}
			}, 1000L);
		}

		public void ResetTutorial()
		{
			_restored = false;
			LockUI();
			ResetTutorialTask("").FireAndForgetSafeAsync();
		}

		public async Task<bool> TrySkipTutorial()
		{
			if (await ComponentFactory.Resolve<IPopupService>().ShowYesNoMessageAsync("SkipTutorialTitle".Translate(), "SkipTutorial".Translate(), Character.Anna))
			{
				LockUI();
				Update((await _tutorialService.SkipTutorial()).CurrentStep);
				return true;
			}
			return false;
		}

		public void RegisterTutorialPopup(TutorialPopupViewModel tutorialPopupViewModel)
		{
			_tutorialPopups.Add(tutorialPopupViewModel);
		}

		public void RemoveTutorialPopup(TutorialPopupViewModel tutorialPopupViewModel)
		{
			_tutorialPopups.Remove(tutorialPopupViewModel);
		}

		public void CloseAllTutorialPopups()
		{
			TutorialPopupViewModel[] array = _tutorialPopups.ToArray();
			foreach (TutorialPopupViewModel tutorialPopupViewModel in array)
			{
				if (tutorialPopupViewModel != null)
				{
					tutorialPopupViewModel.CloseResult = PopupResult.Canceled;
				}
			}
			_tutorialPopups.Clear();
		}

		private void FinishCurrentStep()
		{
			LockUI();
			FinishTutorialStep().FireAndForgetSafeAsync();
		}

		public void RestartCurrentStep()
		{
			LockUI();
			_tutorialController.HideTutorialServiceViews(hideArrow: true, delegate
			{
				Update(_currentStep, forceRestart: true);
			});
		}

		private async Task UpdateTutorial()
		{
			TutorialResponse tutorialResponse = await _tutorialService.GetTutorial();
			if (tutorialResponse.CurrentStep != null && tutorialResponse.CurrentStep.TopicID != "General#1")
			{
				tutorialResponse = await _tutorialService.SkipTutorial();
			}
			Update(tutorialResponse.CurrentStep);
		}

		private async Task FinishTutorialStep()
		{
			LockUI();
			bool hasReward = _currentStep != null && _currentStep.HasReward;
			Update((await _tutorialService.FinishTutorialStep()).CurrentStep);
			if (hasReward)
			{
				ResourceService.Current.Update();
			}
		}

		private async Task ResetTutorialTask(string topicId)
		{
			Update((await _tutorialService.ResetTutorial(topicId)).CurrentStep);
		}

		private void Update(TutorialStep tutorialStep, bool forceRestart = false)
		{
			if (IsStepPerformed(tutorialStep, isContinue: false, forceRestart))
			{
				_deviceService.PerformAfterDelay(_tutorialController.UnlockUI, 500L);
			}
		}

		private bool NeedToSuspend(string topicId)
		{
			return false;
		}

		private void OnTutorialFinished()
		{
			_tutorialController.HideTutorialServiceViews();
			_tutorialController.UnlockUI();
			_currentStep = null;
			Log.Info("... no tutorial");
			this.TutorialFinished?.Invoke(this, EventArgs.Empty);
			ComponentFactory.Resolve<INotificationManager>().RequestPermissions();
		}

		private bool IsStepPerformed(TutorialStep tutorialStep, bool isContinue = false, bool forceRestart = false)
		{
			_suspendedStep = null;
			if (tutorialStep == null)
			{
				OnTutorialFinished();
				return true;
			}
			Log.Info("... current tutorial step is: " + tutorialStep.TopicID);
			if (!isContinue && !forceRestart && _currentStep?.TopicID == tutorialStep.TopicID)
			{
				Log.Info("... the same step again");
				return true;
			}
			_tutorialController.HideTutorialServiceViews();
			if (!_restored && !_deviceService.IsPad)
			{
				NavigationPath path = GetPath(tutorialStep);
				MenuItemIdentifier currentMenuItem = _tutorialController.GetCurrentMenuItem();
				int currentTabIndex = _tutorialController.GetCurrentTabIndex();
				Log.Info($"... tutorial path = {path}");
				Log.Info($"... current path = [{currentMenuItem}, tab = {currentTabIndex}]");
				bool num = path.MenuId != MenuItemIdentifier.None;
				bool flag = path.MenuId != currentMenuItem || path.TabIndex != currentTabIndex;
				if (num && flag && !tutorialStep.ControlID.StartsWith("menu_"))
				{
					_suspendedStep = tutorialStep;
					_tutorialController.NavigateTo(path.MenuId, path.TabIndex);
					Log.Info("... suspend tutorial on navigating");
					return false;
				}
				if (path.SubmenuId != SubmenuIdentifier.None)
				{
					_suspendedStep = tutorialStep;
					_tutorialController.ActivateSubmenu(path.SubmenuId);
					Log.Info("... suspend tutorial on activation submenu");
					_restored = true;
					return false;
				}
			}
			_restored = true;
			if (!isContinue && NeedToSuspend(tutorialStep.TopicID))
			{
				_suspendedStep = tutorialStep;
				Log.Info("... force suspend tutorial");
				return false;
			}
			_currentStep = tutorialStep;
			SpecialAction(tutorialStep.TopicID);
			bool flag2 = !string.IsNullOrEmpty(tutorialStep.CharacterID);
			if (flag2)
			{
				Log.Info("... show tutorial popup with " + tutorialStep.CharacterID);
				foreach (string key in Parameters.Keys)
				{
					if (tutorialStep.Message.Contains(key))
					{
						tutorialStep.Message = tutorialStep.Message.Replace(key, Parameters[key]);
					}
				}
				_tutorialController.ShowPopup(tutorialStep);
			}
			if (string.IsNullOrEmpty(tutorialStep.ControlID))
			{
				return true;
			}
			Log.Info("... try to find control id = " + tutorialStep.ControlID);
			if (tutorialStep.ControlID.StartsWith("context_menu_") && !tutorialStep.ControlID.StartsWith("context_menu_button"))
			{
				Log.Info("... open menu for context menu item");
				_tutorialController.OpenContextMenu();
			}
			if (!_tutorialController.TryToHighlightControl(tutorialStep.ControlID, ButtonCanBeDisabled(), tutorialStep.ControlID.StartsWith("dropdown_item_"), !flag2))
			{
				FinishCurrentStep();
				return false;
			}
			return true;
		}

		private void LockUI()
		{
			_tutorialController.LockUI(IsCurrentTopicIn("TransferMarket#2"));
		}

		private bool ButtonCanBeDisabled()
		{
			return IsCurrentTopicIn("Training#5");
		}

		private void SpecialAction(string topicId)
		{
			switch (topicId)
			{
			case "TransferMarket#1":
				ComponentFactory.Resolve<TransferMarketViewModel>().ResetCommand.Execute(null);
				break;
			case "Lineup#6":
				ComponentFactory.Resolve<ResourcesViewModel>().IsNavigationBarEnabled = false;
				break;
			case "Lineup#8":
				ComponentFactory.Resolve<ResourcesViewModel>().IsNavigationBarEnabled = true;
				break;
			case "Ladder#17":
				_tutorialController.CloseLadderPopup();
				break;
			case "Training#5":
				ComponentFactory.Resolve<TeamTrainingViewModel>().SetForceSaveEnabled(value: true);
				break;
			case "Training#6":
				ComponentFactory.Resolve<TeamTrainingViewModel>().SetForceSaveEnabled(value: false);
				break;
			case "Reward#1":
				ComponentFactory.Resolve<INavigationService>().NavigateTo(ScreenIdentifier.Club, 0);
				break;
			}
		}

		private bool IsCurrentTopicIn(params string[] topics)
		{
			if (topics == null || topics.Length == 0)
			{
				return false;
			}
			if (!InProgress)
			{
				return false;
			}
			TutorialStep tutorialStep = _suspendedStep ?? _currentStep;
			if (tutorialStep == null)
			{
				return false;
			}
			return topics.Contains(tutorialStep.TopicID);
		}

		public bool ShouldChangeLineup()
		{
			return IsCurrentTopicIn("Lineup#2", "Lineup#3", "Lineup#4", "Lineup#5", "Lineup#6");
		}

		public bool ShouldDecreaseStamina()
		{
			return IsCurrentTopicIn("Ladder#12", "Ladder#13", "Ladder#14");
		}
	}
	public class AsyncCommand : IAsyncCommand, ICommand
	{
		private bool _isExecuting;

		private readonly Func<Task> _execute;

		private readonly Func<bool> _canExecute;

		public event EventHandler CanExecuteChanged;

		public AsyncCommand(Func<Task> execute, Func<bool> canExecute = null)
		{
			_execute = execute;
			_canExecute = canExecute;
		}

		public bool CanExecute()
		{
			if (_execute != null && !_isExecuting)
			{
				return _canExecute?.Invoke() ?? true;
			}
			return false;
		}

		public async Task ExecuteAsync()
		{
			if (CanExecute())
			{
				try
				{
					_isExecuting = true;
					await _execute();
				}
				finally
				{
					_isExecuting = false;
				}
			}
			RaiseCanExecuteChanged();
		}

		public void RaiseCanExecuteChanged()
		{
			this.CanExecuteChanged?.Invoke(this, EventArgs.Empty);
		}

		bool ICommand.CanExecute(object parameter)
		{
			return CanExecute();
		}

		void ICommand.Execute(object parameter)
		{
			ExecuteAsync().FireAndForgetSafeAsync();
		}
	}
	public class AsyncCommand<T> : IAsyncCommand<T>, ICommand
	{
		private bool _isExecuting;

		private readonly Func<T, Task> _execute;

		private readonly Func<T, bool> _canExecute;

		public event EventHandler CanExecuteChanged;

		public AsyncCommand(Func<T, Task> execute, Func<T, bool> canExecute = null)
		{
			_execute = execute;
			_canExecute = canExecute;
		}

		public bool CanExecute(T parameter)
		{
			if (!_isExecuting)
			{
				return _canExecute?.Invoke(parameter) ?? true;
			}
			return false;
		}

		public async Task ExecuteAsync(T parameter)
		{
			if (CanExecute(parameter))
			{
				try
				{
					_isExecuting = true;
					await _execute(parameter);
				}
				finally
				{
					_isExecuting = false;
				}
			}
			RaiseCanExecuteChanged();
		}

		public void RaiseCanExecuteChanged()
		{
			this.CanExecuteChanged?.Invoke(this, EventArgs.Empty);
		}

		bool ICommand.CanExecute(object parameter)
		{
			if (!(parameter is T parameter2))
			{
				return false;
			}
			return CanExecute(parameter2);
		}

		void ICommand.Execute(object parameter)
		{
			if (parameter is T parameter2)
			{
				ExecuteAsync(parameter2).FireAndForgetSafeAsync();
			}
		}
	}
