			ShellViewModel = ComponentFactory.Resolve<ShellViewModel>();
			NavigationService = ComponentFactory.Resolve<INavigationService>();
			ResourceService = ComponentFactory.Resolve<IResourceService>();
		}

		protected void AddChildViewModel<T>() where T : BaseViewModel
		{
			AddChildViewModel(ComponentFactory.Resolve<T>());
		}

		protected void AddChildViewModel(BaseViewModel viewModel)
		{
			if (_childViewModels == null)
			{
				_childViewModels = new List<BaseViewModel>();
			}
			_childViewModels.Add(viewModel);
		}

		protected async Task InitChildViewModels()
		{
			if (_childViewModels != null)
			{
				await Task.WhenAll(_childViewModels.Select((BaseViewModel x) => x.Init()));
			}
		}

		protected async Task UpdateChildViewModels()
		{
			if (_childViewModels != null)
			{
				await Task.WhenAll(_childViewModels.Select((BaseViewModel x) => x.Update()));
			}
		}

		public override void ApplyBinding()
		{
			base.ApplyBinding();
			if (_childViewModels == null)
			{
				return;
			}
			foreach (BaseViewModel childViewModel in _childViewModels)
			{
				childViewModel.ApplyBinding();
			}
		}

		public virtual async Task Init()
		{
			IsBusy = true;
			await Update();
			await InitChildViewModels();
			IsBusy = false;
		}

		public virtual async Task Update()
		{
			await UpdateChildViewModels();
		}

		public void Pause()
		{
			OnPaused();
		}

		protected virtual void OnPaused()
		{
		}
	}
	public class BindingEngine
	{
		private bool _started;

		private readonly Dictionary<string, List<BindingInfo>> _bindings;

		private Dictionary<string, PropertyInfo> _vmProperties;

		private NotifyObject _viewModel;

		public bool ShowLog { get; set; }

		public event PropertyChangedEventHandler PropertyChanged;

		public BindingEngine()
		{
			_bindings = new Dictionary<string, List<BindingInfo>>();
		}

		public void SetBindingContext(NotifyObject viewModel)
		{
			Stop();
			if (viewModel != null)
			{
				_viewModel = viewModel;
				_vmProperties = _viewModel.GetType().GetProperties().ToDictionary((PropertyInfo x) => x.Name);
			}
			Start();
		}

		public void Start()
		{
			if (!_started)
			{
				_started = true;
				if (_viewModel != null)
				{
					_viewModel.PropertyChanged -= OnViewModelPropertyChanged;
					_viewModel.PropertyChanged += OnViewModelPropertyChanged;
				}
			}
		}

		public void Stop()
		{
			if (_started)
			{
				_started = false;
				if (_viewModel != null)
				{
					_viewModel.PropertyChanged -= OnViewModelPropertyChanged;
				}
			}
		}

		private void OnViewModelPropertyChanged(object sender, PropertyChangedEventArgs e)
		{
			this.PropertyChanged?.Invoke(this, e);
			if (_vmProperties != null && _viewModel != null && _vmProperties.TryGetValue(e.PropertyName, out var value))
			{
				Update(e.PropertyName, value.GetValue(_viewModel));
			}
		}

		public void Update(string propertyName, object value)
		{
			if (!_bindings.TryGetValue(propertyName, out var value2))
			{
				return;
			}
			foreach (BindingInfo item in value2)
			{
				item.Update(value);
			}
		}

		public void Add(object view, string viewPropertyName, string viewModelPropertyName, Func<object, object> converter = null, bool showLog = false)
		{
			if (!_bindings.ContainsKey(viewModelPropertyName))
			{
				_bindings[viewModelPropertyName] = new List<BindingInfo>();
			}
			_bindings[viewModelPropertyName].Add(new BindingInfo(view, viewPropertyName, converter, showLog));
		}

		public void UpdateViewModel(string propertyName, object value)
		{
			if (_vmProperties.TryGetValue(propertyName, out var value2) && value2.CanWrite)
			{
				value2.SetValue(_viewModel, value);
			}
		}
	}
	public class BindingInfo
	{
		private readonly string _propertyName;

		private readonly bool _showLog;

		public PropertyInfo Property { get; }

		public object View { get; }

		public Func<object, object> Converter { get; }

		public BindingInfo(object view, string propertyName, Func<object, object> converter = null, bool showLog = false)
		{
			_propertyName = propertyName;
			_showLog = showLog;
			Property = view.GetType().GetProperty(propertyName);
			View = view;
			Converter = converter;
		}

		public void Update(object value)
		{
			if (_showLog)
			{
				Log.Info($"Binding new {_propertyName} = {value}");
			}
			if (Property == null)
			{
				Log.Info($"Warning! Property info is NULL: '{_propertyName}' for {View}");
				return;
			}
			object obj = Converter?.Invoke(value) ?? value;
			object value2 = Property.GetValue(View);
			if ((value2 == null && obj == null) || (value2 != null && value2.Equals(obj) && !value2.GetType().IsByRef))
			{
				return;
			}
			if (obj != null && obj.GetType().IsValueType && Property.PropertyType != obj.GetType())
			{
				Property.SetValue(View, (obj is IConvertible) ? Convert.ChangeType(obj, Property.PropertyType) : obj);
				return;
			}
			try
			{
				Property.SetValue(View, obj);
			}
			catch
			{
				Log.Info($"Unable to set binding value: {obj} to {Property.Name}");
			}
		}
	}
