	public class NotifyObject : INotifyPropertyChanged
	{
		public event PropertyChangedEventHandler PropertyChanged;

		protected void Set<T>(ref T field, T value, [CallerMemberName] string propertyName = "")
		{
			if (!EqualityComparer<T>.Default.Equals(field, value))
			{
				field = value;
				OnPropertyChanged(propertyName);
			}
		}

		protected bool TrySet<T>(ref T field, T value, [CallerMemberName] string propertyName = "")
		{
			if (EqualityComparer<T>.Default.Equals(field, value))
			{
				return false;
			}
			field = value;
			OnPropertyChanged(propertyName);
			return true;
		}

		protected virtual void OnPropertyChanged(string propertyName)
		{
			MainThread.BeginInvokeOnMainThread((Action)delegate
			{
				this.PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
			});
		}

		public virtual void ApplyBinding()
		{
			foreach (PropertyInfo item in from x in GetType().GetProperties()
				where !Attribute.IsDefined(x, typeof(NotApplyAttribute))
				select x)
			{
				OnPropertyChanged(item.Name);
			}
		}

		public object GetPropertyValue(string propertyName)
		{
			return GetType().GetProperty(propertyName).GetValue(this);
		}
	}
