	public class TimerEngine
	{
		private System.Timers.Timer _timer;

		private DateTime _endDate;

		private double _totalSeconds;

		public int RefreshInterval { get; set; } = 1000;

		public event EventHandler<TimeChangedEventArgs> TimeChanged;

		public void SetEndDate(DateTime date, double totalSeconds = 0.0)
		{
			if (!(date <= DateTime.UtcNow))
			{
				Log.Info($"set end date to {date}");
				_endDate = date;
				_totalSeconds = totalSeconds;
				if (_timer == null)
				{
					_timer = new System.Timers.Timer(RefreshInterval);
					_timer.Elapsed += OnTimerTick;
				}
				if (!_timer.Enabled)
				{
					_timer.Start();
				}
				Refresh();
			}
		}

		private void OnTimerTick(object sender, ElapsedEventArgs e)
		{
			Refresh();
		}

		private void Refresh()
		{
			bool flag = DateTime.UtcNow >= _endDate;
			TimeSpan timeLeft = (flag ? TimeSpan.Zero : (_endDate - DateTime.UtcNow));
			TimeChangedEventArgs e = new TimeChangedEventArgs(progress: (_totalSeconds > 0.0) ? ((decimal)Math.Max(0.0, (_totalSeconds - timeLeft.TotalSeconds) / _totalSeconds * 100.0)) : 100m, timeLeft: timeLeft, isFinished: flag);
			if (flag)
			{
				_timer.Stop();
			}
			MainThread.BeginInvokeOnMainThread((Action)delegate
			{
				this.TimeChanged?.Invoke(this, e);
			});
		}

		public void Stop()
		{
			_timer?.Stop();
		}
	}
