	public class ViewManager
	{
		private readonly Dictionary<Type, Type> _views;

		public ViewManager(Assembly assembly)
		{
			_views = new Dictionary<Type, Type>();
			Type[] types = assembly.GetTypes();
			foreach (Type type in types)
			{
				if (Attribute.GetCustomAttribute(type, typeof(ViewForAttribute)) is ViewForAttribute viewForAttribute)
				{
					_views[viewForAttribute.ViewModel] = type;
					Log.Info($"== Found view {type} for vm {viewForAttribute.ViewModel}");
				}
			}
		}

		public Type GetViewType(Type viewModelType)
		{
			if (_views.TryGetValue(viewModelType, out var value))
			{
				return value;
			}
			return null;
		}
	}
	public class ChatViewModel : BaseViewModel
	{
		private const string LastMessageIdKey = "chat_last_message_id";

		private const int TypingTimeout = 5;

		private readonly IChatService _chatService;

		private readonly Random _rnd;

		private HubConnection _hub;

		private bool _isConnected;

		private DateTime _lastTimeTyping;

		private Guid _myUserId;

		private System.Timers.Timer _timer;

		private readonly Dictionary<Guid, UserTyping> _users;

		private List<ChatMessage> _messages;

		private string _userTyping;

		private string _text;

		private const string _nameSeparator = " @";

		private readonly string[] _typingNameSeparator = new string[1] { " @" };

		public List<ChatMessage> Messages
		{
			get
			{
				return _messages;
			}
			set
