				Typing();
			}
		}

		public event Action OnMessagePosted;

		public ChatViewModel(IChatService chatService)
		{
			_users = new Dictionary<Guid, UserTyping>();
			_chatService = chatService;
			_lastTimeTyping = DateTime.Now.AddMinutes(-1.0);
			_rnd = new Random();
		}

		private void OnTimerTick(object sender, ElapsedEventArgs e)
		{
			UpdateTyping();
		}

		public override async Task Init()
		{
			if (_hub == null)
			{
				await UpdateInternal();
				_hub = HubConnectionBuilderHttpExtensions.WithUrl((IHubConnectionBuilder)new HubConnectionBuilder(), URLHelper.NewBackendUrl + "/chat").Build();
				_hub.Closed += OnHubClosed;
				HubConnectionExtensions.On<Guid, string>(_hub, "Typing", (Action<Guid, string>)OnTyping);
				HubConnectionExtensions.On<Guid, ChatMessage>(_hub, "Post", (Action<Guid, ChatMessage>)OnPost);
				await Connect();
				_timer = new System.Timers.Timer(1000.0);
				_timer.Elapsed += OnTimerTick;
			}
		}

		private async Task UpdateInternal()
		{
			ChatData chatData = await _chatService.GetChatHistory();
			if (chatData == null)
			{
				return;
			}
			_myUserId = chatData.UserId;
			List<ChatMessage> list = chatData.Messages?.ToList() ?? new List<ChatMessage>();
			Guid guid = Guid.Empty;
			ChatMessage lastMessage = new ChatMessage();
			foreach (ChatMessage item in list)
			{
				UpdateHeader(item, lastMessage);
				lastMessage = item;
				if (guid != Guid.Empty)
				{
					item.IsNewUser = guid != item.UserId || item.Header != "";
				}
				guid = item.UserId;
			}
			Messages = list;
			CheckNewMessage(Messages.LastOrDefault());
			_users.Clear();
			UpdateTyping();
			base.IsBusy = false;
			OnPropertyChanged("Messages");
		}

		public async Task Reinit()
		{
			if (_hub != null)
			{
				await UpdateInternal();
			}
		}

		public override Task Update()
		{
			return base.Update();
		}

		private void Typing()
		{
			TypingTask().FireAndForgetSafeAsync();
		}

		private async Task TypingTask()
		{
			if (!string.IsNullOrWhiteSpace(Text) && !((DateTime.Now - _lastTimeTyping).TotalSeconds < 5.0))
			{
				_lastTimeTyping = DateTime.Now;
				await _chatService.Typing();
			}
		}

		public void Post()
		{
			if (!string.IsNullOrWhiteSpace(Text))
			{
				string text = Text;
				PostTask(text).FireAndForgetSafeAsync();
				Text = string.Empty;
			}
		}

		private async Task PostTask(string text)
		{
			await _chatService.Post(text);
		}

		private void OnPost(Guid userId, ChatMessage chat)
		{
			Log.Info("Chat on post: " + chat?.Name + " : " + chat?.Message);
			if (chat != null && !string.IsNullOrWhiteSpace(chat.Message) && !string.IsNullOrWhiteSpace(chat.Name) && Messages != null)
			{
				if (_users.ContainsKey(userId))
				{
					_users[userId].Started = DateTime.Now.AddSeconds(-6.0);
				}
				UpdateTyping();
				ChatMessage chatMessage = Messages.LastOrDefault() ?? new ChatMessage();
				chat.IsMine = userId == _myUserId;
				UpdateHeader(chat, chatMessage);
				chat.IsNewUser = chat.UserId != chatMessage.UserId || chat.Header != "";
				Messages.Add(chat);
				CheckNewMessage(chat);
				OnPropertyChanged("Messages");
			}
		}

		private void UpdateHeader(ChatMessage chat, ChatMessage lastMessage)
		{
			chat.DateGroup = chat.DateValue.ToLocalTime().Date;
			chat.Header = ((chat.DateGroup != lastMessage.DateGroup) ? chat.DateGroup.ToString("dd MMMM") : string.Empty);
		}

		private void OnTyping(Guid userId, string userName)
		{
			if (!string.IsNullOrWhiteSpace(userName) && !(userId == _myUserId))
			{
				if (!_users.ContainsKey(userId))
				{
					_users.Add(userId, new UserTyping
					{
						Name = userName
					});
				}
				if (!_timer.Enabled)
				{
					_timer.Start();
				}
				_users[userId].Started = DateTime.Now;
				UpdateTyping();
			}
		}

		private void UpdateTyping()
		{
			if (_users == null || _users.Count == 0)
			{
				UserTyping = string.Empty;
				return;
			}
			string[] array = (from x in _users.Values
				where (DateTime.Now - x.Started).TotalSeconds < 5.0
				select GetTypingName(x.Name)).ToArray();
			if (array.Length == 0)
			{
				UserTyping = string.Empty;
			}
			else
			{
				UserTyping = string.Join(", ", array) + " typing...";
			}
		}

		private string GetTypingName(string name)
		{
			if (!name.Contains(" @"))
			{
				return name;
			}
			string[] array = name.Split(_typingNameSeparator, StringSplitOptions.RemoveEmptyEntries);
			if (array.Length == 0)
			{
				return name;
			}
			return array[0];
		}

		private async Task OnHubClosed(Exception ex)
		{
			_isConnected = false;
			if (ex != null)
			{
				await Task.Delay(100 + _rnd.Next(200));
				await Connect();
			}
		}

		private async Task Connect()
		{
			if (_isConnected || (int)_hub.State != 0)
			{
				return;
			}
			try
			{
				await _hub.StartAsync(default(CancellationToken));
				_isConnected = true;
			}
			catch (Exception ex)
			{
				Log.Info("Chat connection error: " + ex.Message);
				AppAnalytics.Instance.TrackError(ex);
			}
		}

		private void CheckNewMessage(ChatMessage message)
		{
			if (message == null || message.IsMine)
			{
				return;
			}
			string text = Preferences.Get("chat_last_message_id", string.Empty);
			if (string.IsNullOrEmpty(text) || message.Id != Guid.Parse(text))
			{
				Preferences.Set("chat_last_message_id", message.Id.ToString());
				MainThread.BeginInvokeOnMainThread((Action)delegate
				{
					this.OnMessagePosted?.Invoke();
				});
			}
		}
	}
