		private async Task RefreshMails()
		{
			_refreshTimer.Stop();
			_mailsData = (await _teamService.GetMyMail()).Mails;
			UpdateMailsList();
			_refreshTimer.Start();
		}

		private async Task RefreshDailyReward()
		{
			if (!(Preferences.Get("daily_reward_last_date", DateTime.UtcNow.Date.AddDays(-1.0)) >= DateTime.UtcNow.Date))
			{
				Preferences.Set("daily_reward_last_date", DateTime.UtcNow.Date);
				await RefreshAccomplishments();
				decimal reward = await ComponentFactory.Resolve<IUserService>().ClaimDailyReward();
				if (!(reward <= 0m))
				{
					await base.ResourceService.UpdateAsync();
					ComponentFactory.Resolve<IShell>().ShowNotification(new NotificationData(string.Empty, string.Empty, string.Format("DailyLoginMessage".Translate(), reward), "balance_star"));
				}
			}
		}

		private async Task RefreshAccomplishments()
		{
			AccomplishmentsResponse accomplishmentsResponse = await _teamService.GetMyAccomplishments();
			foreach (AccomplishmentData accomplishment in accomplishmentsResponse.Accomplishments)
			{
				accomplishment.Name = accomplishment.Name.Replace("{0}", Environment.NewLine);
			}
			Accomplishments = accomplishmentsResponse.Accomplishments;
		}

		protected override void OnTimerRefresh(TimeSpan timeLeft, bool isFininshed)
		{
			UpdateMatchInfo();
		}

		private void ShowNextMatch()
		{
			IsNextMatchSelected = true;
			UpdateMatchInfo();
		}

		private void ShowLastMatch()
		{
			IsNextMatchSelected = false;
			UpdateMatchInfo();
		}

		private void UpdateMatchInfo()
		{
			MatchData matchData = (IsNextMatchSelected ? NextMatch : LastMatch);
			IsNextMatchInfoVisible = IsNextMatchSelected && matchData != null;
			IsLastMatchInfoVisible = !IsNextMatchSelected && matchData != null;
			MatchDate = matchData?.Date.ParseToDate().ToLocalTime().ToGTDateTimeString() ?? string.Empty;
			MatchStatus = GetMatchStatus(matchData);
			HomeTeamName = matchData?.HomeName ?? string.Empty;
			AwayTeamName = matchData?.AwayName ?? string.Empty;
		}

		private int GetStadiumLevelBySize(int stadiumSize)
		{
			if (stadiumSize <= 5000)
			{
				return 1;
			}
			if (stadiumSize > 5000 && stadiumSize <= 15000)
			{
				return 2;
			}
			if (stadiumSize > 15000 && stadiumSize <= 30000)
			{
				return 3;
			}
			if (stadiumSize > 30000 && stadiumSize <= 50000)
			{
				return 4;
			}
			return 5;
		}

		private string GetMatchStatus(MatchData matchData)
		{
			ShowScore = false;
			if (matchData == null)
			{
				return "WaitingMatch".Translate();
			}
			DateTime utcNow = DateTime.UtcNow;
			DateTime dateTime = matchData.Date.ParseToDate();
			if (dateTime.AddMinutes(-60.0) > utcNow)
			{
				return "KickOffAt".Translate();
			}
			if (dateTime > utcNow)
			{
				int num = (int)(dateTime - utcNow).TotalMinutes;
				MatchDate = string.Format("InMinutes".Translate(), num);
				return "KickOff".Translate();
			}
			if (dateTime.AddMinutes(115.0) > utcNow)
			{
				return "Live".Translate();
			}
			if (matchData.HomeScore == -1 || matchData.AwayScore == -1)
			{
				return "MatchDelayed".Translate();
			}
			ShowScore = true;
			return $"{matchData.HomeScore} : {matchData.AwayScore}";
		}

