		{
			ComponentFactory.Resolve<MailDetailsViewModel>().SelectedMail = mail;
			ComponentFactory.Resolve<INavigationService>().NavigateTo(ScreenIdentifier.Club_MailDetails);
			ReadEmail(mail);
		}

		public void ReadEmail(MailData mail)
		{
			if (mail.IsNew)
			{
				MarkMailAsRead(mail).FireAndForgetSafeAsync();
			}
		}

		private async Task MarkMailAsRead(MailData mail)
		{
			await _teamService.MarkAsRead(mail.Id);
			mail.IsNew = false;
			UpdateMailsList();
		}

		private async Task MarkAllAsRead()
		{
			base.IsBusy = true;
			await _teamService.MarkAllAsRead();
			foreach (MailData mailsDatum in _mailsData)
			{
				mailsDatum.IsNew = false;
			}
			UpdateMailsList();
			base.IsBusy = false;
		}

		private async Task DeleteAllRead()
		{
			IShell shell = ComponentFactory.Resolve<IShell>();
			shell.StartProgress();
			await _teamService.DeleteAllRead();
			await RefreshMails();
			shell.StopProgress();
		}

		public void DeleteLocalEmail(MailData mail)
		{
			base.IsBusy = true;
			_mailsData.Remove(mail);
			UpdateMailsList();
			base.IsBusy = false;
		}

		public MailData GetMail(int index)
		{
			return _mailsData[index];
		}

		public int GetIndexOfMail(MailData mail)
		{
			return _mailsData?.IndexOf(mail) ?? (-1);
		}

		private void UpdateMailsList()
		{
			List<ITableRow> list = new List<ITableRow>();
			int num = 0;
			foreach (MailData mailsDatum in _mailsData)
			{
				list.Add(new TableRow(new TextCell(mailsDatum.Date.ParseToDate().ToGTDateTimeString(), TableCellAlignment.Left, GetColor(mailsDatum)), new TextCell(mailsDatum.Sender, TableCellAlignment.Left, GetColor(mailsDatum)), new TextCell(mailsDatum.Subject, TableCellAlignment.Left, GetColor(mailsDatum)))
				{
					Command = SelectMailCommand,
					CommandParameter = mailsDatum
				});
				if (mailsDatum.IsNew)
				{
					num++;
				}
			}
			Mails = list;
			NewMails = num;
		}

		private TableCellColor GetColor(MailData mail)
		{
			if (!mail.IsNew)
			{
				return TableCellColor.Accent;
			}
			return TableCellColor.Default;
		}

		private async Task ChangeClubName()
		{
			EntryPopupViewModel rename = new EntryPopupViewModel
			{
				Title = "ChangeClubName".Translate(),
				ConfirmButtonTitle = "Change".Translate(),
				Message = "ChangeClubNameDescription".Translate(),
				IsButtonPremium = true,
				PriceValue = _changeNameCost
			};
			if (await base.PopupService.ShowPopupAsync(rename) == PopupResult.Done && await base.ResourceService.SpentGTStars(_changeNameCost))
			{
				base.IsBusy = true;
				if ((await _teamService.ChangeTeamName(rename.EnteredText)).Status != ResponseStatus.OK)
				{
					base.IsBusy = false;
					return;
				}
				await Update();
				base.IsBusy = false;
			}
		}

		private async Task ShowComparePopup()
		{
			ComparePopupViewModel popupViewModel = new ComparePopupViewModel
			{
				TeamId = NextMatch.OpponentTeamId
			};
			await base.PopupService.ShowPopupAsync(popupViewModel);
		}

		private void ShowLineup()
		{
			if (!(NextMatch.Id == Guid.Empty))
			{
				LineupFormationViewModel lineupFormationViewModel = ComponentFactory.Resolve<LineupFormationViewModel>();
				lineupFormationViewModel.MatchId = NextMatch.Id;
				lineupFormationViewModel.IsFriendly = NextMatch.IsFriendly;
				base.NavigationService.NavigateTo(ScreenIdentifier.Lineup_Formation);
			}
		}

		public void UpdateSponsor(bool isMain, bool isSigned)
		{
			if (isMain)
			{
				_mainSponsorSigned = isSigned;
			}
			else
			{
				_secondarySponsorSigned = isSigned;
			}
			SponsorsCount = ((!_mainSponsorSigned) ? 1 : 0) + ((!_secondarySponsorSigned) ? 1 : 0);
		}
	}
