			MoveUpCommand = new Command(MoveUp, CanMoveUp);
			MoveDownCommand = new Command(MoveDown, CanMoveDown);
			_emailStyle = "\n* {\n    -webkit-text-size-adjust: none;\n    font-size: [FontSize];\n}\nbody {\n    font-family: Helvetica, Arial, sans-serif;\n    margin: -1;\n    user-select: none;\n    -webkit-touch-callout: none;\n    -webkit-user-select: none;\n}\n.email {\n    width: 100%;\n}\n.emailheader {\n    background-color: #333;\n    color: #ccc;\n    padding: 1em;\n}\n.emailheadercolumn {\n    display: inline-block;\n    box-sizing: border-box;\n    width: 50%;\n    margin-bottom: 0.5em;\n}\n.emailheadersender {\n    font-weight: bold;\n    color: #eee;\n}\n.emailbody {\n    box-sizing: border-box;\n    width: 100%;\n    padding: 1em;\n}\n.button {\n    box-shadow:inset 0px 1px 0px 0px #a4e271;\n    background:linear-gradient(to bottom, #89c403 5%, #648c08 100%);\n    background-color: #89c403;\n    border-radius: 1.5em;\n    border: 1px solid #74b807;\n    display: inline-block;\n    color: #fff;\n    font-weight: bold;\n    padding: 0.5em 2em 0.7em 2em;\n    text-decoration: none;\n    text-shadow: 0px 1px 0px #528009;\n    margin: 1em;\n}\n".Replace("[FontSize]", $"{12}px");
			_htmlReplacements = new Dictionary<string, string>
