		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (propertyName == "SelectedMail")
			{
				UpdateButtonsState();
				RenderMail();
			}
		}

		private void RenderMail()
		{
			MailHtml = string.Empty;
			if (SelectedMail != null)
			{
				base.Title = SelectedMail.Subject;
				ManagerImage = ((SelectedMail.SenderType == 0) ? "assistant" : "coach");
				string text = SelectedMail.Message.Decompress();
				string text2 = SelectedMail.Date.ParseToDate().ToLocalTime().ToGTDateTimeString();
				string text3 = string.Format("\n<div class=\"email\">\n<div class=\"emailheader\">\n<div class=\"emailheadercolumn\">{1}: <span class=\"emailheadersender\">{2}</span></div><div class=\"emailheadercolumn\">{0}</div>\n<div><b>{3}</b></div>\n</div>\n<div class=\"emailbody\">", text2, "From".Translate(), SelectedMail.Sender, SelectedMail.Subject);
				string mailHtml;
				if (!text.Contains("<html>"))
				{
					text = string.Format(text, "<br />");
					text = text.Replace(Environment.NewLine, "<br />");
					mailHtml = $"\n<html>\n<head>\n<meta name='viewport' content='width=device-width, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0, user-scalable=no'>\n<meta content=\"text/html; charset=utf-8\">\n<style type=\"text/css\">\n{_emailStyle}\n</style>\n</head>\n<body>\n{text3}{text}\n</div>\n</div>\n</body>\n</html>";
				}
				else
				{
					mailHtml = ApplyStyle(text3, text);
					mailHtml = RenderStars(mailHtml);
					mailHtml = RenderSkillCards(mailHtml);
				}
				MailHtml = mailHtml;
			}
		}

		private string ApplyStyle(string header, string text)
		{
			text = text.Replace("</style>", _emailStyle + "</style>");
			foreach (string key in _htmlReplacements.Keys)
			{
				text = text.Replace(key, _htmlReplacements[key]);
			}
			return text.Replace("<body>", "<body>" + header);
		}

		private string RenderSkillCards(string html)
		{
			foreach (Match item in new Regex("(\\[SkillCard)(.*?)(\\])").Matches(html))
			{
				string[] array = item.Value.Replace("[SkillCard-", string.Empty).Replace("]", string.Empty).Split(new char[1] { '-' }, StringSplitOptions.RemoveEmptyEntries);
				if (array.Length == 3 && int.TryParse(array[0], out var result) && int.TryParse(array[1], out var result2) && int.TryParse(array[2], out var result3))
				{
					string skillCardBase = _platformService.GetSkillCardBase64(new SkillCard
					{
						Skill = result,
						Rarity = result2,
						Bonus = (decimal)result3 * 0.01m
					});
					html = html.Replace(item.Value, $"data:image/png;base64, {skillCardBase}");
				}
			}
			return html;
		}

		private string RenderStars(string html)
		{
			bool flag = false;
			foreach (Match item in new Regex("(\\[Stars_)(.*?)(\\])").Matches(html))
			{
				if (decimal.TryParse(item.Value.Replace("[Stars_", string.Empty).Replace("]", string.Empty), out var result))
				{
					if (!_base64Strength.TryGetValue((result, flag), out var value))
					{
						value = _platformService.GetStrengthStarsBase64(result, flag);
						_base64Strength.Add((result, flag), value);
					}
					html = html.Replace(item.Value, $"data:image/png;base64, {value}");
				}
				flag = true;
			}
			return html;
		}

		private async Task DeleteEmail()
		{
			if (SelectedMail == null)
			{
				return;
			}
			base.IsBusy = true;
			int index = GetCurrentEmailIndex();
			try
			{
				await _teamService.DeleteMail(SelectedMail.Id);
				_clubViewModel.DeleteLocalEmail(SelectedMail);
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
			finally
			{
				base.IsBusy = false;
			}
			if (_clubViewModel.Mails.Count == 0)
			{
				ComponentFactory.Resolve<INavigationService>().NavigateBack();
			}
			if (index > _clubViewModel.Mails.Count - 1)
			{
				index = _clubViewModel.Mails.Count - 1;
			}
			MoveToEmail(index);
		}

		private void MoveUp()
		{
			int currentEmailIndex = GetCurrentEmailIndex();
			MoveToEmail(currentEmailIndex - 1);
		}

		private void MoveDown()
		{
			int currentEmailIndex = GetCurrentEmailIndex();
			MoveToEmail(currentEmailIndex + 1);
		}

		private bool CanMoveUp()
		{
			int currentEmailIndex = GetCurrentEmailIndex();
			return CanMoveTo(currentEmailIndex - 1);
		}

		private bool CanMoveDown()
		{
			int currentEmailIndex = GetCurrentEmailIndex();
			return CanMoveTo(currentEmailIndex + 1);
		}

		private int GetCurrentEmailIndex()
		{
			if (SelectedMail == null)
			{
				return -1;
			}
			return _clubViewModel.GetIndexOfMail(SelectedMail);
		}

		private bool CanMoveTo(int index)
		{
			if (index < 0 || index > _clubViewModel.Mails.Count - 1)
			{
				return false;
			}
			return true;
		}

		private void MoveToEmail(int index)
		{
			if (CanMoveTo(index))
			{
				SelectedMail = _clubViewModel.GetMail(index);
				_clubViewModel.ReadEmail(SelectedMail);
				UpdateButtonsState();
			}
		}

		private void UpdateButtonsState()
		{
			MoveUpCommand.RaiseCanExecuteChanged();
			MoveDownCommand.RaiseCanExecuteChanged();
		}
	}
