		public abstract bool IsMainSponsor { get; }

		public ICommand NegotiateCommand { get; }

		private ClubViewModel ClubViewModel => _clubViewModel ?? (_clubViewModel = ComponentFactory.Resolve<ClubViewModel>());

		public SponsorDetailsViewModel(ISponsorService sponsorService)
		{
			_sponsorService = sponsorService;
			NegotiateCommand = new AsyncCommand(Negotiate);
			CardsTitle = "SkillCardsBonus".Translate();
		}

		public override Task Init()
		{
			return Update();
		}

		public override Task Update()
		{
			return Task.FromResult(result: true);
		}

		public async Task<bool> Accept()
		{
			base.IsBusy = true;
			SponsorResponse sponsorResponse = await _sponsorService.Accept(_offerId);
			if (sponsorResponse == null || sponsorResponse.Status != ResponseStatus.OK)
			{
				base.IsBusy = false;
				return false;
			}
			_skillCards = sponsorResponse.SkillCards;
			Update(sponsorResponse.Sponsor, 0, null);
			base.IsBusy = false;
			return true;
		}

		public async Task ShowReward()
		{
			if (!TutorialManager.Instance.InProgress && _skillCards != null && _skillCards.Count > 0)
			{
				SkillCardsPopupViewModel popupViewModel = new SkillCardsPopupViewModel(_skillCards);
				await ComponentFactory.Resolve<IPopupService>().ShowPopupAsync(popupViewModel);
			}
		}

		private async Task Negotiate()
		{
			if (!(await base.ResourceService.SpentGTStars(NegotiateCost)))
			{
				return;
			}
			base.IsBusy = true;
			try
			{
				Update((await _sponsorService.Negotiate(_offerId, NegotiateCost)).Sponsor, 0, null);
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
			finally
			{
				base.IsBusy = false;
			}
			base.ResourceService.Update();
		}

		public void Update(SponsorData sponsor, int negotiateCost, string managerName)
		{
			_offerId = sponsor.OfferId;
			if (!string.IsNullOrEmpty(managerName))
			{
				ManagerName = managerName;
			}
			Name = sponsor.Name;
			Description = sponsor.Description;
			Date = sponsor.Date.ParseToDate().ToGTDateTimeString();
			DateTitle = (sponsor.Accepted ? "ContractUntil".Translate() : "OfferFrom".Translate());
			Accepted = sponsor.Accepted;
			if (sponsor.Amounts.Length == 3)
			{
				OfferValue1 = sponsor.Amounts[0].Current;
				OfferValue2 = sponsor.Amounts[1].Current;
				OfferValue3 = sponsor.Amounts[2].Current;
				PreviousValue1 = sponsor.Amounts[0].Change;
				PreviousValue2 = sponsor.Amounts[1].Change;
				PreviousValue3 = sponsor.Amounts[2].Change;
				PreviousValueVisible = !Accepted && sponsor.Amounts[0].Previous > 0;
			}
			PremiumValue = sponsor.Stars;
			CardsValue = sponsor.Cards;
			if (negotiateCost > 0)
			{
				NegotiateCost = negotiateCost;
			}
			ClubViewModel.UpdateSponsor(IsMainSponsor, sponsor.Accepted);
		}
	}
