		private async Task UpdateEquipment(EquipmentType equipment)
		{
			EquipmentResponse equipmentResponse = await _shopService.GetEquipment(equipment);
			if (equipment == EquipmentType.Shirt || equipment == EquipmentType.All)
			{
				MyShirts = GetEquipment(equipmentResponse.MyShirts, "", "", 1, null, UseAsHome, UseAsAway);
				Shirts = GetEquipment(equipmentResponse.Shirts, "", "Buy".Translate(), 1, BuyShirt);
			}
			if (equipment == EquipmentType.Emblem || equipment == EquipmentType.All)
			{
				MyEmblems = GetEquipment(equipmentResponse.MyEmblems, "_normal", "Activate".Translate(), 0, UseEmblem);
				Emblems = GetEquipment(equipmentResponse.Emblems, "_normal", "Buy".Translate(), 1, BuyEmblem);
			}
