		private List<EquipmentItem> GetEquipment(List<EquipmentData> src, string imageSuffix = "", string buttonText = "", int costMultiplier = 1, Func<EquipmentData, Task> buttonTask = null, Func<EquipmentData, Task> homeCommandTask = null, Func<EquipmentData, Task> awayCommandTask = null)
		{
			List<EquipmentItem> list = new List<EquipmentItem>();
			if (src == null)
			{
				return list;
			}
			foreach (EquipmentData item in src)
			{
				list.Add(new EquipmentItem
				{
					Image = item.Image + imageSuffix,
					InUse = item.InUse,
					Cost = item.Cost * costMultiplier,
					ButtonText = buttonText,
					HomeCommand = ((homeCommandTask != null) ? new AsyncCommand<EquipmentData>(homeCommandTask) : null),
					AwayCommand = ((awayCommandTask != null) ? new AsyncCommand<EquipmentData>(awayCommandTask) : null),
					Command = ((buttonTask != null) ? new AsyncCommand<EquipmentData>(buttonTask) : null),
					CommandParameter = item
				});
			}
			return list;
		}

