		{
			base.IsBusy = true;
			await _shopService.UseEquipment(equipment.Id, equipmentCode, useCode);
			await UpdateEquipment(equipmentCode);
			base.IsBusy = false;
		}

		private async Task BuyShirt(EquipmentData shirt)
		{
			await Buy(shirt, EquipmentType.Shirt);
