		private async Task Buy(EquipmentData equipment, EquipmentType equipmentCode)
		{
			string title = ((equipmentCode == EquipmentType.Shirt) ? "BuyShirts".Translate() : "BuyEmblems".Translate());
			string format = ((equipmentCode == EquipmentType.Shirt) ? "BuyShirtsQuestion".Translate() : "BuyEmblemsQuestion".Translate());
			if (await base.ResourceService.SpentGTStars(equipment.Cost, title, string.Format(format, equipment.Cost)))
			{
				base.IsBusy = true;
				await _shopService.BuyEquipment(equipment.Id, equipmentCode, equipment.Cost);
				await UpdateEquipment(equipmentCode);
				base.ResourceService.Update();
				base.IsBusy = false;
				_navigationService.NavigateTo(ScreenIdentifier.Equipment, (equipmentCode != EquipmentType.Shirt) ? 2 : 0);
			}
		}
	}
	public class ChartData
	{
		public string Label { get; set; }

		public string ValueLabel { get; set; }

		public float Value { get; set; }

		private static ChartData FromDateValue(DateTime date, decimal value, string valueFormat = null)
		{
			return new ChartData
			{
				Label = $"{date:dd.MM}",
				Value = (float)value,
				ValueLabel = (string.IsNullOrEmpty(valueFormat) ? ((long)value).ToShortValue() : value.ToString(valueFormat))
			};
		}

		public static List<ChartData> CreateChart<T>(IEnumerable<T> source, Func<T, DateTime> dateSelector, Func<T, decimal> valueSelector, string valueFormat = null)
		{
			if (source == null || source.Count() == 0)
			{
				return new List<ChartData>();
			}
			List<ChartData> list = source.Select((T x) => FromDateValue(dateSelector(x), valueSelector(x), valueFormat)).ToList();
			float num = list.Min((ChartData x) => x.Value);
			float num2 = list.Max((ChartData x) => x.Value);
			if (num == num2)
			{
				return list;
			}
			float num3 = num - (num2 - num) * 0.1f;
			foreach (ChartData item in list)
			{
				item.Value -= num3;
			}
			return list;
		}
	}
