		private void SetMode(FinanceChartMode chartMode)
		{
			List<ChartData> list = chartMode switch
			{
				FinanceChartMode.Income => Income, 
				FinanceChartMode.Outcome => Outcome, 
				_ => Balance, 
			};
			if (list == null || list.Count == 0)
			{
				ChartMode = FinanceChartMode.None;
			}
			else
			{
				ChartMode = chartMode;
			}
		}

		public override async Task Update()
		{
			base.Title = "Finances".Translate();
			try
			{
				await UpdateFinances();
				await UpdateHistory();
			}
			catch (Exception ex)
			{
				ChartMode = FinanceChartMode.None;
				AppAnalytics.Instance.TrackError(ex);
			}
		}

		private async Task UpdateFinances()
		{
			FinancesResponse financesResponse = await _teamService.GetFinances();
			if (financesResponse != null)
			{
				YesterdaysTotal = GetTotal(financesResponse.Yesterdays);
				TodaysTotal = GetTotal(financesResponse.Todays);
				Today = string.Format("Today".Translate(), Math.Max(financesResponse.Today, 1));
				Yesterday = string.Format("Yesterday".Translate(), financesResponse.Yesterday);
				Yesterdays = GetTableRows(financesResponse.Yesterdays, "Yesterdays");
				Todays = GetTableRows(financesResponse.Todays, "Todays");
			}
		}

		private List<ITableRow> GetTableRows(List<FinanceData> finances, string property)
		{
			List<ITableRow> list = new List<ITableRow>();
			foreach (IGrouping<(string, bool), FinanceData> item in from x in finances
				group x by (BookingType: x.BookingType, IsEarning: x.IsEarning))
			{
				decimal num = item.Sum((FinanceData x) => x.Value);
				ExpandableTableRow row = new ExpandableTableRow(new ImageCell("arrow_right"), new TextCell(item.Key.Item1), new TextCell(string.Format("{0}{1:N0} {2}", item.Key.Item2 ? "+" : "-", num, "€"), TableCellAlignment.Right, item.Key.Item2 ? TableCellColor.Positive : TableCellColor.Default));
				foreach (FinanceData item2 in item)
				{
					row.Subrows.Add(new TableRow(new ImageCell(string.Empty), new TextCell("        " + ((!string.IsNullOrEmpty(item2.Description)) ? item2.Description : item.Key.Item1)), new TextCell(string.Format("{0}{1:N0} {2}", item.Key.Item2 ? "+" : "-", item2.Value, "€"), TableCellAlignment.Right, item.Key.Item2 ? TableCellColor.Positive : TableCellColor.Default))
					{
						Background = TableRowBackground.Inactive
					});
				}
				row.Command = new Command(delegate
				{
					ExpandCollapse(row, list, property);
				});
				list.Add(row);
			}
			return list;
		}

		private void ExpandCollapse(ExpandableTableRow selectedRow, List<ITableRow> list, string property)
		{
			List<ITableRow> list2 = new List<ITableRow>();
			foreach (ITableRow item in list)
			{
				if (item is ExpandableTableRow expandableTableRow)
				{
					if (expandableTableRow != selectedRow)
					{
						expandableTableRow.IsExpanded = false;
					}
				}
				else
				{
					list2.Add(item);
				}
			}
			foreach (ITableRow item2 in list2)
			{
				list.Remove(item2);
			}
			selectedRow.IsExpanded = !selectedRow.IsExpanded;
			if (selectedRow.IsExpanded)
			{
				list.InsertRange(list.IndexOf(selectedRow) + 1, selectedRow.Subrows);
			}
			OnPropertyChanged(property);
		}

		private ITableRow GetTotal(List<FinanceData> list)
		{
			decimal num = list.Sum((FinanceData x) => x.Value * (decimal)(x.IsEarning ? 1 : (-1)));
			bool flag = num > 0m;
			return new TableRow(new ImageCell(string.Empty), new TextCell("Total".Translate(), TableCellAlignment.Left, TableCellColor.Accent), new TextCell(string.Format("{0}{1:N0} {2}", flag ? "+" : "-", Math.Abs(num), "€"), TableCellAlignment.Right, flag ? TableCellColor.Positive : TableCellColor.Default));
		}

		private async Task UpdateHistory()
		{
			if (Balance != null && _lastHistoryFetched.Date == DateTime.Now.Date)
			{
				return;
			}
			_lastHistoryFetched = DateTime.Now;
			FinanceHistoryResponse financeHistoryResponse = await _teamService.GetFinanceHistory();
			if (financeHistoryResponse.FinanceHistory == null || financeHistoryResponse.FinanceHistory.Count <= 1)
			{
				ChartMode = FinanceChartMode.None;
				return;
			}
			Income = ChartData.CreateChart(financeHistoryResponse.FinanceHistory, (FinanceHistoryData x) => x.Date, (FinanceHistoryData x) => x.Income);
			Outcome = ChartData.CreateChart(financeHistoryResponse.FinanceHistory, (FinanceHistoryData x) => x.Date, (FinanceHistoryData x) => x.Outcome);
			Balance = ChartData.CreateChart(financeHistoryResponse.FinanceHistory, (FinanceHistoryData x) => x.Date, (FinanceHistoryData x) => x.Balance);
			if (ChartMode == FinanceChartMode.Loading)
			{
				ChartMode = FinanceChartMode.Balance;
			}
		}
	}
