		public override async Task Init()
		{
			base.IsBusy = true;
			await Update();
			await InitChildViewModels();
			await Search();
			base.IsBusy = false;
		}

		public override async Task Update()
		{
			base.Title = "Friends".Translate();
			ChallengesResponse challengesResponse = await _friendsService.GetChallenges();
			UpdateFriends(challengesResponse.Friends);
			UpdateChallenges(challengesResponse.Challenges);
		}

		private void UpdateSearchList(List<FriendData> friends)
		{
			_foundFriends = friends;
			List<ITableRow> list = new List<ITableRow>();
			if (_foundFriends != null)
			{
				foreach (FriendData friend in friends)
				{
					TableCell tableCell = (friend.MyLike ? new ImageButtonCell("button_decline", _declineCommand, friend.TeamId) : new ImageButtonCell("button_add", _acceptCommand, friend.TeamId));
					list.Add(new TableRow(new ImageCell("flag_" + friend.Country), new ImageCell(friend.TeamLogo + "_normal"), new TextCell(friend.TeamName), new StrengthCell(friend.Strength, forPlayer: false), new TextCell(friend.UserName, TableCellAlignment.Center), tableCell)
					{
						Command = _showClubCommand,
						CommandParameter = friend.TeamId
					});
				}
			}
			FriendsSearchTable = list;
		}

		private async Task ShowComparePopup(Guid teamId)
		{
			await ShowCompare(teamId, showClub: false);
		}

		private async Task ShowClubInfoPopup(Guid teamId)
		{
			await ShowCompare(teamId, showClub: true);
		}

		private async Task ShowCompare(Guid teamId, bool showClub)
		{
			await base.PopupService.ShowPopupAsync(new ComparePopupViewModel(showClub)
			{
				TeamId = teamId
			});
		}

		private void UpdateFriends(List<FriendData> myFriends)
		{
			if (myFriends == null || myFriends.Count == 0)
			{
				MyFriendsTable = null;
				return;
			}
			List<ITableRow> list = new List<ITableRow>();
			FriendData[] array = (from x in myFriends
				where !x.MyLike && x.LikesMe
				orderby x.TeamName
				select x).ToArray();
			FriendData[] array2 = (from x in myFriends
				where x.MyLike && x.LikesMe
				orderby x.TeamName
				select x).ToArray();
			FriendData[] array3 = (from x in myFriends
				where x.MyLike && !x.LikesMe
				orderby x.TeamName
				select x).ToArray();
			AddFriendSection(list, array, "FriendshipRequests".Translate() + $": {array.Length}", TableRowBackground.New);
			AddFriendSection(list, array2, "MyFriends".Translate() + $": {array2.Length}");
			AddFriendSection(list, array3, "PendingInvites".Translate() + $": {array3.Length}", TableRowBackground.Inactive);
			MyFriendsTable = list;
		}

		private void UpdateChallenges(List<ChallengeData> challenges)
		{
			if (challenges == null || challenges.Count == 0)
			{
				ChallengesTable = null;
				return;
			}
			List<ITableRow> list = new List<ITableRow>();
			ChallengeData booked = challenges.FirstOrDefault((ChallengeData x) => x.IsAccepted && (x.HomeScore < 0 || x.AwayScore < 0 || x.MatchDate.ParseToDate().AddMinutes(115.0) > DateTime.UtcNow));
			if (booked != null)
			{
				AddChallengeSection(list, new ChallengeData[1] { booked }, 0, "FriendlyMatch".Translate(), TableRowBackground.Default, _showCompareCommand, (ChallengeData x) => x.OpponentTeamId);
			}
			else
			{
				ChallengeData[] array = challenges.Where((ChallengeData x) => x.MyTeam == 2 && !x.IsDeclined && (x.HomeScore < 0 || x.AwayScore < 0)).ToArray();
				ChallengeData[] array2 = challenges.Where((ChallengeData x) => x.MyTeam == 1 && (x.HomeScore < 0 || x.AwayScore < 0)).ToArray();
				AddChallengeSection(list, array, 2, "FriendlyMatchRequests".Translate() + $": {array.Length} / 5", TableRowBackground.New, _showCompareCommand, (ChallengeData x) => x.OpponentTeamId);
				AddChallengeSection(list, array2, 3, "SentRequests".Translate() + $": {array2.Length} / 5", TableRowBackground.Default, _showCompareCommand, (ChallengeData x) => x.OpponentTeamId);
			}
			ChallengeData[] challenges2 = challenges.Where((ChallengeData x) => x != booked && x.HomeScore >= 0 && x.AwayScore >= 0).ToArray();
			AddChallengeSection(list, challenges2, 1, "MatchHistory".Translate(), TableRowBackground.Inactive, _openMatchCommand, (ChallengeData x) => x.MatchId);
			ChallengesTable = list;
		}

		private void AddFriendSection(List<ITableRow> list, FriendData[] friends, string sectionName, TableRowBackground background = TableRowBackground.Default)
		{
			if (friends.Length != 0)
			{
				list.Add(new SectionRow
				{
					Name = sectionName,
					Alignment = TableCellAlignment.Center,
					Background = background
				});
				foreach (FriendData friendData in friends)
				{
					list.Add(new TableRow(new ImageCell("flag_" + friendData.Country), new ImageCell(friendData.TeamLogo + "_normal"), new TextCell(friendData.TeamName), new StrengthCell(friendData.Strength, forPlayer: false), new TextCell(friendData.UserName, TableCellAlignment.Center), GetAcceptCell(friendData), new DeclineButtonCell(_declineCommand, friendData.TeamId), GetChallengeCell(friendData))
					{
						Background = background,
						Command = _showClubCommand,
						CommandParameter = friendData.TeamId
					});
				}
			}
		}

		private void AddChallengeSection(List<ITableRow> list, ChallengeData[] challenges, int id, string sectionName, TableRowBackground background = TableRowBackground.Default, ICommand selectCommand = null, Func<ChallengeData, Guid> parameterFunction = null)
		{
			if (challenges.Length != 0)
			{
				list.Add(new SectionRow
				{
					Name = sectionName,
					Alignment = TableCellAlignment.Center,
					Background = background
				});
				foreach (ChallengeData challengeData in challenges)
				{
					list.Add(new TableRow(new ImageButtonCell("flag_" + challengeData.HomeCountry), new ImageButtonCell(challengeData.HomeLogo + "_normal"), new TextCell(challengeData.HomeName), GetChallengeMultiTextCell(challengeData, id), GetChallengeSignCell(challengeData, id), GetChallengeAcceptCell(challengeData, id), GetChallengeDeclineCell(challengeData, id))
					{
						Background = background,
						Command = selectCommand,
						CommandParameter = parameterFunction?.Invoke(challengeData)
					});
				}
			}
		}

		private void OpenMatch(Guid matchId)
		{
			ComponentFactory.Resolve<LiveViewModel>().MatchId = matchId;
			base.NavigationService.NavigateTo(ScreenIdentifier.Modal_Live);
		}

		private ImageButtonCell GetAcceptCell(FriendData myFriend)
		{
			if (myFriend.LikesMe && myFriend.MyLike)
			{
				return new ImageButtonCell("friendly_match");
			}
			if (myFriend.LikesMe)
			{
				return new ImageButtonCell("button_accept_selector", _acceptCommand, myFriend.TeamId);
			}
			return new ImageButtonCell(string.Empty);
		}

		private ButtonCell GetChallengeCell(FriendData myFriend)
		{
			return myFriend.ChallengeStatus switch
			{
				1 => new ButtonCell("Challenge".Translate(), ButtonType.Standart, 0, _sendChallengeCommand, myFriend), 
				2 => new ButtonCell("Challenge".Translate(), ButtonType.Inactive), 
				3 => new ButtonCell("Accept".Translate(), ButtonType.Standart, 0, _acceptChallengeCommand, myFriend.ChallengeId)
				{
					TextColor = TableCellColor.Highlight
				}, 
				4 => new ButtonCell("Sent".Translate(), ButtonType.None)
				{
					TextColor = TableCellColor.Accent
				}, 
				5 => new ButtonCell("BookedSign".Translate(), ButtonType.None)
				{
					TextColor = TableCellColor.Highlight
				}, 
				6 => new ButtonCell("Declined".Translate(), ButtonType.None), 
				7 => new ButtonCell("Challenged".Translate(), ButtonType.None), 
				_ => new ButtonCell("Challenge".Translate(), ButtonType.Inactive), 
			};
		}

		private MultiTextCell GetChallengeMultiTextCell(ChallengeData match, int id)
		{
			return id switch
			{
				0 => new MultiTextCell((match.MatchDate.ParseToDate() < DateTime.UtcNow) ? "LiveTicker".Translate() : "Booked".Translate(), match.MatchDate.ParseToDate().ToGTShortDateString() ?? "", null, TableCellAlignment.Center, TableCellColor.Highlight), 
				1 => new MultiTextCell($"{match.HomeScore} : {match.AwayScore}", match.Date.ParseToDate().ToGTShortDateString() ?? "", null, TableCellAlignment.Center, TableCellColor.Default, TableCellFontSize.Large), 
				2 => new MultiTextCell("New".Translate(), null, null, TableCellAlignment.Center, TableCellColor.Accent), 
				3 => new MultiTextCell("Waiting".Translate()), 
				_ => new MultiTextCell(string.Empty), 
			};
		}

		private TextCell GetChallengeSignCell(ChallengeData match, int id)
		{
			if (id == 2)
			{
				return new TextCell("AcceptSign".Translate(), TableCellAlignment.Right);
			}
			return new TextCell(match.AwayName, TableCellAlignment.Right);
		}

		private ImageButtonCell GetChallengeAcceptCell(ChallengeData challenge, int id)
		{
			if (id == 2)
			{
				return new ImageButtonCell("button_accept_selector", _acceptChallengeCommand, challenge.Id);
			}
			return new ImageButtonCell(challenge.AwayLogo + "_normal");
		}

		private ImageButtonCell GetChallengeDeclineCell(ChallengeData challenge, int id)
		{
			if (id == 2)
			{
				return new ImageButtonCell("button_decline_selector", _declineChallengeCommand, challenge.Id);
			}
			return new ImageButtonCell("flag_" + challenge.AwayCountry);
		}

		private async Task OnSearch()
		{
			base.IsBusy = true;
			await Search();
			base.IsBusy = false;
		}

		private async Task Search()
		{
			UpdateSearchList((await _friendsService.GetFriends(SearchedText, SelectedLanguage)).Friends);
		}

		private void Reset()
		{
			SearchedText = null;
			SelectedLanguage = null;
		}

		private async Task Decline(Guid teamId)
		{
			base.IsBusy = true;
			UpdateFriends((await _friendsService.Decline(teamId))?.Friends);
			UpdateSearchFriend(teamId);
			base.IsBusy = false;
		}

		private async Task Accept(Guid teamId)
		{
			base.IsBusy = true;
			UpdateFriends((await _friendsService.Accept(teamId))?.Friends);
			UpdateSearchFriend(teamId);
			base.IsBusy = false;
		}

		private async Task SendChallenge(FriendData friendData)
		{
			if (await base.PopupService.ShowYesNoMessageAsync("FriendlyMatch".Translate(), string.Format("CompareChallengeClub".Translate(), friendData.TeamName)))
			{
				base.IsBusy = true;
				ChallengesResponse challengesResponse = await _friendsService.SendChallenge(friendData.TeamId);
				UpdateChallenges(challengesResponse?.Challenges);
				UpdateFriends(challengesResponse?.Friends);
				base.IsBusy = false;
			}
		}

		private async Task ReplyChallenge(Guid challengeId, bool accept)
		{
			base.IsBusy = true;
			ChallengesResponse challengesResponse = await _friendsService.ReplyChallenge(challengeId, accept);
			UpdateChallenges(challengesResponse?.Challenges);
			UpdateFriends(challengesResponse?.Friends);
			base.IsBusy = false;
		}

		private async Task AcceptChallenge(Guid challengeId)
		{
			await ReplyChallenge(challengeId, accept: true);
		}

		private async Task DeclineChallenge(Guid challengeId)
		{
			await ReplyChallenge(challengeId, accept: false);
		}

		private void UpdateSearchFriend(Guid teamId)
		{
			base.IsBusy = true;
			if (_foundFriends != null)
			{
				FriendData friendData = _foundFriends.FirstOrDefault((FriendData x) => x.TeamId == teamId);
				if (friendData != null)
				{
					friendData.MyLike = !friendData.MyLike;
					UpdateSearchList(_foundFriends.ToList());
					base.IsBusy = false;
				}
			}
		}
	}
	public class LadderViewModel : TimerViewModel
	{
		private readonly string _ladderTitle = "GTLadder".Translate();

		private readonly Dictionary<Guid, int> _previousPositions;

		private List<ITableRow> _ladderTable;

		private List<ITableRow> _rewardsTable;

		private int _tutorialTeamIndex;

		private Guid _ladderId;

		private readonly ILadderService _ladderService;

		private readonly IPopupService _popupService;

		private readonly INavigationService _navigationService;

		public List<ITableRow> LadderTable
		{
			get
			{
				return _ladderTable;
			}
			set
			{
				Set(ref _ladderTable, value, "LadderTable");
			}
		}

		public List<ITableRow> RewardsTable
		{
			get
			{
				return _rewardsTable;
			}
			set
			{
				Set(ref _rewardsTable, value, "RewardsTable");
			}
		}

		public int TutorialTeamIndex
		{
			get
			{
				return _tutorialTeamIndex;
			}
			set
			{
				Set(ref _tutorialTeamIndex, value, "TutorialTeamIndex");
			}
		}

		public bool CanLeave { get; private set; } = true;

		public ICommand OpenLadderPopupCommand { get; }

		public HeaderRow LadderListHeader => new HeaderRow(new HeaderCell("PositionAbbreviation".Translate(), 10, TableCellAlignment.Center), new HeaderCell(CellType.Image, 10), new HeaderCell(CellType.Image, 10), new HeaderCell("Club".Translate(), 35), new HeaderCell("Strength".Translate(), 50, TableCellAlignment.Center, CellType.Strength), new HeaderCell("GoalsAbbreviation".Translate(), 15, TableCellAlignment.Center), new HeaderCell("GoalsDifferenceAbbreviation".Translate(), 12, TableCellAlignment.Center), new HeaderCell(CellType.Image, 15), new HeaderCell("PointsAbbreviation".Translate(), 15, TableCellAlignment.Center));

		public HeaderRow RewardsListHeader => new HeaderRow(new HeaderCell("PositionAbbreviation".Translate(), 12, TableCellAlignment.Center), new HeaderCell(CellType.Image, 15), new HeaderCell(CellType.Image, 15), new HeaderCell("Club".Translate(), 40), new HeaderCell("Reward".Translate(), 40, TableCellAlignment.Center));

		public ICommand SelectedTeamCommand { get; }

		public ICommand OpenLineupCommand { get; }

		public LadderViewModel(ILadderService ladderService, IPopupService popupService, INavigationService navigationService)
		{
			SelectedTeamCommand = new AsyncCommand<Guid>(ShowLadderPopup);
			OpenLineupCommand = new Command(GoToLineup);
			_ladderService = ladderService;
			_popupService = popupService;
			_navigationService = navigationService;
			_previousPositions = new Dictionary<Guid, int>();
			ShellViewModel shellViewModel = ComponentFactory.Resolve<ShellViewModel>();
			shellViewModel.SetContextMenuImage(ScreenIdentifier.GTLadder, -1, "menu_ladder");
			shellViewModel.AddContextMenuItem(ScreenIdentifier.GTLadder, -1, "Lineup".Translate(), OpenLineupCommand);
		}

		private void GoToLineup()
		{
			LineupFormationViewModel lineupFormationViewModel = ComponentFactory.Resolve<LineupFormationViewModel>();
			lineupFormationViewModel.IsFriendly = false;
			lineupFormationViewModel.MatchId = Guid.Empty;
			_navigationService.NavigateTo(ScreenIdentifier.Lineup_Formation);
		}

		public override async Task Update()
		{
			base.Title = _ladderTitle;
			base.IsBusy = true;
			LadderResponse ladderResponse = await _ladderService.GetLadder();
			if (ladderResponse == null || ladderResponse.Teams == null || ladderResponse.Teams.Count == 0)
			{
				base.IsBusy = false;
				LadderTable = null;
				return;
			}
			_ladderId = ladderResponse.LadderId;
			UpdateLadderTable(ladderResponse);
			UpdateRewardsTable(ladderResponse);
			SetEndDate(ladderResponse.EndDate.ParseToDate());
			if (TutorialManager.Instance.InProgress)
			{
				TutorialTeamIndex = LadderTable.FindIndex((ITableRow x) => x is TableRow { CommandParameter: var commandParameter } && Guid.TryParse(commandParameter?.ToString(), out var result) && result == Guids.LadderTeamId);
			}
			base.IsBusy = false;
		}

		private void UpdateLadderTable(LadderResponse ladderResponse)
		{
			List<ITableRow> list = new List<ITableRow>();
			List<LadderTeamData> teams = ladderResponse.Teams;
			int num = 0;
			for (int i = 0; i < teams.Count; i++)
			{
				LadderTeamData ladderTeamData = teams[i];
				string tutorialControlId = null;
				if (TutorialManager.Instance.InProgress && ladderTeamData.TeamId == Guids.LadderTeamId)
				{
					tutorialControlId = "button_choose_club";
				}
				else if (ladderTeamData.TeamId == Guids.LadderTeamId)
				{
					continue;
				}
				num++;
				string imageName = string.Empty;
				if (_previousPositions.TryGetValue(ladderTeamData.TeamId, out var value))
				{
					imageName = ((num > value) ? "arrow_out" : ((num >= value) ? string.Empty : "arrow_in"));
				}
				_previousPositions[ladderTeamData.TeamId] = num;
				TableCellColor teamColor = ladderTeamData.GetTeamColor();
				TableRowBackground background = ((i <= 2) ? TableRowBackground.New : TableRowBackground.Default);
				Log.Info($"{ladderTeamData.Name}, strength = {ladderTeamData.Strength}");
				list.Add(new TableRow(new TextCell($"{num}", TableCellAlignment.Center, teamColor), new ImageCell("flag_" + ladderTeamData.Country), new ImageCell(ladderTeamData.Logo + "_normal"), new TextCell(ladderTeamData.Name, TableCellAlignment.Left, teamColor), GetStrengthCell(ladderTeamData), new TextCell($"{ladderTeamData.GoalsScored} : {ladderTeamData.GoalsReceived}", TableCellAlignment.Center, teamColor), new TextCell($"{ladderTeamData.GoalsScored - ladderTeamData.GoalsReceived}", TableCellAlignment.Center, teamColor), new ImageCell(imageName), GetPointsCell(ladderTeamData, teamColor))
				{
					Background = background,
					Command = ((!ladderTeamData.IsMine && !ladderTeamData.Played) ? SelectedTeamCommand : null),
					CommandParameter = ladderTeamData.TeamId,
					TutorialControlId = tutorialControlId
				});
			}
			LadderTable = list;
		}

		private void UpdateRewardsTable(LadderResponse ladderResponse)
		{
			List<ITableRow> list = new List<ITableRow>();
			List<LadderTeamData> teams = ladderResponse.Teams;
			int num = Math.Min(15, teams?.Count ?? 0);
			for (int i = 0; i < num; i++)
			{
				LadderTeamData ladderTeamData = teams[i];
				TableCellColor teamColor = ladderTeamData.GetTeamColor();
				TableRowBackground background = ((i <= 2) ? TableRowBackground.New : TableRowBackground.Default);
				TableCellColor color = i switch
				{
					0 => TableCellColor.Highlight, 
					1 => TableCellColor.Accent, 
					_ => TableCellColor.Default, 
				};
				TableCell tableCell = ((i >= 10) ? new TextCell($"{100000 - (i - 9) * 10000:N0}€", TableCellAlignment.Center, color, TableCellFontSize.Large) : new TextCell($"{1000000 - i * 100000:N0}€", TableCellAlignment.Center, color, TableCellFontSize.Large));
				list.Add(new TableRow(new TextCell($"{i + 1}", TableCellAlignment.Center, teamColor), new ImageCell("flag_" + ladderTeamData.Country), new ImageCell(ladderTeamData.Logo + "_normal"), new TextCell(ladderTeamData.Name, TableCellAlignment.Left, teamColor), tableCell)
				{
					Background = background
				});
			}
			RewardsTable = list;
		}

		private async Task ShowLadderPopup(Guid teamId)
		{
			base.IsBusy = true;
			CanLeave = false;
			LadderPopupViewModel popup = new LadderPopupViewModel(_ladderId, teamId);
			await _popupService.ShowPopupAsync(popup);
			CanLeave = true;
			if (popup.IsGameStarted)
			{
				await Update();
			}
		}

		private StrengthCell GetStrengthCell(LadderTeamData team)
		{
			if (team.Strength < 0m)
			{
				return new StrengthCell(0m, forPlayer: false);
			}
			return new StrengthCell(team.Strength, forPlayer: false);
		}

		private TextCell GetPointsCell(LadderTeamData team, TableCellColor color)
		{
			if (team.Points < 0)
			{
				return new TextCell("-", TableCellAlignment.Center, color);
			}
			return new TextCell($"{team.Points}", TableCellAlignment.Center, color);
		}

		protected override void OnTimerRefresh(TimeSpan timeLeft, bool isFininshed)
		{
			if (isFininshed)
			{
				base.Title = _ladderTitle;
				LadderTable = null;
			}
			else
			{
				base.Title = _ladderTitle + " - " + timeLeft.ToLocalizedString();
			}
		}
	}
