		public override async Task Update()
		{
			base.Title = "League".Translate();
			_leagueTableResponse = await _leagueService.GetLeagueTable(Guid.Empty);
			MatchesResponse matchesResponse = await _leagueService.GetMatches(Guid.Empty);
			ShowLeagueTable(home: true, away: true);
			if (matchesResponse != null && matchesResponse.Matches != null && matchesResponse.Matches.Count > 0)
			{
				List<ITableRow> list = new List<ITableRow>();
				IEnumerable<IGrouping<string, MatchData>> enumerable = from x in matchesResponse.Matches
					group x by x.Date;
				int num = 1;
				foreach (IGrouping<string, MatchData> item in enumerable)
				{
					list.Add(new SectionRow
					{
						Name = "Matchday".Translate() + $" {num} - {item.Key.ParseToDate().ToGTDateTimeString()}",
						Alignment = TableCellAlignment.Center
					});
					foreach (MatchData item2 in item)
					{
						TableCellColor teamColor = item2.GetTeamColor();
						list.Add(new TableRow(new ImageCell("flag_" + item2.HomeCountry), new ImageCell(item2.HomeLogo + "_normal"), new TextCell(item2.HomeName, TableCellAlignment.Left, teamColor), new TextCell(item2.GetMatchScore(), TableCellAlignment.Center, teamColor, TableCellFontSize.Large), new TextCell(item2.AwayName, TableCellAlignment.Right, teamColor), new ImageCell(item2.AwayLogo + "_normal"), new ImageCell("flag_" + item2.AwayCountry))
						{
							Command = _showMatchCommand,
							CommandParameter = item2.Id
						});
					}
					num++;
				}
				MatchesTable = list;
				IEnumerable<MatchData> enumerable2 = matchesResponse.Matches.Where((MatchData x) => x.MyTeam > 0);
				List<ITableRow> list2 = new List<ITableRow>();
				foreach (MatchData item3 in enumerable2)
				{
					TableCellColor fixtureColor = item3.GetFixtureColor();
					string text = null;
					string imageName = null;
					DateTime dateTime = item3.Date.ParseToDate();
					if (item3.HasScore)
					{
						text = item3.GetMatchScore();
					}
					else
					{
						double totalMinutes = (dateTime - DateTime.UtcNow).TotalMinutes;
						if (totalMinutes < 60.0 && totalMinutes > 0.0)
						{
							text = $"{totalMinutes:N0} " + "Minutes".Translate();
						}
						else if (totalMinutes < 0.0 && totalMinutes > -95.0)
						{
							text = "Live".Translate();
						}
						else if (item3.HasLineup)
						{
							imageName = "haken";
						}
						else if (item3.MyTeam == 1)
						{
							imageName = matchesResponse.HomeTrikot ?? "";
						}
						else if (item3.MyTeam == 2)
						{
							imageName = matchesResponse.AwayTrikot ?? "";
						}
						else
						{
							text = "- : -";
						}
					}
					list2.Add(new TableRow(new TextCell(item3.Date.ParseToDate().ToGTDateTimeString(), TableCellAlignment.Center, fixtureColor), new ImageCell(item3.HomeLogo + "_normal"), new TextCell(item3.HomeName, TableCellAlignment.Left, fixtureColor), new ImageCell(item3.AwayLogo + "_normal"), new TextCell(item3.AwayName, TableCellAlignment.Left, fixtureColor), new ImageTextCell(imageName, text)
					{
						Color = fixtureColor
					})
					{
						Command = (item3.HasScore ? _showMatchCommand : _showLineupCommand),
						CommandParameter = item3.Id
					});
				}
				FixtureListTable = list2;
			}
			GoalGettersResponse goalGettersResponse = await _leagueService.GetGoalGetters(Guid.Empty);
			if (goalGettersResponse == null || goalGettersResponse.Players == null || goalGettersResponse.Players.Count == 0)
			{
				GoalGettersTable = null;
				return;
			}
			List<ITableRow> list3 = new List<ITableRow>();
			GoalGetterPlayerData[] array = goalGettersResponse.Players.OrderByDescending((GoalGetterPlayerData x) => x.Goals).ToArray();
			for (int num2 = 0; num2 < array.Length; num2++)
			{
				GoalGetterPlayerData goalGetterPlayerData = array[num2];
				TableCellColor playerColor = goalGetterPlayerData.GetPlayerColor();
				list3.Add(TableRow.Create(new TextCell($"{num2 + 1}", TableCellAlignment.Center, playerColor), new AvatarCell(goalGetterPlayerData.Country, goalGetterPlayerData.Head), new TextCell(goalGetterPlayerData.Name, TableCellAlignment.Left, playerColor), new StrengthCell(goalGetterPlayerData.Strength), new DeclineButtonCell(), new TextCell(goalGetterPlayerData.TeamName, TableCellAlignment.Center, playerColor), new TextCell($"{goalGetterPlayerData.Goals}", TableCellAlignment.Center, playerColor)));
			}
			GoalGettersTable = list3;
		}

		private void ShowLeagueTable(bool home, bool away)
		{
			if (_leagueTableResponse == null || _leagueTableResponse.Teams == null || _leagueTableResponse.Teams.Count == 0)
			{
				LeagueTable = null;
				return;
			}
			List<ITableRow> list = new List<ITableRow>();
			LeagueTableData[] array = (from x in _leagueTableResponse.Teams
				orderby x.GetTotalPoints(home, away) descending, x.GetGoalDifference(home, away) descending, x.Strength descending
				select x).ToArray();
			TotalMatches = _leagueTableResponse.Teams[0].TotalMatches;
			string text = string.Empty;
			if (home && !away)
			{
				text = " - " + "HomeTable".Translate();
			}
			else if (!home && away)
			{
				text = " - " + "AwayTable".Translate();
			}
			list.Add(new SectionRow
			{
				Name = string.Format("{0} {1} - {2}{3}", "Matchday".Translate(), Math.Max(TotalMatches, 1), DateTime.Now.ToGTShortDateString(), text),
				Alignment = TableCellAlignment.Center,
				Background = ((home && away) ? TableRowBackground.New : TableRowBackground.Default)
			});
			for (int num = 0; num < array.Length; num++)
			{
				LeagueTableData leagueTableData = array[num];
				TableCellColor teamColor = leagueTableData.GetTeamColor();
				TableRowBackground background = ((home && away) ? TableRowBackground.New : TableRowBackground.Default);
				if (home && away)
				{
					if (num >= array.Length - _leagueTableResponse.Dismount)
					{
						background = TableRowBackground.Inactive;
					}
					else if (num >= _leagueTableResponse.Mount)
					{
						background = TableRowBackground.Default;
					}
				}
				list.Add(new TableRow(new TextCell($"{num + 1}", TableCellAlignment.Center, teamColor), new ImageCell("flag_" + leagueTableData.Country), new ImageCell(leagueTableData.Logo + "_normal"), new TextCell(leagueTableData.Name, TableCellAlignment.Left, teamColor), new StrengthCell(leagueTableData.Strength, forPlayer: false), new TextCell($"{leagueTableData.GetWins(home, away)}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.GetDraws(home, away)}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.GetLosses(home, away)}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.GetGoalsScored(home, away)}:{leagueTableData.GetGoalsReceived(home, away)}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.GetGoalDifference(home, away)}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.GetTotalPoints(home, away)}", TableCellAlignment.Center, teamColor))
				{
					Background = background,
					Command = (leagueTableData.IsMine ? null : _showCompareCommand),
					CommandParameter = leagueTableData.Id
				});
			}
			LeagueTable = list;
		}

