		public LineupFormationViewModel(ILineupService lineupService, IPopupService popupService, INavigationService navigationService)
		{
			_lineupService = lineupService;
			_popupService = popupService;
			_roles = new Dictionary<Guid, LineupPlayerData>
			{
				[Guids.Position_Captain] = null,
				[Guids.Position_Cornerkick] = null,
				[Guids.Position_Freekick] = null,
				[Guids.Position_Penalty] = null
			};
			FormationPlayers = new Dictionary<MatchSystemFieldData, LineupPlayerData>();
			PlaceToLineupCommand = new Command<MatchSystemFieldData>(PlaceToLineup);
			UnselectPlayerCommand = new Command<LineupPlayerData>(UnselectPlayerInTable);
			SelectPlayerCommand = new Command<LineupPlayerData>(SelectPlayer);
			SaveCommand = new AsyncCommand<bool>(SaveLineup);
			ShowPlayerRolesCommand = new AsyncCommand(ShowPlayerRoles);
			base.ShellViewModel.SetContextMenuImage(ScreenIdentifier.Lineup_Formation, 0, "menu_player");
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Lineup_Formation, 0, "PlayerRoles".Translate(), ShowPlayerRolesCommand);
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Lineup_Formation, 0, "AsStandard".Translate(), SaveCommand, true);
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Lineup_Formation, 0, "Save".Translate(), SaveCommand, false, "context_menu_save_lineup");
			navigationService.SetCanLeave(ScreenIdentifier.Lineup_Formation, CanLeave);
		}

		private bool IsSomethingChanged()
		{
			if (IsLocked)
			{
				return false;
			}
			if (_formationData == null)
			{
				return false;
			}
			if (_formationData.MatchSystemID != SelectedVisibleSystem.Id)
			{
				return true;
			}
			if (_formationData.MatchTacticID != SelectedTactic.ID)
			{
				return true;
			}
			if (_formationData.Players != null)
			{
				Dictionary<Guid, MatchSystemFieldData> selectedSystemFields = GetSelectedSystemFields();
				foreach (FormationPlayer player in _formationData.Players)
				{
					selectedSystemFields.TryGetValue(player.MatchSystemFieldID, out var value);
					if (value.DropInfo.Index < 0)
					{
						continue;
					}
					if (player.MatchStandardPositionID != null && player.MatchStandardPositionID.Count > 0)
					{
						foreach (Guid item in player.MatchStandardPositionID)
						{
							if (_roles.TryGetValue(item, out var value2) && value2 != null && value2.ID != player.PlayerID)
							{
								return true;
							}
						}
					}
					if (!FormationPlayers.TryGetValue(value, out var value3) || !(value3.ID == player.PlayerID))
					{
						return true;
					}
				}
			}
			return false;
		}

		private async Task<bool> CanLeave()
		{
			if (TutorialManager.Instance.InProgress)
			{
				_formationData = null;
				return true;
			}
			if (!IsSomethingChanged())
			{
				_formationData = null;
				return true;
			}
			if (!(await _popupService.ShowYesNoMessageAsync("Warning".Translate(), "LineupChangedQuestion".Translate())))
			{
				_formationData = null;
				return true;
			}
			await SaveLineup(asDefault: false);
			return true;
		}

		public override async Task Update()
		{
			if (IsSomethingChanged())
			{
				return;
			}
			base.IsBusy = true;
			FormationPlayers.Clear();
			MatchLineupResponse result = await _lineupService.GetMatchLineup(MatchId, IsFriendly);
			string text = " - " + "Lineup".Translate();
			if (IsFriendly)
			{
				base.Title = "FriendlyMatch".Translate() + text;
			}
			else if (MatchId == Guid.Empty)
			{
				base.Title = "GTLadder".Translate() + text;
			}
			else
			{
				base.Title = "League".Translate() + text;
			}
			if (result.Status == ResponseStatus.OK)
			{
				IsLocked = !TutorialManager.Instance.InProgress && result.IsLocked;
				CaptainBonus = result.CaptainBonus;
				CornerBonus = result.CornerBonus;
				FreekickBonus = result.FreekickBonus;
				PenaltyBonus = result.PenaltyBonus;
				Systems = result.Systems.ToComboBoxItems((MatchSystemData x) => x.Name);
				Tactics = result.Tactics.ToComboBoxItems((TacticData x) => x.Name);
				HashSet<Guid> formationIds = new HashSet<Guid>(result.FormationData.Players.Select((FormationPlayer x) => x.PlayerID));
				PlayerTableRows = PlayerRow.GetPlayersTableRows(result.Players, delegate(PlayerRow row, LineupPlayerData player)
				{
					row.IsOnField = formationIds.Contains(player.ID);
					row.LongPressCommand = SelectPlayerCommand;
					row.CommandParameter = player;
					row.Background = ((!player.IsReady) ? TableRowBackground.Warning : TableRowBackground.Default);
				}, result.HomeShirt, orderPlayers: true, showShirt: false);
				SelectedTactic = result.Tactics.FirstOrDefault((TacticData x) => x.ID == result.FormationData.MatchTacticID) ?? result.Tactics.First();
				SelectedVisibleSystem = result.Systems.FirstOrDefault((MatchSystemData x) => x.Id == result.FormationData.MatchSystemID);
				VisibleSystem = SelectedVisibleSystem;
				Dictionary<Guid, MatchSystemFieldData> selectedSystemFields = GetSelectedSystemFields();
				Dictionary<Guid, LineupPlayerData> dictionary = result.Players.ToDictionary((LineupPlayerData x) => x.ID);
				foreach (FormationPlayer player in result.FormationData.Players)
				{
					if (!selectedSystemFields.TryGetValue(player.MatchSystemFieldID, out var value) || !dictionary.TryGetValue(player.PlayerID, out var value2))
					{
						continue;
					}
					FormationPlayers[value] = value2;
					if (player.MatchStandardPositionID == null || player.MatchStandardPositionID.Count <= 0)
					{
						continue;
					}
					foreach (Guid item in player.MatchStandardPositionID)
					{
						_roles[item] = value2;
					}
				}
				PrepareForTutorial();
				OnPropertyChanged("FormationPlayers");
				UpdateTotalStrength();
				SelectedPlayer = null;
				_formationData = result.FormationData;
			}
			base.IsBusy = false;
		}

		private void PrepareForTutorial()
		{
			if (!TutorialManager.Instance.ShouldChangeLineup())
			{
				return;
			}
			LineupPlayerData lineupPlayerData = null;
			MatchSystemFieldData matchSystemFieldData = null;
			foreach (KeyValuePair<MatchSystemFieldData, LineupPlayerData> formationPlayer in FormationPlayers)
			{
				if (formationPlayer.Value.GetMainSkillIndex() == 0)
				{
					lineupPlayerData = formationPlayer.Value;
					matchSystemFieldData = formationPlayer.Key;
					break;
				}
			}
			if (matchSystemFieldData != null)
			{
				FormationPlayers.Remove(matchSystemFieldData);
				UnselectPlayerInTable(lineupPlayerData);
				TutorialManager.Instance.Parameters["<player name>"] = lineupPlayerData.Name;
				PlayerRow playerRow = GetPlayerRow(lineupPlayerData);
				playerRow.IsOnField = false;
				playerRow.TutorialControlId = "show_player";
				playerRow.ActivateTutorialControlOnTap = false;
				OnPropertyChanged("PlayerTableRows");
				TutorialPlayer = lineupPlayerData;
			}
		}

		private Dictionary<Guid, MatchSystemFieldData> GetSelectedSystemFields()
		{
			return SelectedVisibleSystem?.Fields.ToDictionary((MatchSystemFieldData x) => x.Id) ?? new Dictionary<Guid, MatchSystemFieldData>();
		}

		private PlayerRow GetPlayerRow(LineupPlayerData player)
		{
			return PlayerTableRows.OfType<PlayerRow>().FirstOrDefault((PlayerRow x) => x.Player == player);
		}

		private void SetTableRowState(LineupPlayerData player, bool isOnField)
		{
			PlayerRow playerRow = GetPlayerRow(player);
			if (playerRow != null)
			{
				playerRow.IsOnField = isOnField;
				OnPropertyChanged("PlayerTableRows");
			}
		}

		private void SelectPlayer(LineupPlayerData player)
		{
			if (IsLocked)
			{
				return;
			}
			if (SelectedPlayer == player)
			{
				OnPropertyChanged("SelectedPlayer");
			}
			else
			{
				SelectedPlayer = player;
			}
			SetTableRowState(player, isOnField: true);
			KeyValuePair<MatchSystemFieldData, LineupPlayerData>[] array = FormationPlayers.Where((KeyValuePair<MatchSystemFieldData, LineupPlayerData> x) => x.Value == player).ToArray();
			for (int num = 0; num < array.Length; num++)
			{
				KeyValuePair<MatchSystemFieldData, LineupPlayerData> keyValuePair = array[num];
				if (keyValuePair.Value == player)
				{
					FormationPlayers.Remove(keyValuePair.Key);
				}
			}
			OnPropertyChanged("FormationPlayers");
			UpdateTotalStrength();
		}

		private void PlaceToLineup(MatchSystemFieldData field)
		{
			if (field != null)
			{
				if (FormationPlayers.TryGetValue(field, out var value))
				{
					UnselectPlayerInTable(value);
				}
				FormationPlayers[field] = SelectedPlayer;
				OnPropertyChanged("FormationPlayers");
				UpdateTotalStrength();
				if (TutorialManager.Instance.InProgress)
				{
					TutorialManager.Instance.ControlActivated("show_player");
				}
			}
		}

		private void UpdateTotalStrength()
		{
			if (FormationPlayers.Count == 0)
			{
				TotalStrength = 0m;
				return;
			}
			TotalStrength = FormationPlayers.Keys.Sum((MatchSystemFieldData x) => FormationPlayers[x].GetStrengthForPositionId(x.PositionId));
		}

		private void UnselectPlayerInTable(LineupPlayerData player)
		{
			SetTableRowState(player, isOnField: false);
		}

		private void ResetTable()
		{
			foreach (ITableRow playerTableRow in PlayerTableRows)
			{
				if (playerTableRow is PlayerRow playerRow)
				{
					playerRow.IsOnField = false;
				}
			}
			OnPropertyChanged("PlayerTableRows");
		}

		private async Task ChangeSystem()
		{
			if (await _popupService.ShowYesNoMessageAsync("Warning".Translate(), "ChangeFormationSystem".Translate()))
			{
				SelectedVisibleSystem = VisibleSystem;
				FormationPlayers.Clear();
				OnPropertyChanged("FormationPlayers");
				ResetTable();
				UpdateTotalStrength();
			}
			else
			{
				VisibleSystem = SelectedVisibleSystem;
			}
		}

		protected override async void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (propertyName == "VisibleSystem" && VisibleSystem != SelectedVisibleSystem)
			{
				await ChangeSystem();
			}
		}

		private async Task SaveLineup(bool asDefault)
		{
			if (TutorialManager.Instance.InProgress)
			{
				return;
			}
			if (IsLocked)
			{
				await ShowLockedMessage();
				return;
			}
			base.IsBusy = true;
			MatchFormationData matchFormationData = new MatchFormationData
			{
				MatchTacticID = SelectedTactic.ID,
				MatchSystemID = SelectedVisibleSystem.Id,
				Players = new List<FormationPlayer>()
			};
			foreach (MatchSystemFieldData key in FormationPlayers.Keys)
			{
				LineupPlayerData lineupPlayerData = FormationPlayers[key];
				if (key == null || !(key.Id != Guid.Empty) || lineupPlayerData == null || !(lineupPlayerData.ID != Guid.Empty))
				{
					continue;
				}
				List<Guid> list = new List<Guid>();
				foreach (Guid key2 in _roles.Keys)
				{
					if (_roles[key2] == lineupPlayerData)
					{
						list.Add(key2);
					}
				}
				matchFormationData.Players.Add(new FormationPlayer
				{
					PlayerID = lineupPlayerData.ID,
					MatchSystemFieldID = key.Id,
					MatchStandardPositionID = list
				});
			}
			ResponseObject responseObject = await _lineupService.SaveLineup(matchFormationData, MatchId, IsFriendly, asDefault);
			_formationData = null;
			base.IsBusy = false;
			if (!string.IsNullOrEmpty(responseObject.ErrorMessage))
			{
				await _popupService.ShowOkMessageAsync("Warning".Translate(), responseObject.ErrorMessage, "Ok".Translate());
			}
		}

		private bool IsNotBench(MatchSystemFieldData field)
		{
			(int, Point) dropInfo = field.DropInfo;
			if (dropInfo.Item1 > -1)
			{
				return dropInfo.Item1 < 11;
			}
			return false;
		}

		private async Task ShowLockedMessage()
		{
			await _popupService.ShowOkMessageAsync("Locked".Translate(), "LineupLockedMessage".Translate(), "Ok".Translate());
		}

		private async Task ShowPlayerRoles()
		{
			if (IsLocked)
			{
				await ShowLockedMessage();
				return;
			}
			if (FormationPlayers == null || FormationPlayers.Count == 0)
			{
				_popupService.ShowOkMessage("LineupOptionsNoPlayers".Translate());
				return;
			}
			List<LineupPlayerData> list = (from x in FormationPlayers.Keys.Where(IsNotBench)
				select FormationPlayers[x]).ToList();
			if (list.Count == 0)
			{
				_popupService.ShowOkMessage("LineupOptionsNoPlayers".Translate());
				return;
			}
			LineupOptionsPopupViewModel options = new LineupOptionsPopupViewModel
			{
				Players = list,
				Captain = _roles[Guids.Position_Captain],
				Corner = _roles[Guids.Position_Cornerkick],
				Penalty = _roles[Guids.Position_Penalty],
				Freekick = _roles[Guids.Position_Freekick],
				CaptainBonus = CaptainBonus,
				CornerBonus = CornerBonus,
				FreekickBonus = FreekickBonus,
				PenaltyBonus = PenaltyBonus
			};
			if (await _popupService.ShowPopupAsync(options) == PopupResult.Done)
			{
				_roles[Guids.Position_Captain] = options.Captain;
				_roles[Guids.Position_Cornerkick] = options.Corner;
				_roles[Guids.Position_Freekick] = options.Freekick;
				_roles[Guids.Position_Penalty] = options.Penalty;
			}
		}
	}
