		public string Score
		{
			get
			{
				return _score;
			}
			set
			{
				Set(ref _score, value, "Score");
			}
		}

		public string Time
		{
			get
			{
				return _time;
			}
			set
			{
				Set(ref _time, value, "Time");
			}
		}

		public List<MatchReportEntryData> MatchEvents
		{
			get
			{
				return _matchEvents;
			}
			set
			{
				Set(ref _matchEvents, value, "MatchEvents");
			}
		}

		public bool IsWaitingVisible
		{
			get
			{
				return _isWaitingVisible;
			}
			set
			{
				Set(ref _isWaitingVisible, value, "IsWaitingVisible");
			}
		}

		public bool IsPlayersVisible
		{
			get
			{
				return _isPlayersVisible;
			}
			set
			{
				Set(ref _isPlayersVisible, value, "IsPlayersVisible");
			}
		}

		public Guid MatchId { get; set; }

		public LiveViewModel(ILiveService liveService)
		{
			_liveService = liveService;
		}

		public override async Task Update()
		{
			base.IsBusy = true;
			base.Title = "Live".Translate();
			MatchEvents = null;
			if (base.NavigationService.GetCurrentScreen() == ScreenIdentifier.Live)
			{
				MatchId = Guid.Empty;
			}
			MatchDetailsResponse matchDetailsResponse = await _liveService.GetMatchDetails(MatchId);
			if (matchDetailsResponse.Status != ResponseStatus.OK)
			{
				IsWaitingVisible = true;
				IsPlayersVisible = false;
				base.IsBusy = false;
				return;
			}
			if (string.IsNullOrEmpty(matchDetailsResponse.Report))
			{
				IsWaitingVisible = true;
				IsPlayersVisible = false;
				base.IsBusy = false;
				return;
			}
			Match = matchDetailsResponse.Match;
			base.Title = Match.HomeName + " vs " + Match.AwayName;
			try
			{
				MatchReport = JsonConvert.DeserializeObject<MatchReportData>(matchDetailsResponse.Report.Decompress());
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
				MatchReport = null;
			}
			base.IsBusy = false;
			RunTicker();
			GeneratePlayersList();
		}

		private void GeneratePlayersList()
		{
			if (MatchReport == null || Match == null)
			{
				IsPlayersVisible = false;
				return;
			}
			List<LivePlayersItem> list = new List<LivePlayersItem>
			{
				new LivePlayersItem
				{
					HomePlayerName = Match.HomeName,
					AwayPlayerName = Match.AwayName,
					IsMainAwayPlayersRow = true,
					IsMainHomePlayersRow = true,
					HomeColor = TableCellColor.Accent,
					AwayColor = TableCellColor.Accent
				}
			};
			List<LineUp> list2 = MatchReport.HomeLineUp ?? new List<LineUp>();
			List<LineUp> list3 = MatchReport.AwayLineUp ?? new List<LineUp>();
			for (int i = 0; i < Math.Max(list2.Count, list3.Count); i++)
			{
				LineUp player = ((i < list2.Count) ? list2[i] : null);
				LineUp player2 = ((i < list3.Count) ? list3[i] : null);
				bool flag = i < 11;
				list.Add(new LivePlayersItem
				{
					HomePlayerName = getPlayerName(i, player),
					AwayPlayerName = getPlayerName(i, player2),
					IsMainHomePlayersRow = flag,
					IsMainAwayPlayersRow = flag
				});
			}
			IsPlayersVisible = list.Count > 1;
			LivePlayers = list;
			static string getPlayerName(int num, LineUp lineUp)
			{
				return string.Format("{0} - {1}", num + 1, (lineUp == null) ? "..." : (lineUp.Name + ((lineUp.ShirtNr > 0) ? $" (#{lineUp.ShirtNr})" : string.Empty)));
			}
		}

		private void RunTicker()
		{
			IsWaitingVisible = Match == null;
			if (Match == null || MatchReport == null || !MatchReport.MatchEvents.Any())
			{
				return;
			}
			IEnumerable<IGrouping<int, MatchReportEntryData>> enumerable = from x in MatchReport.MatchEvents
				group x by x.Minute;
			bool flag = false;
			foreach (IGrouping<int, MatchReportEntryData> item in enumerable)
			{
				int value = 60 / item.Count();
				int num = 0;
				foreach (MatchReportEntryData item2 in item)
				{
					if (flag)
					{
						item2.Second = num + value.GetRandom();
						num = item2.Second;
					}
					else
					{
						flag = true;
					}
					item2.IsMinuteVisible = item2.Minute > 0;
				}
			}
			_lastMinute = MatchReport.MatchEvents.Last().Minute;
			if (MatchReport.MatchEvents.Count > 1)
			{
				MatchReportEntryData matchReportEntryData = MatchReport.MatchEvents.LastOrDefault((MatchReportEntryData x) => x.Type == EventType.End);
				MatchReportEntryData? matchReportEntryData2 = MatchReport.MatchEvents.LastOrDefault((MatchReportEntryData x) => x.Type == EventType.Statistic);
				matchReportEntryData.Second = 59;
				matchReportEntryData2.Minute++;
				matchReportEntryData2.Second = 0;
				matchReportEntryData2.IsMinuteVisible = false;
			}
			_startDate = Match.Date.ParseToDate();
			_endDate = _startDate.AddMinutes(_lastMinute);
			int currentMinute = GetCurrentMinute();
			MatchEvents = MatchReport.MatchEvents.Where((MatchReportEntryData x) => x.Minute - 1 <= currentMinute).Reverse().ToList();
			Refresh();
			SetEndDate(_endDate);
		}

		protected override void OnTimerRefresh(TimeSpan timeLeft, bool isFininshed)
		{
			Refresh();
		}

		private int GetCurrentMinute()
		{
			if (!(DateTime.UtcNow >= _startDate))
			{
				return -2;
			}
			return Math.Min(_lastMinute, (int)Math.Floor((DateTime.UtcNow - _startDate).TotalMinutes));
		}

		private void Refresh()
		{
			if (MatchEvents == null || MatchReport == null || MatchReport.MatchEvents == null)
			{
				return;
			}
			int num = GetCurrentMinute();
			DateTime utcNow = DateTime.UtcNow;
			TimeSpan timeSpan = utcNow - _startDate;
			if (utcNow > _endDate.AddHours(1.0))
			{
				Time = "MatchFrom".Translate() + " " + _startDate.ToGTDateTimeString();
			}
			else if (utcNow < _startDate)
			{
				Time = "KickOffAt".Translate() + " " + _startDate.ToGTDateTimeString();
			}
			else if (utcNow < _endDate)
			{
				Time = $"{Math.Floor(timeSpan.TotalMinutes):00}:{timeSpan.Seconds:00}";
			}
			else
			{
				Time = $"{_lastMinute}:00";
			}
			if (utcNow < _startDate && utcNow > _startDate.AddMinutes(-1.0))
			{
				num = -1;
			}
			int count = MatchEvents.Count;
			for (int i = count; i < MatchReport.MatchEvents.Count; i++)
			{
				MatchReportEntryData matchReportEntryData = MatchReport.MatchEvents[i];
				if (matchReportEntryData.Minute - 1 > num || matchReportEntryData.Second > timeSpan.Seconds)
				{
					break;
				}
				MatchEvents.Insert(0, matchReportEntryData);
			}
			if (MatchEvents.Count > count)
			{
				MatchEvents = MatchEvents.ToList();
			}
			MatchReportEntryData matchReportEntryData2 = MatchEvents.FirstOrDefault();
			Score = ((matchReportEntryData2 == null) ? "0 : 0" : $"{matchReportEntryData2.HomeTeamGoals} : {matchReportEntryData2.AwayTeamGoals}");
			IsWaitingVisible = MatchEvents.Count == 0;
		}
	}
