	public class LoginViewModel : BaseViewModel
	{
		private const int MinPasswordLength = 4;

		private string _login;

		private string _password;

		private readonly IAuthService _authService;

		private readonly IHelpshiftService _helpshiftService;

		private readonly IFacebookService _facebookService;

		public string Login
		{
			get
			{
				return _login;
			}
			set
			{
				Set(ref _login, value, "Login");
			}
		}

		public string Password
		{
			get
			{
				return _password;
			}
			set
			{
				Set(ref _password, value, "Password");
			}
		}

		public AsyncCommand LoginCommand { get; }

		public AsyncCommand SupportCommand { get; }

		public Command QuickStartCommand { get; }

		public Command NewPlayerCommand { get; }

		public LoginViewModel(IAuthService authService, IHelpshiftService helpshiftService, IFacebookService facebookService)
		{
			_authService = authService;
			_helpshiftService = helpshiftService;
			_facebookService = facebookService;
			LoginCommand = new AsyncCommand(LoginTask, IsLoginEnabled);
			SupportCommand = new AsyncCommand(OnSupportCommand);
			QuickStartCommand = new Command(OnQuickStartCommand);
			NewPlayerCommand = new Command(OnNewPlayerCommand);
		}

		public override Task Update()
		{
			base.Title = "Login".Translate();
			base.IsBusy = false;
			base.ShellViewModel.IsLoadingScreenVisisble = false;
			_facebookService.SetCallback(OnFacebookResult);
			return Task.FromResult(result: true);
		}

		private void OnFacebookResult(FacebookAuthResult result)
		{
			if (result.CallBack == CallbackType.Success || result.CallBack == CallbackType.Failed)
			{
				LoginViaFacebook(result).FireAndForgetSafeAsync();
			}
		}

		private async Task LoginViaFacebook(FacebookAuthResult facebookAuthResult)
		{
			base.IsBusy = true;
			AuthResponse authResponse = null;
			if (facebookAuthResult.CallBack == CallbackType.Success)
			{
				authResponse = await _authService.Login(facebookAuthResult.UserId, AuthMethod.Facebook);
			}
			base.IsBusy = false;
			if (authResponse != null)
			{
				if (authResponse.Status == ResponseStatus.OK && !string.IsNullOrEmpty(authResponse.Token))
				{
					base.ShellViewModel.IsLoadingScreenVisisble = true;
					base.NavigationService.NavigateTo(ScreenIdentifier.Club);
				}
				else if (authResponse.Status == ResponseStatus.AuthenticationError)
				{
					QuickStartViewModel quickStartViewModel = ComponentFactory.Resolve<QuickStartViewModel>();
					quickStartViewModel.IsQuickRegister = true;
					quickStartViewModel.FaceboookId = facebookAuthResult.UserId;
					base.NavigationService.NavigateTo(ScreenIdentifier.QuickStart);
				}
				else
				{
					base.PopupService.ShowErrorMessage("LoginFailed".Translate(), Character.Anna);
				}
			}
		}

		private bool IsLoginEnabled()
		{
			if (!string.IsNullOrWhiteSpace(Login) && !string.IsNullOrEmpty(Password))
			{
				return Password.Length >= 4;
			}
			return false;
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (propertyName == "Login" || propertyName == "Password")
			{
				LoginCommand.RaiseCanExecuteChanged();
			}
		}

		private async Task LoginTask()
		{
			base.IsBusy = true;
			AuthResponse authResponse = await _authService.Login(Login, Password);
			base.IsBusy = false;
			if (authResponse != null)
			{
				if (authResponse.Status != ResponseStatus.OK || string.IsNullOrEmpty(authResponse.Token))
				{
					base.PopupService.ShowErrorMessage("LoginFailed".Translate(), Character.Anna);
					return;
				}
				base.ShellViewModel.IsLoadingScreenVisisble = true;
				base.NavigationService.NavigateTo(ScreenIdentifier.Club);
			}
		}

		private async Task OnSupportCommand()
		{
			await _helpshiftService.ShowHelp(HelpSection.Contents);
		}

		private void OnQuickStartCommand()
		{
			ComponentFactory.Resolve<QuickStartViewModel>().IsQuickRegister = true;
			base.NavigationService.NavigateTo(ScreenIdentifier.QuickStart);
		}

		private void OnNewPlayerCommand()
		{
			base.NavigationService.NavigateTo(ScreenIdentifier.RegisterNewPlayer);
		}
	}
	public class QuickStartViewModel : BaseViewModel
	{
		private string _teamName;

		private CountryData _selectedCountry;

		private string _backButtonText;

		private bool _isQuickRegister;

		private string _facebookId;

		private string _version;

		private readonly IRegisterService _registerService;

		private readonly ICredentialService _credentialService;

		private readonly IAuthService _authService;

		private readonly ICommonService _commonService;

		public ICommand BackCommand { get; }

		public ICommand SelectCountryCommand { get; }

		public AsyncCommand StartCommand { get; }

		public ICommand ShowPrivacyPolicyCommand { get; }

		public string TeamName
		{
			get
			{
				return _teamName;
			}
			set
			{
				Set(ref _teamName, value, "TeamName");
				StartCommand.RaiseCanExecuteChanged();
			}
		}

		public CountryData SelectedCountry
		{
			get
			{
				return _selectedCountry;
			}
			set
			{
				Set(ref _selectedCountry, value, "SelectedCountry");
				StartCommand.RaiseCanExecuteChanged();
			}
		}

		public string BackButtonText
		{
			get
			{
				return _backButtonText;
			}
			set
			{
				Set(ref _backButtonText, value, "BackButtonText");
			}
		}

		public bool IsQuickRegister
		{
			get
			{
				return _isQuickRegister;
			}
			set
			{
				Set(ref _isQuickRegister, value, "IsQuickRegister");
				BackButtonText = (_isQuickRegister ? "SignInSignUp".Translate() : "Back".Translate());
			}
		}

		public string FaceboookId
		{
			get
			{
				return _facebookId;
			}
			set
			{
				Set(ref _facebookId, value, "FaceboookId");
			}
		}

		public string Version
		{
			get
			{
				return _version;
			}
			set
			{
				Set(ref _version, value, "Version");
			}
		}

		public QuickStartViewModel(IRegisterService registerService, ICredentialService credentialService, IAuthService authService, ICommonService commonService)
		{
			_registerService = registerService;
			_credentialService = credentialService;
			_authService = authService;
			_commonService = commonService;
			BackCommand = new Command(OnBackCommand);
			SelectCountryCommand = new AsyncCommand(OnSelectCountryCommand);
			StartCommand = new AsyncCommand(OnStart, IsStartEnabled);
			ShowPrivacyPolicyCommand = new AsyncCommand(URLHelper.ShowPrivacyPolicy);
			IsQuickRegister = true;
			base.ShellViewModel.SetCharacter(ScreenIdentifier.QuickStart, -1, "characters_coach");
		}

		private bool IsStartEnabled()
		{
			if (!string.IsNullOrEmpty(TeamName) && TeamName.Trim().Length > 2)
			{
				return SelectedCountry != null;
			}
			return false;
		}

		private async Task OnStart()
		{
			base.IsBusy = true;
			AuthRequest authRequest = await RegisterUserBySelectedWay();
			if (authRequest == null)
			{
				base.IsBusy = false;
				Log.Info("Register failed");
				return;
			}
			if (!(await _credentialService.SaveCredentials(authRequest)))
			{
				base.IsBusy = false;
				Log.Info("Save credentials failed");
				return;
			}
			AuthResponse authResponse = await _authService.Login();
			if (authResponse == null || authResponse.Status != ResponseStatus.OK)
			{
				base.IsBusy = false;
				Log.Info("Login failed");
				return;
			}
			Log.Info("Registration was OK!");
			base.IsBusy = false;
			base.ShellViewModel.IsLoadingScreenVisisble = true;
			base.NavigationService.NavigateTo(ScreenIdentifier.Club);
		}

		private async Task<AuthRequest> RegisterUserBySelectedWay()
		{
			return (IsQuickRegister && !string.IsNullOrEmpty(FaceboookId)) ? (await RegisterViaFacebook()) : ((!IsQuickRegister) ? (await RegistrerViaLoginAndPassword()) : (await RegisterAsGuest()));
		}

		private async Task<AuthRequest> RegisterViaFacebook()
		{
			RegisterRequest request = new RegisterRequest
			{
				AuthMethod = 1,
				TeamName = TeamName.Trim(),
				CountryId = SelectedCountry.Id,
				AuthId = FaceboookId
			};
			return (await RegisterBy(request) != null) ? new AuthRequest
			{
				AuthMethod = request.AuthMethod,
				AuthId = FaceboookId
			} : null;
		}

		private async Task<AuthRequest> RegistrerViaLoginAndPassword()
		{
			RegisterNewPlayerViewModel registerNewPlayerViewModel = ComponentFactory.Resolve<RegisterNewPlayerViewModel>();
			ICrypterService crypterService = ComponentFactory.Resolve<ICrypterService>();
			RegisterRequest request = new RegisterRequest
			{
				AuthMethod = 0,
				TeamName = TeamName.Trim(),
				CountryId = SelectedCountry.Id,
				Login = registerNewPlayerViewModel.Login,
				Password = crypterService.CreateMD5(registerNewPlayerViewModel.Password)
			};
			RegisterResponse registerResponse = await RegisterBy(request);
			return (registerResponse != null) ? new AuthRequest
			{
				AuthMethod = request.AuthMethod,
				Login = registerResponse.Login,
				Password = registerResponse.Password
			} : null;
		}

		private async Task<AuthRequest> RegisterAsGuest()
		{
			RegisterRequest request = new RegisterRequest
			{
				IsGuest = true,
				TeamName = TeamName.Trim(),
				CountryId = SelectedCountry.Id
			};
			RegisterResponse registerResponse = await RegisterBy(request);
			return (registerResponse != null) ? new AuthRequest
			{
				AuthMethod = request.AuthMethod,
				Login = registerResponse.Login,
				Password = registerResponse.Password
			} : null;
		}

		private async Task<RegisterResponse> RegisterBy(RegisterRequest request)
		{
			RegisterResponse registerResponse = await _registerService.Register(request);
			return (registerResponse.Status != ResponseStatus.OK) ? null : registerResponse;
		}

		private void OnBackCommand()
		{
			base.NavigationService.NavigateTo(IsQuickRegister ? ScreenIdentifier.Login : ScreenIdentifier.RegisterNewPlayer);
		}

		private async Task OnSelectCountryCommand()
		{
			CountrySelectionViewModel popup = new CountrySelectionViewModel(SelectedCountry);
			if (await base.PopupService.ShowPopupAsync(popup) == PopupResult.Done)
			{
				SelectedCountry = popup.SelectedCountry;
			}
		}

		public override async Task Update()
		{
			base.Title = "QuickStartTitle".Translate();
			base.IsBusy = false;
			SelectedCountry = await _commonService.GetDefaultCountry();
			IDeviceService deviceService = ComponentFactory.Resolve<IDeviceService>();
			string arg = await ComponentFactory.Resolve<ICommonService>().GetVersion();
			Version = $"{deviceService.AppVersion} ({deviceService.BuildNumber}) - {arg}";
			base.ShellViewModel.IsLoadingScreenVisisble = false;
			await base.Update();
		}
	}
	public class RegisterNewPlayerViewModel : BaseViewModel
	{
		private const int MinManagerLength = 3;

		private const int MinPasswordLength = 4;

		private string _login;

		private string _email;

		private string _password;

		private string _rePassword;

		private readonly INavigationService _navigationService;

		private readonly IRegisterService _registerService;

		public string Login
		{
			get
			{
				return _login;
			}
			set
			{
				Set(ref _login, value, "Login");
			}
		}

		public string Email
		{
			get
			{
				return _email;
			}
			set
			{
				Set(ref _email, value, "Email");
			}
		}

		public string Password
		{
			get
			{
				return _password;
			}
			set
			{
				Set(ref _password, value, "Password");
			}
		}

		public string RePassword
		{
			get
			{
				return _rePassword;
			}
			set
			{
				Set(ref _rePassword, value, "RePassword");
			}
		}

		public AsyncCommand RegisterCommand { get; }

		public Command RegisterCancelCommand { get; }

		public RegisterNewPlayerViewModel(INavigationService navigationService, IRegisterService registerService)
		{
			_navigationService = navigationService;
			_registerService = registerService;
			RegisterCancelCommand = new Command(OnRegisterCancelCommand);
			RegisterCommand = new AsyncCommand(RegisterTask, IsRegisterEnabled);
			base.ShellViewModel.SetCharacter(ScreenIdentifier.RegisterNewPlayer, -1, "characters_assistant");
		}

		public override Task Update()
		{
			base.Title = "RegisterTitle".Translate();
			return base.Update();
		}

		private bool IsRegisterEnabled()
		{
			if (!string.IsNullOrWhiteSpace(Login) && !string.IsNullOrEmpty(Password) && !string.IsNullOrEmpty(RePassword) && Password.Length >= 4 && RePassword.Length >= 4 && Login.Length >= 3)
			{
				return Password == RePassword;
			}
			return false;
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			switch (propertyName)
			{
			case "Login":
			case "Email":
			case "Password":
			case "RePassword":
				RegisterCommand.RaiseCanExecuteChanged();
				break;
			}
		}

		private async Task RegisterTask()
		{
			base.IsBusy = true;
			ResponseObject obj = await _registerService.VerifyLogin(Login);
			base.IsBusy = false;
			if (obj.Status == ResponseStatus.OK)
			{
				ComponentFactory.Resolve<QuickStartViewModel>().IsQuickRegister = false;
				_navigationService.NavigateTo(ScreenIdentifier.QuickStart);
			}
		}

		private void OnRegisterCancelCommand()
		{
			_navigationService.NavigateTo(ScreenIdentifier.Login);
		}
	}
