		public ComparePopupViewModel(bool showClub = false)
		{
			base.IsLoadingVisible = true;
			base.Title = "Compare".Translate();
			_loadingStatus = new Dictionary<ComparePopupMenuItem, bool>();
			ComparePopupMenuItem[] array = Enum.GetValues(typeof(ComparePopupMenuItem)) as ComparePopupMenuItem[];
			foreach (ComparePopupMenuItem key in array)
			{
				_loadingStatus[key] = false;
			}
			_teamService = ComponentFactory.Resolve<INewTeamService>();
			_squadService = ComponentFactory.Resolve<ISquadService>();
			_leagueService = ComponentFactory.Resolve<ILeagueService>();
			_friendsService = ComponentFactory.Resolve<IFriendsService>();
			_popupService = ComponentFactory.Resolve<IPopupService>();
			_shell = ComponentFactory.Resolve<IShell>();
			base.Size = PopupSize.Large;
			SelectMenuCommand = new AsyncCommand<ComparePopupMenuItem>(SelectMenu);
			LikeUnlikeCommand = new AsyncCommand(LikeUnlike);
			SendChallangeCommand = new AsyncCommand(SendChallange);
			SelectedItem = ((!showClub) ? ComparePopupMenuItem.Compare : ComparePopupMenuItem.Club);
		}

		private void Loading(bool isLoading)
		{
			if (isLoading)
			{
				_shell.StartProgress();
			}
			else
			{
				_shell.StopProgress();
			}
		}

		private async Task SelectMenu(ComparePopupMenuItem selectedItem)
		{
			SelectedItem = selectedItem;
			if (!_loadingStatus[selectedItem])
			{
				IsBusy = true;
				switch (selectedItem)
				{
				case ComparePopupMenuItem.Squad:
					await GetSquad();
					break;
				case ComparePopupMenuItem.League:
					await GetLeague();
					break;
				case ComparePopupMenuItem.Matchday:
					await GetMatches();
					break;
				case ComparePopupMenuItem.Goalscorers:
					await GetGoalgetters();
					break;
				}
				IsBusy = false;
			}
			_loadingStatus[selectedItem] = true;
		}

		public override async Task Update()
		{
			if (!(TeamId == Guid.Empty))
			{
				await GetClub();
				await GetMyClub();
				_loadingStatus[ComparePopupMenuItem.Club] = true;
				_loadingStatus[ComparePopupMenuItem.Compare] = true;
			}
		}

