		private async Task GetSquad()
		{
			TeamPlayersResponse teamPlayersResponse = await _squadService.GetTeamPlayers(TeamId);
			if (teamPlayersResponse == null || teamPlayersResponse.Players == null || teamPlayersResponse.Players.Count == 0)
			{
				PlayerTableRows = null;
			}
			else
			{
				_players = (from x in teamPlayersResponse.Players
					orderby x.GetPositionOrder(), x.Strength descending
					select x).ToList();
				string text = string.Empty;
				List<ITableRow> list = new List<ITableRow>();
				foreach (PlayerData player in _players)
				{
					string shortPositionName = player.GetShortPositionName();
					if (text != shortPositionName)
					{
						text = shortPositionName;
						list.Add(new SectionRow
						{
							Name = shortPositionName
						});
					}
					TableRow item = new TableRow(new AvatarCell(player.Country, player.Head), new PlayerInfoCell(player.Name, player.Strength, 0, hasRedCard: false, 0, isForSale: false, null, -1, showShirt: true, showStrengthNumber: false), new TextCell(player.Age.ToString(), TableCellAlignment.Center), new TextCell(player.Talent.ToString(), TableCellAlignment.Center, (player.Talent > 8) ? TableCellColor.Highlight : TableCellColor.Default));
					list.Add(item);
				}
				PlayerTableRows = list;
			}
			NoPlayersMessage = (_isBotTeam ? "NoPlayersBot" : "NoPlayersTeam").Translate();
		}

		private async Task GetLeague()
		{
			LeagueTableResponse leagueTableResponse = await _leagueService.GetLeagueTable(TeamData?.LeagueId ?? Guid.Empty);
			if (leagueTableResponse == null)
			{
				LeagueTableRows = null;
				return;
			}
			List<ITableRow> list = new List<ITableRow>();
			LeagueTableData[] array = (from x in leagueTableResponse.Teams
				orderby x.TotalPoints descending, x.GoalDifference descending, x.Strength descending
				select x).ToArray();
			list.Add(new SectionRow
			{
				Name = string.Format("{0} {1} - {2}", "Matchday".Translate(), Math.Max(leagueTableResponse.Teams[0].TotalMatches, 1), DateTime.Now.ToGTShortDateString()),
				Alignment = TableCellAlignment.Center,
				Background = TableRowBackground.New
			});
			for (int num = 0; num < array.Length; num++)
			{
				LeagueTableData leagueTableData = array[num];
				TableCellColor teamColor = leagueTableData.GetTeamColor();
				TableRowBackground background = TableRowBackground.New;
				if (num >= array.Length - leagueTableResponse.Dismount)
				{
					background = TableRowBackground.Inactive;
				}
				else if (num >= leagueTableResponse.Mount)
				{
					background = TableRowBackground.Default;
				}
				list.Add(new TableRow(new TextCell($"{num + 1}", TableCellAlignment.Center, teamColor), new ImageCell("flag_" + leagueTableData.Country), new ImageCell(leagueTableData.Logo + "_normal"), new TeamInfoCell(leagueTableData.Name, leagueTableData.Strength), new TextCell($"{leagueTableData.Wins.Home + leagueTableData.Wins.Away}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.Draws.Home + leagueTableData.Draws.Away}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.Losses.Home + leagueTableData.Losses.Away}", TableCellAlignment.Center, teamColor), new TextCell($"{leagueTableData.TotalPoints}", TableCellAlignment.Center, teamColor))
				{
					Background = background
				});
			}
			LeagueTableRows = list;
		}

		private async Task GetMatches()
		{
			MatchesResponse matchesResponse = await _leagueService.GetMatches(TeamData?.LeagueId ?? Guid.Empty);
			if (matchesResponse == null || matchesResponse.Matches == null || matchesResponse.Matches.Count <= 0)
			{
				return;
			}
			List<ITableRow> list = new List<ITableRow>();
			IEnumerable<IGrouping<string, MatchData>> enumerable = from x in matchesResponse.Matches
				group x by x.Date;
			int num = 1;
			foreach (IGrouping<string, MatchData> item in enumerable)
			{
				list.Add(new SectionRow
				{
					Name = "Matchday".Translate() + $" {num} - {item.Key.ParseToDate().ToGTDateTimeString()}",
					Alignment = TableCellAlignment.Center
				});
				foreach (MatchData item2 in item)
				{
					TableCellColor teamColor = item2.GetTeamColor();
					list.Add(new TableRow(new ImageCell(item2.HomeLogo + "_normal"), new TextCell(item2.HomeName, TableCellAlignment.Left, teamColor), new TextCell(item2.GetMatchScore(), TableCellAlignment.Center, teamColor, TableCellFontSize.Large), new TextCell(item2.AwayName, TableCellAlignment.Right, teamColor), new ImageCell(item2.AwayLogo + "_normal")));
				}
				num++;
			}
			MatchesTableRows = list;
		}

		private async Task GetGoalgetters()
		{
			GoalGettersResponse goalGettersResponse = await _leagueService.GetGoalGetters(TeamData?.LeagueId ?? Guid.Empty);
			if (goalGettersResponse == null || goalGettersResponse.Players == null || goalGettersResponse.Players.Count == 0)
			{
				GoalGettersTableRows = null;
			}
			else
			{
				List<ITableRow> list = new List<ITableRow>();
				GoalGetterPlayerData[] array = goalGettersResponse.Players.OrderByDescending((GoalGetterPlayerData x) => x.Goals).ToArray();
				for (int num = 0; num < array.Length; num++)
				{
					GoalGetterPlayerData goalGetterPlayerData = array[num];
					TableCellColor playerColor = goalGetterPlayerData.GetPlayerColor();
					list.Add(TableRow.Create(new TextCell($"{num + 1}", TableCellAlignment.Center, playerColor), new AvatarCell(goalGetterPlayerData.Country, goalGetterPlayerData.Head), new TextCell(goalGetterPlayerData.Name, TableCellAlignment.Left, playerColor), new TextCell(goalGetterPlayerData.TeamName, TableCellAlignment.Center, playerColor), new TextCell($"{goalGetterPlayerData.Goals}", TableCellAlignment.Center, playerColor)));
				}
				GoalGettersTableRows = list;
			}
			NoGoalgettersMessage = "NoGoalscorers".Translate();
		}

		private async Task GetMyClub()
		{
			MyTeamData = (await _teamService.GetMyTeamInfo()).TeamData;
			ForeignInfo = new List<TextTwoValuesItem>
			{
				new TextTwoValuesItem("Strength".Translate(), TeamData.Strength, MyTeamData.Strength),
				new TextTwoValuesItem("Points".Translate(), TeamData.UserData.Score, MyTeamData.UserData.Score),
				new TextTwoValuesItem("MarketValue".Translate(), TeamData.MarketValue, MyTeamData.MarketValue, " €"),
				new TextTwoValuesItem("Fans".Translate(), TeamData.Fans, MyTeamData.Fans),
				new TextTwoValuesItem("Members".Translate(), TeamData.Members, MyTeamData.Members),
				new TextTwoValuesItem("TeamMood".Translate(), TeamData.TeamMood, MyTeamData.TeamMood, TeamData.Mood > MyTeamData.Mood, MyTeamData.Mood > TeamData.Mood),
				new TextTwoValuesItem("Rank".Translate(), TeamData.UserData.Rank, MyTeamData.UserData.Rank, TeamData.UserData.Score > MyTeamData.UserData.Score, MyTeamData.UserData.Score > TeamData.UserData.Score),
				new TextTwoValuesItem("Foundation".Translate(), TeamData.UserData.Created.ParseToDate(), MyTeamData.UserData.Created.ParseToDate()),
				new TextTwoValuesItem("Matches".Translate(), TeamData.Matches, MyTeamData.Matches),
				new TextTwoValuesItem("WinRate".Translate(), TeamData.WinRate, MyTeamData.WinRate, "%")
			};
			MyClubName = MyTeamData.Name;
			MyLogo = MyTeamData.Logo;
		}

		private async Task LikeUnlike()
		{
			if (!(TeamId == Guid.Empty))
			{
				Loading(isLoading: true);
				ResponseObject responseObject = (IsFriends ? (await _friendsService.Unlike(TeamId)) : (await _friendsService.Like(TeamId)));
				if (responseObject.Status == ResponseStatus.OK)
				{
					IsFriends = !IsFriends;
				}
				Loading(isLoading: false);
			}
		}

		private async Task SendChallange()
		{
			if (!(TeamId == Guid.Empty) && await _popupService.ShowYesNoMessageAsync("FriendlyMatch".Translate(), string.Format("CompareChallengeClub".Translate(), ClubName)))
			{
				Loading(isLoading: true);
				if ((await _friendsService.SendChallenge(TeamId)).Status == ResponseStatus.OK)
				{
					IsChallangeSended = true;
				}
				Loading(isLoading: false);
			}
		}
	}
