		public decimal LadderStarsAway { get; set; }

		public string LadderTacticHome { get; set; }

		public string LadderTacticAway { get; set; }

		public string LadderWinPts { get; set; }

		public string LadderLosePts { get; set; }

		public int MatchCost { get; set; }

		public ICommand RestoreStaminaCommand { get; }

		public ICommand RunMatchCommand { get; }

		public ICommand UpMatchSpeedCommand { get; }

		public decimal ResultHomeStrength { get; private set; }

		public decimal ResultAwayStrength { get; private set; }

		public LadderPopupViewModel(Guid ladderId, Guid teamId)
		{
			base.IsTutorialControlContainer = true;
			base.IsCloseButtonHidden = TutorialManager.Instance.InProgress;
			_ladderService = ComponentFactory.Resolve<ILadderService>();
			RestoreStaminaCommand = new AsyncCommand(RestoreStamina);
			RunMatchCommand = new AsyncCommand(RunMatch);
			UpMatchSpeedCommand = new Command(UpMatchSpeed);
			_ladderId = ladderId;
			_teamId = teamId;
			base.Size = PopupSize.Medium;
			base.Background = PopupBackground.Spotlights;
			_timer = new System.Timers.Timer(3000.0);
			_timer.Elapsed += OnTimerTick;
			_matchTimer = new System.Timers.Timer(_matchSpeed);
			_matchTimer.Elapsed += OnMatchTimerTick;
			base.CloseMessage = "DissmissLadderMatchRunning".Translate();
		}

		public override async Task Update()
		{
			LadderChallengeResponse ladderChallengeResponse = await _ladderService.GetLadderChallenge(_ladderId, _teamId);
			LadderNameHome = ladderChallengeResponse.HomeTeam.Name ?? "";
			LadderWappenHome = ladderChallengeResponse.HomeTeam.Logo + "_normal";
			LadderShirtHome = ladderChallengeResponse.HomeTeam.Trikot ?? "";
			LadderStarsHome = ladderChallengeResponse.HomeTeam.Strength;
			LadderTacticHome = ladderChallengeResponse.HomeTeam.Scheme + " " + ladderChallengeResponse.HomeTeam.Tactics;
			LadderNameAway = ladderChallengeResponse.AwayTeam.Name ?? "";
			LadderWappenAway = ladderChallengeResponse.AwayTeam.Logo + "_normal";
			LadderShirtAway = ladderChallengeResponse.AwayTeam.Trikot ?? "";
			LadderStarsAway = ladderChallengeResponse.AwayTeam.Strength;
			LadderTacticAway = ladderChallengeResponse.AwayTeam.Scheme + " " + ladderChallengeResponse.AwayTeam.Tactics;
			Price = ladderChallengeResponse.StaminaCost;
			MatchCost = ladderChallengeResponse.MatchCost;
			LadderWinPts = $"+{ladderChallengeResponse.WinPoints}";
			LadderLosePts = $"{ladderChallengeResponse.LosePoints}";
			base.Title = (LadderNameHome + " - " + LadderNameAway).Translate();
			MatchSpeedMode = (LadderMatchSpeed)Preferences.Get("LadderSpeed", 1);
			SetLadderDate(ladderChallengeResponse.LadderDate);
			ApplyBinding();
			ComponentFactory.Resolve<IShell>().StopProgress();
		}

		private async Task RestoreStamina()
		{
			if (!(LadderStamina >= 100m) && await ResourceService.Current.SpentGTStars(Price))
			{
				_timer.Stop();
				LadderStamina = 100m;
				TextResponse textResponse = await _ladderService.RestoreStamina();
				if (textResponse.Status == ResponseStatus.OK)
				{
					SetLadderDate(textResponse.Text, needRefreshStamina: false);
					return;
				}
				await ResourceService.Current.UpdateAsync();
				Refresh();
			}
		}

		private async Task RunMatch()
		{
			if (!(LadderStamina < (decimal)MatchCost))
			{
				IsGameStarted = true;
				base.IsPossibleToClose = false;
				_timer.Stop();
				IsRunButtonEnabled = false;
				IsRestoreButtonEnabled = false;
				LadderStamina -= (decimal)MatchCost;
				LadderMatchResponse ladderMatchResponse = await _ladderService.RunMatch(_ladderId, _teamId);
				if (ladderMatchResponse == null || ladderMatchResponse.Status != ResponseStatus.OK || ladderMatchResponse.MatchReport == null || ladderMatchResponse.MatchReport.Events == null)
				{
					Refresh();
					base.IsPossibleToClose = true;
					return;
				}
				SetLadderDate(ladderMatchResponse.Stamina, needRefreshStamina: false);
				ResultHomeStrength = ladderMatchResponse.MatchReport.Home.Strength;
				ResultAwayStrength = ladderMatchResponse.MatchReport.Away.Strength;
				_matchDuration = ladderMatchResponse.MatchReport.Events.LastOrDefault()?.Minute ?? 0;
				LadderEvents = ladderMatchResponse.MatchReport.Events;
				_matchTimer.Start();
			}
		}

		private void OnTimerTick(object sender, ElapsedEventArgs e)
		{
			Refresh();
		}

		private void OnMatchTimerTick(object sender, ElapsedEventArgs e)
		{
			UpdateMatch();
		}

		private void Refresh(bool refreshStamina = true)
		{
			if (refreshStamina)
			{
				LadderStamina = GetStamina();
			}
			IsRunButtonEnabled = !IsGameStarted && LadderStamina >= (decimal)MatchCost;
			IsRestoreButtonEnabled = !IsGameStarted && LadderStamina < 100m;
			Log.Info($"ladder stamina: {LadderStamina:N2}");
			if (LadderStamina >= 100m)
			{
				_timer.Stop();
			}
		}

		private void SetLadderDate(string dateText, bool needRefreshStamina = true)
		{
			_ladderDate = dateText.ParseToDate();
			Refresh(needRefreshStamina);
			if (LadderStamina < 100m)
			{
				_timer.Start();
			}
		}

		private decimal GetStamina()
		{
			return (decimal)(DateTime.UtcNow - _ladderDate).TotalMinutes.Clamp(0.0, 100.0);
		}

		private void UpdateMatch()
		{
			if (LadderEvents == null || LadderEvents.Count <= 0)
			{
				MatchEnd();
				return;
			}
			foreach (LadderEvent item in LadderEvents.Where((LadderEvent x) => x.Minute == MatchTime))
			{
				HomeScore = item.HomeScore;
				AwayScore = item.AwayScore;
				CurrentEvent = item;
			}
			if (MatchTime == _matchDuration)
			{
				MatchEnd();
			}
			else
			{
				MatchTime++;
			}
		}

		private void MatchEnd()
		{
			IsGameEnded = true;
			_matchTimer.Stop();
			base.IsPossibleToClose = true;
		}

		public override void OnClose(PopupResult popupResult)
		{
			if (base.IsPossibleToClose)
			{
				_timer.Elapsed -= OnTimerTick;
				_timer.Stop();
				_timer.Dispose();
				_matchTimer.Elapsed -= OnMatchTimerTick;
				_matchTimer.Stop();
				_matchTimer.Dispose();
			}
			else
			{
				ComponentFactory.Resolve<IPopupService>().ShowOkMessage(base.CloseMessage);
			}
		}

		private void UpMatchSpeed()
		{
			MatchSpeedMode = NextMatchSpeed(MatchSpeedMode);
			Preferences.Set("LadderSpeed", (int)MatchSpeedMode);
		}

		private LadderMatchSpeed NextMatchSpeed(LadderMatchSpeed speed)
		{
			return speed switch
			{
				LadderMatchSpeed.x1 => LadderMatchSpeed.x2, 
				LadderMatchSpeed.x2 => LadderMatchSpeed.x3, 
				LadderMatchSpeed.x3 => LadderMatchSpeed.x1, 
				_ => throw new NotImplementedException(), 
			};
		}
	}
