	{
		private int _bonusMoney;

		private int _bonusStars;

		private int _bonusMedipacks;

		private readonly bool _isForTutorial = true;

		private readonly bool _isLastPopup;

		public int BonusMoney
		{
			get
			{
				return _bonusMoney;
			}
			set
			{
				Set(ref _bonusMoney, value, "BonusMoney");
			}
		}

		public int BonusStars
		{
			get
			{
				return _bonusStars;
			}
			set
			{
				Set(ref _bonusStars, value, "BonusStars");
			}
		}

		public int BonusMedipacks
		{
			get
			{
				return _bonusMedipacks;
			}
			set
			{
				Set(ref _bonusMedipacks, value, "BonusMedipacks");
			}
		}

		public TutorialPopupViewModel(string title, string message, ProductData product)
		{
			_isForTutorial = false;
			base.Background = PopupBackground.Green;
			base.Title = title;
			base.Message = message;
			base.Character = Character.AnnaCheer;
			BonusMoney = product.Money;
			BonusStars = product.GTStars;
			BonusMedipacks = product.Medipacks;
			base.ConfirmButtonTitle = "Ok".Translate();
		}

		public TutorialPopupViewModel(TutorialStep tutorialStep)
		{
			base.IsCloseOnShadowEnabled = false;
			base.Background = PopupBackground.Blue;
			base.Title = tutorialStep.Title;
			base.Message = tutorialStep.Message;
			base.Character = GetCharacter(tutorialStep.CharacterID);
			BonusMoney = tutorialStep.RewardMoney;
			BonusStars = tutorialStep.RewardStars;
			_isLastPopup = string.IsNullOrEmpty(tutorialStep.NextTopicID);
			base.ConfirmButtonTitle = (_isLastPopup ? "Finish".Translate() : "Next".Translate());
			if (!tutorialStep.CanSkip)
			{
				base.IsCloseButtonHidden = true;
			}
			TutorialManager.Instance.RegisterTutorialPopup(this);
		}

		public override void OnClose(PopupResult popupResult)
		{
			if (!_isForTutorial)
			{
				return;
			}
			if (popupResult == PopupResult.Done || popupResult == PopupResult.Canceled)
			{
				if (popupResult == PopupResult.Done)
				{
					IAsyncCommand finishTutorialStepCommand = TutorialManager.Instance.FinishTutorialStepCommand;
					if (finishTutorialStepCommand != null && finishTutorialStepCommand.CanExecute(null))
					{
						finishTutorialStepCommand.Execute(null);
					}
				}
				base.IsPossibleToClose = true;
				TutorialManager.Instance.RemoveTutorialPopup(this);
				if (_isLastPopup)
				{
					TutorialManager.Instance.CloseAllTutorialPopups();
				}
			}
			else
			{
				base.IsPossibleToClose = false;
				ClosePopupTask().FireAndForgetSafeAsync();
			}
		}

		private async Task ClosePopupTask()
		{
			if (await TutorialManager.Instance.TrySkipTutorial())
			{
				Close(PopupResult.Canceled);
			}
		}

		private Character GetCharacter(string characterId)
		{
			return characterId switch
			{
				"anna_neutral" => Character.Anna, 
				"anna_cheer" => Character.AnnaCheer, 
				"anna_point" => Character.AnnaPoint, 
				"scout_neutral" => Character.Scout, 
				"scout_cheer" => Character.ScoutCheer, 
				"scout_point" => Character.ScoutPoint, 
				"coach_cheer" => Character.CoachCheer, 
				"coach_point" => Character.CoachPoint, 
				_ => Character.Coach, 
			};
		}
	}
