			RecruitCommand = new AsyncCommand<Guid>(Recruit);
			SelectCommand = new Command<SquadPlayerData>(Select);
			PositionsList = new List<ComboBoxItem>
			{
				new ComboBoxItem
				{
					Text = "Keeper".Translate()
				},
				new ComboBoxItem
				{
