		private void Select(SquadPlayerData player)
		{
			ComponentFactory.Resolve<ScoutingDetailsViewModel>().Player = player;
			_navigationService.NavigateTo(ScreenIdentifier.Scouting_Details);
		}

		private async Task Recruit(Guid playerId)
		{
			Log.Info($"recruit player id = {playerId}");
			base.IsBusy = true;
			try
			{
				ScoutingResponse scoutingResponse = await _scoutingService.Recruit(playerId);
				if (scoutingResponse.Status == ResponseStatus.OK)
				{
					UpdateData(scoutingResponse);
				}
			}
			catch (Exception ex)
			{
				AppAnalytics.Instance.TrackError(ex);
			}
			finally
			{
				base.IsBusy = false;
			}
		}

		public override async Task Update()
		{
			base.Title = "Scouting".Translate();
			UpdateData(await _scoutingService.GetPlayers());
		}

		private void UpdateData(ScoutingResponse result)
		{
			_playersData = result.Players ?? new List<SquadPlayerData>();
			UpdateScoutedPlayers();
			InstructCost = result.ScoutingCost;
			PremiumInstructCost = result.PremiumScoutingCost;
			SpeedupCost = result.SpeedupCost;
			_nextScoutDate = result.NextScoutingDate.ParseToDate();
			_nextPremiumScoutDate = result.NextPremiumScoutingDate.ParseToDate();
			SetupTimer();
		}

		private void UpdateScoutedPlayers()
		{
			ScoutedPlayers = ((IEnumerable<SquadPlayerData>)_playersData).Select((Func<SquadPlayerData, ITableRow>)((SquadPlayerData p) => new TableRow(new AvatarCell(p.Country, p.Head), new TextTimerCell(p.Name, p.EndDateValue), new TextCell(p.Age.ToString(), TableCellAlignment.Center), new TextCell(p.Talent.ToString(), TableCellAlignment.Center, (p.Talent > 8) ? TableCellColor.Highlight : TableCellColor.Default), new TextCell(p.GetShortPositionName(), TableCellAlignment.Center, TableCellColor.Accent), new StrengthCell(p.Strength), new ButtonCell("Recruit".Translate(), ButtonType.Standart, 0, RecruitCommand, p.ID))
			{
				Command = SelectCommand,
				CommandParameter = p
			})).ToList();
		}

		private void SetupTimer()
		{
			List<DateTime> list = (from x in _playersData
				where x.EndDateValue > DateTime.UtcNow
				select x.EndDateValue).ToList();
			if (_nextScoutDate > DateTime.UtcNow)
			{
				list.Add(_nextScoutDate);
			}
			if (_nextPremiumScoutDate > DateTime.UtcNow)
			{
				list.Add(_nextPremiumScoutDate);
			}
			if (list.Any())
			{
				SetEndDate(list.Min());
			}
			else
			{
				SetEndDate(DateTime.MinValue);
			}
		}

		protected override void OnTimerRefresh(TimeSpan timeLeft, bool isFininshed)
		{
			base.OnTimerRefresh(timeLeft, isFininshed);
			DateTime utcNow = DateTime.UtcNow;
			if (_nextScoutDate > utcNow)
			{
				TimeToInstruct = (_nextScoutDate - utcNow).ToLocalizedString();
			}
			if (_nextPremiumScoutDate > utcNow)
			{
				TimeToPremiumInstruct = (_nextPremiumScoutDate - utcNow).ToLocalizedString();
			}
			InstructCommand.RaiseCanExecuteChanged();
			OnPropertyChanged("IsInstructEnabled");
			OnPropertyChanged("IsPremiumInstructEnabled");
			if (isFininshed)
			{
				Update().FireAndForgetSafeAsync();
			}
		}

		private bool InstructEnabled()
		{
			return _nextScoutDate < DateTime.UtcNow;
		}

		private async Task Instruct()
		{
			await InstructInternal(isPremium: false);
		}

		private async Task InstructPremium()
		{
			await InstructInternal(isPremium: true);
		}

		private async Task InstructInternal(bool isPremium)
		{
			int position = (isPremium ? SelectedPositionIndex : (-1));
			int cost = (isPremium ? PremiumInstructCost : InstructCost);
			string question = (isPremium ? string.Format("InstructSpecialScoutQuestion".Translate(), PositionsList[SelectedPositionIndex].Text, PremiumInstructCost) : string.Empty);
			if (!(await base.ResourceService.Spent(cost, isPremium, isPremium ? "InstructSpecialScout".Translate() : string.Empty, question, Character.Scout)))
			{
				return;
			}
			base.IsBusy = true;
			List<Guid> ids = _playersData.Select((SquadPlayerData x) => x.ID).ToList();
			ScoutingResponse scoutingResponse = await _scoutingService.Instruct(position, cost);
			if (scoutingResponse.Status == ResponseStatus.NeedToRefresh)
			{
				base.ResourceService.Update();
				await Update();
				base.IsBusy = false;
				return;
			}
			if (scoutingResponse.Status == ResponseStatus.OK)
			{
				UpdateData(scoutingResponse);
				_navigationService.NavigateTo(ScreenIdentifier.Scouting, 1);
				SquadPlayerData squadPlayerData = _playersData.FirstOrDefault((SquadPlayerData x) => !ids.Contains(x.ID));
				if (squadPlayerData != null)
				{
					base.IsBusy = false;
					ComponentFactory.Resolve<ScoutingDetailsViewModel>().Player = squadPlayerData;
					base.NavigationService.NavigateTo(ScreenIdentifier.Scouting_Details);
				}
			}
			else
			{
				base.ResourceService.Update();
			}
			base.IsBusy = false;
		}

		private async Task Speedup()
		{
			if (!(await base.ResourceService.SpentGTStars(SpeedupCost, "SpeedupSpecialScout".Translate(), string.Format("SpeedupSpecialScoutQuestion".Translate(), SpeedupCost), Character.Scout)))
			{
				return;
			}
			base.IsBusy = true;
			ResponseObject responseObject = await _scoutingService.Speedup(SpeedupCost);
			if (responseObject.Status == ResponseStatus.NeedToRefresh)
			{
				await Update();
				base.IsBusy = false;
				return;
			}
			if (responseObject.Status == ResponseStatus.OK)
			{
				_nextPremiumScoutDate = DateTime.MinValue;
				SetupTimer();
				OnTimerRefresh(TimeSpan.Zero, isFininshed: true);
			}
			base.IsBusy = false;
		}
	}
