		public SettingsViewModel(ICredentialService credentialService, IUserService userService, IPreferencesService preferencesService, IDeviceService deviceService, IFacebookService facebookService)
		{
			_credentialService = credentialService;
			_userService = userService;
			_preferencesService = preferencesService;
			_deviceService = deviceService;
			_facebookService = facebookService;
		}

		public override Task Init()
		{
			if (ComponentFactory.Resolve<IAuthService>().IsAdmin)
			{
				Log.Info("Adding admin controls");
				base.ShellViewModel.SetContextMenuImage(ScreenIdentifier.Settings, -1, "menu_settings");
				base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Settings, -1, "Send Notification", SendNotificationCommand);
				base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Settings, -1, "Switch Server", SwitchServerCommand);
				base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Settings, -1, "ResetTutorial".Translate(), ResetCommand);
				base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Settings, -1, "Logout".Translate(), LogoutCommand);
			}
			return base.Init();
		}

		public override async Task Update()
		{
			base.Title = "Settings".Translate();
			_facebookService.SetCallback(FacebookTokenChanged);
			_isUpdating = true;
			IsMusicEnabled = _preferencesService.IsMusicEnabled;
			IsSoundEnabled = _preferencesService.IsSoundEnabled;
			IsSeasonInformationEnabled = _preferencesService.IsSeasonInformationEnabled;
			IsSponsorExpiredEnabled = _preferencesService.IsSponsorExpiredEnabled;
			IsPlayerContractEndEnabled = _preferencesService.IsPlayerContractEndEnabled;
			IsSingleTrainingExpiredEnabled = _preferencesService.IsSingleTrainingExpiredEnabled;
			IsBuildingCompleteEnabled = _preferencesService.IsBuildingCompleteEnabled;
			IsReturnInviteEnabled = _preferencesService.IsReturnInviteEnabled;
			PreferencesResponse preferencesResponse = await _userService.GetPreferences();
			if (preferencesResponse.Status == ResponseStatus.OK && preferencesResponse?.NotificationSettings != null)
			{
				IsAuctionOverbidEnabled = preferencesResponse.NotificationSettings.AuctionOverbid;
				IsMatchResultsEnabled = preferencesResponse.NotificationSettings.MatchResults;
				IsLineupIncompleteEnabled = preferencesResponse.NotificationSettings.LineupIncomplete;
				IsFriendInviteEnabled = preferencesResponse.NotificationSettings.FriendInvite;
				IsIneffectiveTrainingEnabled = preferencesResponse.NotificationSettings.IneffectiveTraining;
				IsFriendMatchEnabled = preferencesResponse.NotificationSettings.FriendlyMatch;
				IsSystemMessagesEnabled = preferencesResponse.NotificationSettings.System;
			}
			_userData = preferencesResponse.UserData;
			ManagerName = preferencesResponse.UserData.Name;
			FacebookUserId = _facebookService.UserId;
			IDeviceService deviceService = ComponentFactory.Resolve<IDeviceService>();
			string arg = await ComponentFactory.Resolve<ICommonService>().GetVersion();
			Version = $"{deviceService.AppVersion} ({deviceService.BuildNumber}) - {arg}";
			_isUpdating = false;
		}

		private void FacebookTokenChanged(FacebookAuthResult result)
		{
			if (result.CallBack == CallbackType.Success)
			{
				ConnectFacebook(result).FireAndForgetSafeAsync();
			}
			else if (result.CallBack == CallbackType.LoggedOut && FacebookUserId != null)
			{
				FacebookUserId = null;
				SecureStorage.RemoveAll();
				ComponentFactory.Resolve<INotificationManager>().CancelNotification();
				base.NavigationService.NavigateTo(ScreenIdentifier.Login);
			}
		}

		private void Logout()
		{
			base.IsBusy = true;
			_credentialService.Logout();
		}

		private async Task ConnectFacebook(FacebookAuthResult facebookAuthResult)
		{
			if (!(await _userService.UpdateUser(new UserData
			{
				FacebookId = facebookAuthResult.UserId
			})))
			{
				_facebookService?.Logout();
				return;
			}
			FacebookUserId = facebookAuthResult.UserId;
			await base.ResourceService.UpdateAsync();
		}

		private void CallSettingsUpdate()
		{
			if (!_isUpdating)
			{
				_saveTriggerTimer?.Dispose();
				_saveTriggerTimer = new System.Threading.Timer(async delegate
				{
					await UpdateSettingsAsync();
				}, null, 1000, 0);
			}
		}

		private async Task<bool> UpdateSettingsAsync()
		{
			_saveTriggerCancellationTokenSource?.Cancel();
			_saveTriggerCancellationTokenSource = new CancellationTokenSource();
			CancellationToken token = _saveTriggerCancellationTokenSource.Token;
			TaskCompletionSource<bool> taskCompletionSource = new TaskCompletionSource<bool>();
			await Task.Run(async delegate
			{
				try
				{
					token.ThrowIfCancellationRequested();
					bool num = await _userService.SavePreferences(new NotificationSettings
					{
						AuctionOverbid = IsAuctionOverbidEnabled,
						MatchResults = IsMatchResultsEnabled,
						LineupIncomplete = IsLineupIncompleteEnabled,
						FriendInvite = IsFriendInviteEnabled,
						IneffectiveTraining = IsIneffectiveTrainingEnabled,
						FriendlyMatch = IsFriendMatchEnabled,
						System = IsSystemMessagesEnabled,
						AuctionEnd = IsAuctionEndSoonEnabled
					});
					token.ThrowIfCancellationRequested();
					if (num)
					{
						_deviceService.InvokeOnMainThread(delegate
						{
							base.PopupService.ShowToast("ChangesSaved".Translate());
						});
					}
					taskCompletionSource.TrySetResult(result: true);
				}
				catch (OperationCanceledException)
				{
					taskCompletionSource.TrySetResult(result: false);
				}
			});
			return await taskCompletionSource.Task;
		}

		private async Task ShowUpdateUserPopup()
		{
			if (await _userService.ShowUpdateUserPopup(_userData))
			{
				await base.ResourceService.UpdateAsync();
			}
			ManagerName = _userData.Name;
		}
	}
