	{
		private List<ContextMenuItem> _contextMenuItems;

		private string _contextMenuImage;

		private string _title;

		private bool _isLoadingScreenVisisble = true;

		private string _characterImageName;

		private readonly Dictionary<string, List<ContextMenuItem>> _contextMenu;

		private readonly Dictionary<string, string> _contextImages;

		private readonly Dictionary<string, string> _characterImages;

		private readonly INavigationService _navigationService;

		public List<ContextMenuItem> ContextMenuItems
		{
			get
