				return _characterImageName;
			}
			set
			{
				Set(ref _characterImageName, value, "CharacterImageName");
			}
		}

		public HelpSection HelpSection { get; set; }

		public ShellViewModel(INavigationService navigationService)
		{
			_contextMenu = new Dictionary<string, List<ContextMenuItem>>();
			_contextImages = new Dictionary<string, string>();
			_characterImages = new Dictionary<string, string>();
			_navigationService = navigationService;
			_navigationService.Navigated += OnNavigated;
		}

		private void OnNavigated(object sender, NavigationEventArgs e)
		{
			string key = GetKey(e.Screen, e.TabIndex);
			string key2 = GetKey(e.Screen, -1);
			if (!_contextImages.TryGetValue(key, out var value) && !_contextImages.TryGetValue(key2, out value))
			{
				value = string.Empty;
			}
			ContextMenuImage = value;
			if (!_contextMenu.TryGetValue(key, out var value2) && !_contextMenu.TryGetValue(key2, out value2))
			{
				value2 = null;
			}
			ContextMenuItems = value2;
			if (!_characterImages.TryGetValue(key, out var value3) && !_characterImages.TryGetValue(key2, out value3))
			{
				value3 = string.Empty;
			}
			CharacterImageName = value3;
			HelpSection = GetHelpSectionByScreen(e.Screen, e.TabIndex);
		}

		private string GetKey(ScreenIdentifier screen, int tabIndex)
		{
			if (tabIndex < 0)
			{
				return screen.ToString();
			}
			return $"{screen}.{tabIndex}";
		}

		public void AddContextMenuItem(ScreenIdentifier screen, int tabIndex, string title, ICommand command, object commandParameter = null, string tutorialControlId = null)
		{
			string key = GetKey(screen, tabIndex);
			if (!_contextMenu.ContainsKey(key))
			{
				_contextMenu.Add(key, new List<ContextMenuItem>());
			}
			_contextMenu[key].Add(new ContextMenuItem
			{
				Title = title,
				Command = command,
				CommandParameter = commandParameter,
				TutorialControlId = tutorialControlId
			});
		}

		public void SetContextMenuImage(ScreenIdentifier screen, int tabIndex, string image)
		{
			string key = GetKey(screen, tabIndex);
			_contextImages[key] = image;
		}

		public void SetCharacter(ScreenIdentifier screen, int tabIndex, string characterImageName)
		{
			string key = GetKey(screen, tabIndex);
			_characterImages[key] = characterImageName;
		}

		private HelpSection GetHelpSectionByScreen(ScreenIdentifier identifier, int index)
		{
			return identifier switch
			{
				ScreenIdentifier.Shop => HelpSection.Shop_Overview, 
				ScreenIdentifier.Club => index switch
				{
					1 => HelpSection.Club_Sponsors, 
					2 => HelpSection.Club_Inbox, 
					3 => HelpSection.Club_Accomplishments, 
					_ => HelpSection.Club_Overview, 
				}, 
				ScreenIdentifier.Finances => (index != 0) ? HelpSection.Finances_Matchday : HelpSection.Finances_History, 
				ScreenIdentifier.Stadium => HelpSection.Stadium_Overview, 
				ScreenIdentifier.Equipment => HelpSection.Equipment_ShirtsEmblems, 
				ScreenIdentifier.Squad => index switch
				{
					1 => HelpSection.Squad_Details, 
					2 => HelpSection.Squad_SkillCards, 
					3 => HelpSection.Squad_Upgrade, 
					4 => HelpSection.Squad_SellPlayers, 
					_ => HelpSection.Squad_Overview, 
				}, 
				ScreenIdentifier.Lineup => HelpSection.Lineup_Overview, 
				ScreenIdentifier.Lineup_Formation => HelpSection.Lineup_Lineup, 
				ScreenIdentifier.Training => index switch
				{
					1 => HelpSection.Training_Tactics, 
					2 => HelpSection.Training_TrainingCamp, 
					3 => HelpSection.Training_IndividualTraining, 
					_ => HelpSection.Training_TeamTraining, 
				}, 
				ScreenIdentifier.Scouting => (index != 1) ? HelpSection.Scouting_Overview : HelpSection.Scouting_YouthPlayer, 
				ScreenIdentifier.Transfermarket => index switch
				{
					1 => HelpSection.TransferMarket_QuickSearch, 
					2 => HelpSection.TransferMarket_BidForPlayers, 
					3 => HelpSection.TransferMarket_MyAuctions, 
					_ => HelpSection.TransferMarket_SearchResult, 
				}, 
				ScreenIdentifier.League => index switch
				{
					1 => HelpSection.League_Matchday, 
					2 => HelpSection.League_FixtureList, 
					3 => HelpSection.League_GoalscorersList, 
					_ => HelpSection.League_Overview, 
				}, 
				ScreenIdentifier.GTLadder => HelpSection.GTLadder_Table, 
				ScreenIdentifier.Friends => index switch
				{
					1 => HelpSection.Friends_Challenges, 
					2 => HelpSection.Friends_QuickSearch, 
					_ => HelpSection.Friends_Friends, 
				}, 
				ScreenIdentifier.Live => HelpSection.Live_Live, 
				ScreenIdentifier.Settings => HelpSection.Settings_Settings, 
				_ => HelpSection.Contents, 
			};
		}
	}
