		public ShopViewModel(IShopService shopService, IUserService userService, IFacebookService facebookService, IAdService adService)
		{
			_shopService = shopService;
			_userService = userService;
			_facebookService = facebookService;
			_adService = adService;
		}

		public override async Task Update()
		{
			if (DeviceInfo.Platform == DevicePlatform.iOS)
			{
				return;
			}
			if (DeviceInfo.Platform == DevicePlatform.Android && _updateAfterPurchase)
			{
				_updateAfterPurchase = false;
				return;
			}
			base.Title = "Shop".Translate();
			_facebookService.SetCallback(null);
			base.IsBusy = true;
			ProductsResponse response = await _shopService.GetProducts();
			if (response.Products == null || response.Products.Count == 0)
			{
				return;
			}
			_userData = response.UserData;
			Dictionary<int, List<ShopItem>> shops = new Dictionary<int, List<ShopItem>>();
			Dictionary<string, InAppBillingProduct> dictionary = null;
			string[] array = (from x in response.Products
				where x.Section == 0
				select x.Identifier.ToLower()).ToArray();
			if (array.Length != 0)
			{
				dictionary = await GetIAP(array.ToArray());
			}
			foreach (ProductData product in response.Products)
			{
				if (string.IsNullOrEmpty(product.Image))
				{
					Log.Info("product image not set -> " + product.Identifier);
					continue;
				}
				if (!shops.ContainsKey(product.Section))
				{
					shops[product.Section] = new List<ShopItem>();
				}
				if (product.Identifier == "Free_Stars_Video")
				{
					product.GTStars = _adService.GetVideoReward();
				}
				string text = string.Empty;
				AddAmount(ref text, product.Money);
				AddAmount(ref text, product.GTStars);
				AddAmount(ref text, product.Medipacks);
				if (dictionary != null && dictionary.TryGetValue(product.Identifier.ToLower(), out var value))
				{
					product.Action = value.LocalizedPrice;
					product.StorePrice = (double)value.MicrosPrice * 1E-06;
					product.CurrencyCode = value.CurrencyCode;
				}
				ShopItem item = new ShopItem
				{
					Image = product.Image,
					ButtonText = product.Action.Translate(),
					Text = text,
					IsPremium = (product.Cost > 0m),
					Cost = (int)product.Cost,
					CommandParameter = product,
					Command = new AsyncCommand<object>(Buy)
				};
				shops[product.Section].Add(item);
			}
			shops.TryGetValue(0, out var value2);
			shops.TryGetValue(1, out var value3);
			shops.TryGetValue(2, out var value4);
			StarsShop = value2;
			FreeStars = value3;
			MedipackShop = value4;
			base.IsBusy = false;
		}

		private async Task<Dictionary<string, InAppBillingProduct>> GetIAP(string[] productIds)
		{
			Dictionary<string, InAppBillingProduct> products = null;
			IInAppBilling billing = CrossInAppBilling.Current;
			Dictionary<string, InAppBillingProduct> result;
			try
			{
				int num = 0;
				object obj = default(object);
				try
				{
					if (await billing.ConnectAsync(true))
					{
						products = (await billing.GetProductInfoAsync((ItemType)0, productIds))?.ToDictionary((InAppBillingProduct x) => x.ProductId);
						goto end_IL_00cb;
					}
					await base.PopupService.ShowErrorMessageAsync("StoreUnavailable".Translate());
					result = products;
					goto end_IL_0054;
					end_IL_00cb:;
				}
				catch (InAppBillingPurchaseException ex)
				{
					InAppBillingPurchaseException ex2 = ex;
					obj = ex2;
					num = 1;
				}
				catch (Exception ex3)
				{
					AppAnalytics.Instance.TrackError(ex3);
					await base.PopupService.ShowErrorMessageAsync("StoreUnavailable".Translate());
					goto IL_0412;
				}
				if (num == 1)
				{
					InAppBillingPurchaseException ex4 = (InAppBillingPurchaseException)obj;
					AppAnalytics.Instance.TrackError((Exception)(object)ex4);
					await base.PopupService.ShowErrorMessageAsync("StoreUnavailable".Translate());
				}
				goto IL_0412;
				end_IL_0054:;
			}
			finally
			{
				await billing.DisconnectAsync();
			}
			return result;
			IL_0412:
			return products;
		}

		private void AddAmount(ref string text, int amount)
		{
			if (amount > 0)
			{
				if (string.IsNullOrEmpty(text))
				{
					text = $"{amount:N0}";
				}
				else
				{
					text = $"{text} + {amount:N0}";
				}
			}
		}

		private async Task Buy(object item)
		{
			base.IsBusy = true;
			if (item is ProductData { Section: var section } productData)
			{
				switch (section)
				{
				case 0:
					await BuyInAppPurchase(productData);
					break;
				case 2:
					await BuyMedipacks(productData);
					break;
				default:
					await GetFreeStars(productData);
					break;
				}
			}
			base.IsBusy = false;
		}

		private async Task GetFreeStars(ProductData product)
		{
			switch (product.Identifier)
			{
			case "Free_Stars_Email":
				await ConnectEmailAsync();
				break;
			case "Free_Stars_Facebook":
				await ConnectFacebookAsync();
				break;
			case "Free_Stars_Video":
				ShowVideoAd();
				break;
			}
		}

