		{
			if (FreeStars != null && FreeStars.Count != 0)
			{
				ShopItem shopItem = FreeStars.FirstOrDefault((ShopItem x) => x.CommandParameter is ProductData productData && productData.Identifier == "Free_Stars_Video");
				if (shopItem != null)
				{
					shopItem.IsButtonEnabled = isEnabled;
					OnPropertyChanged("FreeStars");
				}
			}
		}

		private void ShowVideoAd()
		{
			_adService.ShowVideoIfAvailable(null);
		}

		public async Task BuyInAppPurchase(ProductData product)
		{
			IInAppBilling billing = CrossInAppBilling.Current;
			try
			{
				_ = 4;
				try
				{
					string productId = product.Identifier;
					if (DeviceInfo.Platform == DevicePlatform.Android)
					{
						productId = productId.ToLower();
					}
					if (!(await billing.ConnectAsync(true)))
					{
						await base.PopupService.ShowErrorMessageAsync("StoreUnavailable".Translate());
						return;
					}
					if (DeviceInfo.Platform == DevicePlatform.Android)
					{
						_updateAfterPurchase = true;
					}
					base.ResourceService.IsSuspended = true;
					InAppBillingPurchase val = await billing.PurchaseAsync(productId, (ItemType)0, (string)null, (string)null);
					Log.Info($"Purchase state is: {((val != null) ? new PurchaseState?(val.State) : ((PurchaseState?)null))}");
					if (val == (InAppBillingPurchase)null)
					{
						await base.PopupService.ShowErrorMessageAsync();
					}
					else if ((int)val.State == 0)
					{
						await VerifyPurchase(val, product);
					}
				}
				catch (InAppBillingPurchaseException ex)
				{
					InAppBillingPurchaseException ex2 = ex;
					AppAnalytics.Instance.TrackError((Exception)(object)ex2);
				}
				catch (Exception ex3)
				{
					AppAnalytics.Instance.TrackError(ex3);
				}
			}
			finally
			{
				base.ResourceService.IsSuspended = false;
				await billing.DisconnectAsync();
				ComponentFactory.Resolve<IShell>().Unlock();
			}
		}

		private async Task<bool> VerifyPurchase(InAppBillingPurchase purchase, ProductData product)
		{
			ResponseObject responseObject = await _shopService.VerifyPurchase(purchase);
			if (responseObject == null || responseObject.Status != ResponseStatus.OK)
			{
				return false;
			}
			bool finalized = false;
			IInAppBilling current = CrossInAppBilling.Current;
			if (!current.IsConnected)
			{
				Log.Info("$$$ Billing plugin is not connected");
				return false;
			}
			try
			{
				if (DeviceInfo.Platform == DevicePlatform.Android)
				{
					finalized = await current.ConsumePurchaseAsync(purchase.ProductId, purchase.PurchaseToken);
					Log.Info($"$ Purchase consumed = {finalized}");
				}
				else
				{
					IEnumerable<(string, bool)> enumerable = await current.FinalizePurchaseAsync(new string[1] { purchase.TransactionIdentifier });
					if (enumerable != null && enumerable.Any())
					{
						finalized = enumerable.First().Item2;
					}
					Log.Info($"$ Transaction finalized = {finalized}");
				}
				if (!finalized)
				{
					await base.PopupService.ShowErrorMessageAsync();
				}
			}
			catch (InAppBillingPurchaseException ex)
			{
				InAppBillingPurchaseException ex2 = ex;
				AppAnalytics.Instance.TrackError((Exception)(object)ex2);
			}
			catch (Exception ex3)
			{
				AppAnalytics.Instance.TrackError(ex3);
			}
			if (!finalized)
			{
				return false;
			}
			AppAnalytics.Instance.TrackPurchase(product.Identifier, product.CurrencyCode, product.StorePrice);
			TutorialPopupViewModel popupViewModel = new TutorialPopupViewModel("ShopSuccessTitle".Translate(), "ShopSuccessMessage".Translate(), product);
			await base.PopupService.ShowPopupAsync(popupViewModel);
			base.ResourceService.IsSuspended = false;
			await base.ResourceService.UpdateAsync();
			_updateAfterPurchase = false;
			await Update();
			return true;
		}

		private async Task BuyMedipacks(ProductData product)
		{
			if (await base.ResourceService.SpentGTStars((int)product.Cost, "BuyMedipacks".Translate(), string.Format("BuyMedipacksQuestion".Translate(), product.Medipacks, (int)product.Cost)) && (await _shopService.BuyProduct(product)).Status == ResponseStatus.OK)
			{
				await base.ResourceService.UpdateAsync();
			}
		}

		private async Task ConnectEmailAsync()
		{
			if (await _userService.ShowUpdateUserPopup(_userData))
			{
				await base.ResourceService.UpdateAsync();
				await Update();
			}
		}

		private async Task ConnectFacebookAsync()
		{
			FacebookAuthResult facebookAuthResult = await _facebookService.LoginAsync();
			if (facebookAuthResult.CallBack == CallbackType.Success)
			{
				if (!(await _userService.UpdateUser(new UserData
				{
					FacebookId = facebookAuthResult.UserId
				})))
				{
					_facebookService.Logout();
					return;
				}
				await base.ResourceService.UpdateAsync();
				await Update();
			}
		}
	}
