	public class SkillCardsViewModel : BaseViewModel
	{
		private SquadPlayerData _selectedPlayer;

		private decimal _strengthIncrease;

		private List<SkillCard> _skillCards;

		private List<SkillProgressData> _impactSkills;

		private List<SkillCard> _allCards;

		private readonly IPopupService _popupService;

		private int _previousPlayerPosition = -1;

		public SquadPlayerData SelectedPlayer
		{
			get
			{
				return _selectedPlayer;
			}
			set
			{
				Set(ref _selectedPlayer, value, "SelectedPlayer");
				UpdateImpactSkills();
				UpdateSkillCards();
				StrengthIncrease = 0m;
			}
		}

		public decimal StrengthIncrease
		{
			get
			{
				return _strengthIncrease;
			}
			set
			{
				Set(ref _strengthIncrease, value, "StrengthIncrease");
			}
		}

		public List<SkillCard> SkillCards
		{
			get
			{
				return _skillCards;
			}
			set
			{
				Set(ref _skillCards, value, "SkillCards");
				OnPropertyChanged("IsDescriptionVisible");
			}
		}

		public List<SkillProgressData> ImpactSkills
		{
			get
			{
				return _impactSkills;
			}
			set
			{
				Set(ref _impactSkills, value, "ImpactSkills");
			}
		}

		public bool IsDescriptionVisible
		{
			get
			{
				if (SkillCards != null)
				{
					return SkillCards.Count > 0;
				}
				return false;
			}
		}

		public ICommand UseCardCommand { get; }

		public SkillCardsViewModel()
		{
			_popupService = ComponentFactory.Resolve<IPopupService>();
			UseCardCommand = new AsyncCommand<SkillCard>(UseCard);
		}

		public void UpdateData(SkillCardsResponse response)
		{
			_allCards = response?.SkillCards ?? new List<SkillCard>();
			_previousPlayerPosition = -1;
			UpdateSkillCards();
		}

		private void UpdateSkillCards()
		{
			if (_allCards == null)
			{
				return;
			}
			if (SelectedPlayer == null)
			{
				foreach (SkillCard allCard in _allCards)
				{
					allCard.IsAvailable = false;
				}
				SkillCards = _allCards;
			}
			else
			{
				if (SelectedPlayer.Position == _previousPlayerPosition)
				{
					return;
				}
				_previousPlayerPosition = SelectedPlayer.Position;
				foreach (SkillCard allCard2 in _allCards)
				{
					allCard2.IsAvailable = !SelectedPlayer.IsForSale;
					if (allCard2.Skill == SelectedPlayer.MainSkill)
					{
						allCard2.Order = 1000000 + allCard2.Rarity * 10000;
					}
					else if (allCard2.Skill < 4)
					{
						allCard2.Order = allCard2.Skill + allCard2.Rarity * 100;
						allCard2.IsAvailable = false;
					}
					else
					{
						allCard2.Order = allCard2.Skill * 1000 + allCard2.Rarity * 10000;
					}
				}
				SkillCards = _allCards.OrderByDescending((SkillCard x) => x.Order).ToList();
			}
		}

		private void UpdateImpactSkills(List<SkillProgressData> oldSkills = null)
		{
			if (SelectedPlayer == null)
			{
				ImpactSkills = new List<SkillProgressData>();
				return;
			}
			List<SkillProgressData> list = SelectedPlayer.GetSkillDetails(impactOnly: true) ?? new List<SkillProgressData>();
			if (oldSkills != null && oldSkills.Count == list.Count)
			{
				for (int i = 0; i < list.Count; i++)
				{
					SkillProgressData skillProgressData = list[i];
					SkillProgressData skillProgressData2 = oldSkills[i];
					skillProgressData.Increase = skillProgressData2.Increase + skillProgressData.Value - skillProgressData2.Value;
				}
			}
			ImpactSkills = list;
		}

		private async Task UseCard(SkillCard card)
		{
			if (!card.IsAvailable || !(await _popupService.ShowYesNoMessageAsync("UseCardTitle".Translate(), string.Format("UseCardQuestion".Translate(), card.Name, card.Bonus, SelectedPlayer.Name))))
			{
				return;
			}
			ComponentFactory.Resolve<IShell>().StartProgress();
			decimal strength = SelectedPlayer.Strength;
			List<SkillProgressData> skills = ImpactSkills.ToList();
			UpgradeResponse upgradeResponse = await ComponentFactory.Resolve<ISquadService>().UseSkillCard(SelectedPlayer.ID, card.Skill, card.Rarity);
			if (upgradeResponse == null || upgradeResponse.Status != ResponseStatus.OK || upgradeResponse.Player == null)
			{
				ComponentFactory.Resolve<IShell>().StopProgress();
				return;
			}
			card.Count--;
			if (card.Count <= 0)
			{
				_allCards.Remove(card);
				SkillCards.Remove(card);
			}
			SkillCards = SkillCards.ToList();
			ComponentFactory.Resolve<ISoundManager>().PlaySound(Sounds.Money);
			SelectedPlayer.UpdateStrengthAndSkillsFrom(upgradeResponse.Player);
			OnPropertyChanged("SelectedPlayer");
			ComponentFactory.Resolve<SquadViewModel>().UpdateStrengthInTableForSelectedPlayer(upgradeResponse.Player.Strength);
			UpdateImpactSkills(skills);
			StrengthIncrease += upgradeResponse.Player.Strength - strength;
			Log.Info($"Strength increase = +{StrengthIncrease}");
			ComponentFactory.Resolve<IShell>().StopProgress();
		}
	}
	public class SkillProgressData
	{
		public string Name { get; set; }

		public decimal Value { get; set; }

		public decimal MaxValue { get; set; }

		public bool IsInt { get; set; }

		public bool IsHighlighted { get; set; }

		public string Text => Value.ToString(IsInt ? "N0" : "N2");

		public int DecimalPlaces
		{
			get
			{
				if (!IsInt)
				{
					return 2;
				}
				return 0;
			}
		}

		public bool IsVisible => !string.IsNullOrEmpty(Name);

		public TableCellColor Color { get; set; }

		public decimal Increase { get; set; }

		public SkillProgressData()
		{
		}

		public SkillProgressData(string name, decimal value, decimal maxValue = 100m, bool isMain = false, bool isBonus = false)
		{
			Name = name;
			Value = value;
			MaxValue = maxValue;
			if (isMain)
			{
				Color = TableCellColor.Highlight;
			}
			else if (isBonus)
			{
				Color = TableCellColor.Accent;
			}
			else
			{
				Color = TableCellColor.Default;
			}
		}
	}
