		public SquadViewModel(ISquadService squadService, INavigationService navigationService, IPopupService popupService, ICommonService commonService)
		{
			SelectedPlayerCommand = new Command<SquadPlayerData>(SelectPlayer);
			UpgradePlayerCommand = new AsyncCommand(UpgradePlayer);
			HealPlayerCommand = new AsyncCommand(HealPlayer);
			ExtendContractCommand = new AsyncCommand(ShowRenewContractForSelectedPlayerPopup);
			GoToTransferCommand = new Command(NavigateToTransfer);
			GoToScoutingCommand = new Command(NavigateToScouting);
			ChangeNameCommand = new AsyncCommand(ShowChangeNameForSelectedPlayerPopup);
			ChangeShirtCommand = new AsyncCommand(ChangeShirt);
			ChangeOriginCommand = new AsyncCommand(ShowChangeOriginPopup);
			FireCommand = new AsyncCommand(ShowFireSelectedPlayerPopup);
			ExtendAllContractsCommand = new AsyncCommand(ShowRenewAllContractsPopup);
			_navigationService = navigationService;
			_squadService = squadService;
			_popupService = popupService;
			_commonService = commonService;
			base.ShellViewModel.SetContextMenuImage(ScreenIdentifier.Squad, -1, "menu_player");
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "ChangeName".Translate(), ChangeNameCommand);
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "ShirtNo".Translate(), ChangeShirtCommand);
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "ChangeOrigin".Translate(), ChangeOriginCommand);
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "Training".Translate(), new Command(OpenTraining));
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "TrainingProgress".Translate(), new Command(OpenTrainingProgress));
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "Statistics".Translate(), new Command(OpenPlayerStatistics));
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "Contract".Translate(), ExtendContractCommand);
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "RenewAllContracts".Translate(), ExtendAllContractsCommand);
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Squad, -1, "FirePlayer".Translate(), FireCommand);
			AddChildViewModel<SkillCardsViewModel>();
		}

		private async Task HealPlayer()
		{
			if (SelectedPlayer == null || SelectedPlayer.Injured <= 0 || !(await base.ResourceService.SpentMedipacks(SelectedPlayer.Injured, string.Format("HealPlayerPopupHeadline".Translate(), SelectedPlayer.Name), string.Format("HealPlayerPopupText".Translate(), SelectedPlayer.Injured))))
			{
				return;
			}
			base.IsBusy = true;
			ResponseObject obj = await _squadService.HealPlayer(SelectedPlayer.ID);
			base.IsBusy = false;
			if (obj.Status == ResponseStatus.OK)
			{
				SelectedPlayer.Injured = 0;
				UpdatePlayerTableRow(SelectedPlayer, delegate(PlayerRow row)
				{
					row.SetInjured(0);
				});
				RefreshSelectedPlayer();
			}
			else
			{
				await Update();
			}
		}

		private void NavigateToScouting()
		{
			_navigationService.NavigateTo(ScreenIdentifier.Scouting);
		}

		private void NavigateToTransfer()
		{
			_navigationService.NavigateTo(ScreenIdentifier.Transfermarket);
		}

		private void OnPlayerSelected()
		{
			if (SelectedPlayer != null)
			{
				base.Title = SelectedPlayer.Name;
				if (SelectedPlayer.IsUpgraded)
				{
					UpgradeDescription = ((SelectedPlayer.Age < 34) ? "PlayerAlreadyUpgraded".Translate() : "PlayerAlreadyUpgradedOld".Translate());
				}
				else if (SelectedPlayer.IsForSale)
				{
					UpgradeDescription = "PlayerOnTransferMarket".Translate();
				}
				else
				{
					UpgradeDescription = string.Empty;
				}
				UpgradeStrength = SelectedPlayer.Strength;
				Skills = SelectedPlayer.GetSkillDetails();
			}
			UpdateSellStuffForPlayer();
			ComponentFactory.Resolve<SkillCardsViewModel>().SelectedPlayer = SelectedPlayer;
		}

		private void RefreshSelectedPlayer()
		{
			OnPropertyChanged("SelectedPlayer");
			OnPlayerSelected();
			NeedToRefresh++;
		}

		private async Task UpgradePlayer()
		{
			if (!string.IsNullOrEmpty(UpgradeDescription))
			{
				await _popupService.ShowOkMessageAsync("PlayerUpgradeTitle".Translate(), UpgradeDescription);
				return;
			}
			UpgradeStrength = Math.Round(UpgradeStrength, 2);
			if (await base.ResourceService.SpentGTStars(UpgradeCost, "PlayerUpgradeTitle".Translate(), string.Format("PlayerUpgradeQuestion".Translate(), SelectedPlayer.Name, UpgradeStrength, StrengthIncrease, UpgradeCost, SelectedPlayer.Salary)))
			{
				base.IsBusy = true;
				UpgradeResponse result = await _squadService.UpgradePlayer(SelectedPlayer.ID, UpgradeStrength, UpgradeCost);
				if (result.Status == ResponseStatus.NeedToRefresh)
				{
					await Update();
				}
				base.IsBusy = false;
				if (result.Status != ResponseStatus.OK || result.Player == null)
				{
					await base.ResourceService.UpdateAsync();
					return;
				}
				SelectedPlayer.UpdateStrengthAndSkillsFrom(result.Player);
				UpdateStrengthInTableForSelectedPlayer(SelectedPlayer.Strength);
				RefreshSelectedPlayer();
			}
		}

		public void UpdateStrengthInTableForSelectedPlayer(decimal strength)
		{
			UpdatePlayerTableRow(SelectedPlayer, delegate(PlayerRow row)
			{
				row.SetStrength(strength);
			});
		}

		public override async Task Update()
		{
			base.Title = "Squad".Translate();
			base.IsBusy = true;
			ComponentFactory.Resolve<IShell>().StartProgress();
			SquadResponse result = await _squadService.GetPlayers();
			_countries = await _commonService.GetCountries();
			SkillCardsResponse response = await _squadService.GetSkillCards();
			ComponentFactory.Resolve<SkillCardsViewModel>().UpdateData(response);
			if (result.Status == ResponseStatus.OK)
			{
				if (result.Players == null || result.Players.Count == 0)
				{
					PlayerTableRows = null;
					base.IsBusy = false;
					return;
				}
				SquadShirt = result.HomeShirt;
				_changeNameCost = result.CostRename;
				_changeOriginCost = result.CostOrigin;
				_changeShirtCost = result.CostShirt;
				_upgradeCostFactor = result.CostUpgrade;
				_players = (from x in result.Players
					orderby x.GetPositionOrder(), x.Strength descending
					select x).ToList();
				UpdatePlayers(SelectedPlayer == null);
				UpdateSellStuff(result);
			}
			base.IsBusy = false;
		}

		public async Task CheckUnContracted()
		{
			if (_players == null || _players.Count == 0)
			{
				return;
			}
			List<SquadPlayerData> list = _players.Where((SquadPlayerData x) => !x.HasContract).ToList();
			if (list.Count != 0)
			{
				string value = "LocalNotificationPlayerContractEndManyTitle";
				string message;
				if (list.Count != 1)
				{
					message = ((list.Count != 2) ? string.Format("LocalNotificationPlayerContractEndManyBody".Translate(), list[0].Name, list.Count - 1) : string.Format("LocalNotificationPlayerContractEndTwoBody".Translate(), list[0].Name, list[1].Name));
				}
				else
				{
					value = "LocalNotificationPlayerContractEndOneTitle";
					message = string.Format("LocalNotificationPlayerContractEndOneBody".Translate(), list[0].Name);
				}
				if (await base.PopupService.ShowYesNoMessageAsync(value.Translate(), message, Character.Anna))
				{
					await ShowRenewAllContractsPopup();
				}
			}
		}

		private void UpdatePlayers(bool selectFirstOne)
		{
			Guid selectedPlayerId = ((SelectedPlayer == null || selectFirstOne) ? Guid.Empty : SelectedPlayer.ID);
			PlayerTableRows = PlayerRow.GetPlayersTableRows(_players, delegate(PlayerRow row, SquadPlayerData player)
			{
				player.ShirtName = SquadShirt;
				if (selectFirstOne)
				{
					SelectedPlayer = player;
					selectFirstOne = false;
				}
				else if (player.ID == selectedPlayerId)
				{
					SelectedPlayer = player;
				}
				row.Command = SelectedPlayerCommand;
				row.CommandParameter = player;
				row.AutoSelect = true;
				row.IsSelected = player == SelectedPlayer;
				row.Background = ((!player.IsReady) ? TableRowBackground.Warning : TableRowBackground.Default);
			}, SquadShirt, orderPlayers: false, showShirt: true);
		}

		private void SelectPlayer(SquadPlayerData player)
		{
			SelectedPlayer = player;
			foreach (ITableRow playerTableRow in PlayerTableRows)
			{
				if (playerTableRow is PlayerRow playerRow)
				{
					playerRow.IsSelected = player == playerRow.Player;
				}
			}
			OnPropertyChanged("PlayerTableRows");
		}

