		private async Task ShowChangeNameForSelectedPlayerPopup()
		{
			if (SelectedPlayer == null)
			{
				return;
			}
			EntryPopupViewModel poupVM = new EntryPopupViewModel
			{
				Title = "ChangePlayerName".Translate(),
				ConfirmButtonTitle = "Change".Translate(),
				Message = string.Format("ChangePlayerNamePopupText".Translate(), SelectedPlayer.Name),
				IsButtonPremium = true,
				PriceValue = _changeNameCost
			};
			if (await _popupService.ShowPopupAsync(poupVM) != PopupResult.Done || !(await base.ResourceService.SpentGTStars(_changeNameCost, "ChangePlayerName".Translate(), string.Format("ChangeNameQuestion".Translate(), SelectedPlayer.Name, poupVM.EnteredText.Trim(), _changeNameCost))))
			{
				return;
			}
			TextResponse textResponse = await _squadService.RenamePlayer(SelectedPlayer.ID, poupVM.EnteredText.Trim());
			if (textResponse.Status == ResponseStatus.OK && string.IsNullOrEmpty(textResponse.ErrorMessage))
			{
				SelectedPlayer.Name = textResponse.Text;
				base.Title = SelectedPlayer.Name;
				ComponentFactory.Resolve<ILegacyService>().UpdatePlayer(SelectedPlayer);
				UpdatePlayerTableRow(SelectedPlayer, delegate(PlayerRow row)
				{
					row.SetName(SelectedPlayer.Name);
				});
				RefreshSelectedPlayer();
			}
		}

		private void UpdatePlayerTableRow(SquadPlayerData player, Action<PlayerRow> updateAction)
		{
			if (PlayerTableRows != null)
			{
				PlayerRow playerRow = PlayerTableRows.OfType<PlayerRow>().FirstOrDefault((PlayerRow x) => x.Player == player);
				if (playerRow != null)
				{
					updateAction?.Invoke(playerRow);
					OnPropertyChanged("PlayerTableRows");
				}
			}
		}

		private Task ShowRenewContractForSelectedPlayerPopup()
		{
			if (SelectedPlayer == null)
			{
				return Task.FromResult(result: false);
			}
			return RenewContracts(SelectedPlayer);
		}

		private Task ShowRenewAllContractsPopup()
		{
			return RenewContracts(null);
		}

		private async Task RenewContracts(SquadPlayerData player)
		{
			base.IsBusy = true;
			Guid playerId = player?.ID ?? Guid.Empty;
			PlayerContractResponse playerContractResponse = await _squadService.GetContractRenewalCost(playerId);
			base.IsBusy = false;
			if (playerContractResponse.Status != ResponseStatus.OK)
			{
				return;
			}
			if (playerContractResponse.Contracts == null || !playerContractResponse.Contracts.Any())
			{
				if (!string.IsNullOrEmpty(playerContractResponse.Resolution))
				{
					await _popupService.ShowOkMessageAsync("ContractRenewTitle".Translate(), playerContractResponse.Resolution, "Ok".Translate(), Character.Anna);
				}
				return;
			}
			decimal salary = default(decimal);
			int premiumPriceValue;
			int priceValue;
			string message;
			if (playerContractResponse.Contracts.Count == 1)
			{
				PlayerContractItem playerContractItem = playerContractResponse.Contracts.FirstOrDefault();
				DateTime date = playerContractItem.EndDate.ParseToDate();
				premiumPriceValue = playerContractItem.PremiumCost;
				priceValue = playerContractItem.BudgetCost;
				salary = playerContractItem.Salary;
				message = string.Format("ContractRenewText".Translate(), playerContractItem.PlayerName, date.ToGTDateTimeString(), playerContractItem.Salary.ToString("N0"));
			}
			else
			{
				premiumPriceValue = playerContractResponse.Contracts.Sum((PlayerContractItem x) => x.PremiumCost);
				priceValue = playerContractResponse.Contracts.Sum((PlayerContractItem x) => x.BudgetCost);
				message = string.Format("RenewContractsQuestion".Translate(), playerContractResponse.Contracts.Count);
			}
			ContractPopupViewModel popupViewModel = new ContractPopupViewModel
			{
				Title = "ContractRenewTitle".Translate(),
				Message = message,
				ExtendContractButtonTitle = "ContractRenewButton".Translate(),
				PremiumPriceValue = premiumPriceValue,
				PriceValue = priceValue
			};
			PopupResult popupResult = await _popupService.ShowPopupAsync(popupViewModel);
			if (popupResult == PopupResult.None || popupResult == PopupResult.Closed)
			{
				return;
			}
			bool premium = popupResult == PopupResult.Done;
			if (!(await base.ResourceService.Spent(premium ? premiumPriceValue : priceValue, premium)))
			{
				return;
			}
			PlayerContractResponse playerContractResponse2 = await _squadService.ExtendPlayerContract(playerId, premium, salary);
			if (playerContractResponse2.Status != ResponseStatus.OK || playerContractResponse2.Contracts == null || !playerContractResponse2.Contracts.Any())
			{
				return;
			}
			Dictionary<Guid, PlayerRow> dictionary = PlayerTableRows.OfType<PlayerRow>().ToDictionary((PlayerRow x) => x.Player.ID);
			foreach (PlayerContractItem contract in playerContractResponse2.Contracts)
			{
				if (dictionary.TryGetValue(contract.PlayerID, out var value))
				{
					value.Player.EndDate = contract.EndDate;
					value.Player.Salary = contract.Salary;
					value.Player.MarketValue = contract.MarketValue;
					value.Player.CanExtendContract = false;
					value.UpdateBackground();
				}
			}
			ComponentFactory.Resolve<ILegacyService>().UpdateContracts(playerContractResponse2.Contracts);
			OnPropertyChanged("PlayerTableRows");
			RefreshSelectedPlayer();
		}

		private async Task ShowFireSelectedPlayerPopup()
		{
			if (SelectedPlayer != null && await _popupService.ShowYesNoMessageAsync("FirePlayer".Translate(), string.Format("FirePlayerQuestion".Translate(), SelectedPlayer.Name)))
			{
				base.IsBusy = true;
				if ((await _squadService.FirePlayer(SelectedPlayer.ID)).Status != ResponseStatus.OK)
				{
					base.IsBusy = false;
					return;
				}
				RemoveSelectedPlayerFromList();
				base.IsBusy = false;
			}
		}

		private void RemoveSelectedPlayerFromList()
		{
			int num = Math.Max(0, _players.IndexOf(SelectedPlayer));
			if (num == _players.Count)
			{
				num = _players.Count - 1;
			}
			_players.Remove(SelectedPlayer);
			ComponentFactory.Resolve<ILegacyService>().RemovePlayer(SelectedPlayer.ID);
			if (num < _players.Count)
			{
				SelectedPlayer = _players[num];
			}
			else
			{
				SelectedPlayer = null;
			}
			UpdatePlayers(SelectedPlayer == null);
		}

		private async Task ShowChangeOriginPopup()
		{
			if (SelectedPlayer == null)
			{
				return;
			}
			ChangeOriginPopupViewModel popupVM = new ChangeOriginPopupViewModel
			{
				PriceValue = _changeOriginCost,
				Countries = _countries,
				Message = string.Format("ChangeOriginPopupText".Translate(), SelectedPlayer.Name),
				SelectedOrigin = new CountryData
				{
					Short = SelectedPlayer.Country
				}
			};
			if (await _popupService.ShowPopupAsync(popupVM) == PopupResult.Done && await base.ResourceService.SpentGTStars(_changeOriginCost, "ChangeOrigin".Translate(), string.Format("ChangeOriginQuestion".Translate(), SelectedPlayer.Name, popupVM.SelectedOrigin.Name, _changeOriginCost)) && (await _squadService.ChangeOrigin(SelectedPlayer.ID, popupVM.SelectedOrigin.Id)).Status == ResponseStatus.OK)
			{
				SelectedPlayer.Country = popupVM.SelectedOrigin.Short;
				SelectedPlayer.Origin = popupVM.SelectedOrigin.Name;
				ComponentFactory.Resolve<ILegacyService>().UpdatePlayerCountry(SelectedPlayer.ID, popupVM.SelectedOrigin);
				UpdatePlayerTableRow(SelectedPlayer, delegate(PlayerRow row)
				{
					row.SetCountry(SelectedPlayer.Country);
				});
				RefreshSelectedPlayer();
			}
		}

		private async Task ChangeShirt()
		{
			if (SelectedPlayer == null)
			{
				return;
			}
			ChangeShirtPopupViewModel shirtNumberPopup = new ChangeShirtPopupViewModel(SelectedPlayer.Name)
			{
				PriceValue = _changeShirtCost,
				Shirt = SquadShirt,
				SelectedNumber = SelectedPlayer.Shirt
			};
			PopupResult popupResult = await _popupService.ShowPopupAsync(shirtNumberPopup);
			Log.Info($"Shirt popup result = {popupResult}");
			if (popupResult == PopupResult.Done && await base.ResourceService.SpentGTStars(_changeShirtCost, "ShirtNo".Translate(), string.Format("ChangeShirtNrQuestion".Translate(), SelectedPlayer.Name, shirtNumberPopup.SelectedNumber, _changeShirtCost)) && (await _squadService.ChangeShirt(SelectedPlayer.ID, shirtNumberPopup.SelectedNumber)).Status == ResponseStatus.OK)
			{
				SelectedPlayer.Shirt = shirtNumberPopup.SelectedNumber;
				ComponentFactory.Resolve<ILegacyService>().UpdatePlayer(SelectedPlayer);
				UpdatePlayerTableRow(SelectedPlayer, delegate(PlayerRow row)
				{
					row.SetShirtNumber(shirtNumberPopup.SelectedNumber);
				});
				RefreshSelectedPlayer();
			}
		}

		private async Task SendPlayerToTransfermarket()
		{
			if (SelectedPlayer == null || !(await _popupService.ShowYesNoMessageAsync("SellPlayerOnTransfermarketTitle".Translate(), string.Format("SellPlayerOnTransfermarketQuestion".Translate(), SelectedPlayer.Name, AuctionPrice))) || !(await base.ResourceService.SpentMoney((int)SelectedPlayer.TransfermarketFee)))
			{
				return;
			}
			base.IsBusy = true;
			TransfermarketPlayerResponse transfermarketPlayerResponse = await _squadService.SendToTransfermarket(SelectedPlayer.ID, (int)AuctionHours, AuctionPrice);
			if (transfermarketPlayerResponse.Status != ResponseStatus.OK)
			{
				base.IsBusy = false;
				return;
			}
			SelectedPlayer.IsForSale = true;
			_mySellings[SelectedPlayer.ID] = transfermarketPlayerResponse.Player;
			UpdatePlayerTableRow(SelectedPlayer, delegate(PlayerRow row)
			{
				row.SetSellStatus(isForSale: true);
			});
			UpdateSellStuffForPlayer();
			base.IsBusy = false;
		}

		private async Task SellPlayerToBank()
		{
			if (SelectedPlayer != null && await _popupService.ShowYesNoMessageAsync("SellPlayerTitle".Translate(), string.Format("SellPlayerQuestion".Translate(), SelectedPlayer.Name, SelectedPlayer.SellPrice)))
			{
				base.IsBusy = true;
				if ((await _squadService.SellPlayer(SelectedPlayer.ID)).Status != ResponseStatus.OK)
				{
					base.IsBusy = false;
					return;
				}
				base.ResourceService.Update();
				RemoveSelectedPlayerFromList();
				base.IsBusy = false;
			}
		}

		private void UpdateSellStuff(SquadResponse squad)
		{
			_mySellings = squad.PlayersOnTransfermarket.ToDictionary((TransfermarketPlayerData x) => x.ID);
			AuctionMinHours = squad.TransfermarketMinHours;
		}

		private void UpdateSellStuffForPlayer()
		{
			if (SelectedPlayer != null)
			{
				if (_mySellings.TryGetValue(SelectedPlayer.ID, out var value))
				{
					IsOnAuction = true;
					BidTeamName = (string.IsNullOrEmpty(value.BidTeamName) ? "NoBidsText".Translate() : value.BidTeamName);
					BidTeamLogo = value.BidTeamLogo;
					CurrentBid = value.Bid;
					TransfermarketEndDate = value.EndDateValue.ToGTDateTimeString();
					return;
				}
				IsOnAuction = false;
				SendToAuctionCost = (int)SelectedPlayer.TransfermarketFee;
				AuctionDescription = string.Format("SellPlayerOnTransfermarket".Translate(), SelectedPlayer.Name);
				SellDescription = string.Format("SellPlayerText".Translate(), SelectedPlayer.Name, SelectedPlayer.SellPrice);
				AuctionMinPrice = (double)SelectedPlayer.TransfermarketMinOffer;
				AuctionMaxPrice = (double)SelectedPlayer.TransfermarketMaxOffer;
				AuctionPrice = (decimal)AuctionMaxPrice;
				AuctionMaxHours = SelectedPlayer.TransfermarketMaxHours;
				AuctionHours = (decimal)AuctionMaxHours;
				SellStuffUpdate++;
			}
		}
	}
