	public class TrainingProgressViewModel : PlayerInfoViewModel
	{
		private readonly ISquadService _squadService;

		private readonly string[] _skills;

		private List<ITableRow> _skillTableRows;

		private SkillTrainingData _selectedSkill;

		private List<SkillTrainingData> _trainingProgress;

		protected override string InfoName => "Training progress".Translate();

		public List<ITableRow> SkillTableRows
		{
			get
			{
				return _skillTableRows;
			}
			set
			{
				Set(ref _skillTableRows, value, "SkillTableRows");
			}
		}

		public HeaderRow SkillsTableHeader => new HeaderRow(new HeaderCell("Skills".Translate(), 1, TableCellAlignment.Center));

		public SkillTrainingData SelectedSkill
		{
			get
			{
				return _selectedSkill;
			}
			set
			{
				Set(ref _selectedSkill, value, "SelectedSkill");
			}
		}

		public List<SkillTrainingData> TrainingProgress
		{
			get
			{
				return _trainingProgress;
			}
			set
			{
				Set(ref _trainingProgress, value, "TrainingProgress");
			}
		}

		public TrainingProgressViewModel(ISquadService squadService)
		{
			_squadService = squadService;
			_skills = Skill.GetAllSkills();
		}

		public override async Task Update()
		{
			await base.Update();
			TrainingProgressResponse trainingProgressResponse = await _squadService.GetTrainingProgress(base.SelectedPlayerId);
			if (trainingProgressResponse.Status != ResponseStatus.OK || trainingProgressResponse.Progress == null || trainingProgressResponse.Progress.Count == 0)
			{
				return;
			}
			List<SkillTrainingData> list = new List<SkillTrainingData>();
			for (int i = 0; i < trainingProgressResponse.Progress.Count; i++)
			{
				list.Add(new SkillTrainingData(_skills[i], ChartData.CreateChart(trainingProgressResponse.Progress[i], (TrainingProgressData x) => x.Date.ParseToDate(), (TrainingProgressData x) => x.Value, "N2")));
			}
			List<ITableRow> list2 = new List<ITableRow>();
			foreach (SkillTrainingData item in list)
			{
				TableRow row = new TableRow(new TextCell(item.Name));
				row.Command = new Command(delegate
				{
					SelectRow(row, item);
				});
				list2.Add(row);
			}
			TrainingProgress = list;
			SkillTableRows = list2;
			SelectRow(list2[0], list[0]);
		}

		private void SelectRow(ITableRow selectedRow, SkillTrainingData skill)
		{
			foreach (ITableRow skillTableRow in SkillTableRows)
			{
				if (skillTableRow is TableRow tableRow)
				{
					tableRow.IsSelected = tableRow == selectedRow;
				}
			}
			SelectedSkill = skill;
			OnPropertyChanged("SkillTableRows");
		}
	}
