			set
			{
				Set(ref _canDecrease, value, "CanDecrease");
			}
		}

		public Building Building { get; }

		protected int SpeedupCost { get; }

		public BaseStadiumPopupViewModel(Building building, bool buildInProgress, int speedUpCost)
		{
			base.Background = PopupBackground.Spotlights;
			Building = building;
			SpeedupCost = speedUpCost;
			BuildInProgress = buildInProgress;
			CanBuild = !buildInProgress && building.IsNotMaxLevel;
			CanDecrease = !buildInProgress && building.IsNotMinLevel;
			IsLockVisible = buildInProgress && !building.IsUnderConstruction && building.IsNotMaxLevel;
			_timerEngine = new TimerEngine();
			_timerEngine.TimeChanged += OnTimeChanged;
			_popupService = ComponentFactory.Resolve<IPopupService>();
			StadiumService = ComponentFactory.Resolve<INewStadiumService>();
			ShowLockedCommand = new AsyncCommand(ShowLocked);
			BuildCommand = new AsyncCommand(Build);
			PremiumBuildCommand = new AsyncCommand(PremiumBuild);
			SpeedupCommand = new AsyncCommand<BuildingData>(Speedup);
		}

		public override Task Update()
		{
			if (Building.IsUnderConstruction)
			{
				SetEndDate(Building.BuildEnd, Building.TotalBuildSeconds);
			}
			return base.Update();
		}

		private void OnTimeChanged(object sender, TimeChangedEventArgs e)
		{
			TimeLeft = e.TimeLeft;
			TimerIsRunning = !e.IsFinished;
			BuildProgress = e.Progress;
			if (BuildInProgress && !TimerIsRunning)
			{
				Close(PopupResult.Done);
			}
			else
			{
				OnTimeChanged();
			}
		}

		protected virtual void OnTimeChanged()
		{
		}

		protected void SetEndDate(DateTime date, double totalBuildSeconds)
		{
			_timerEngine.SetEndDate(date, totalBuildSeconds);
		}

		private async Task ShowLocked()
		{
			await _popupService.ShowOkMessageAsync("BuildingInProgressTitle".Translate(), "BuildingInProgressMessage".Translate(), "Ok".Translate(), Character.Anna);
		}

		private async Task Speedup(BuildingData buildingData)
		{
			int speedupPrice = buildingData.GetSpeedupPrice(SpeedupCost);
			if (await ResourceService.Current.SpentGTStars(speedupPrice, "BuildingSpeedupTitle".Translate(), string.Format("BuildingSpeedupQuestion".Translate(), buildingData.Name, speedupPrice), Character.Anna))
			{
				await Finish((await StadiumService.Speedup(buildingData.Id)).Status);
			}
		}

		protected abstract string GetPremiumBuildQuestion();

		private async Task PremiumBuild()
		{
			if (await ResourceService.Current.SpentGTStars(PremiumPrice, "BuildingUpgradeTitle".Translate(), GetPremiumBuildQuestion(), Character.Anna))
			{
				await BuildTask(premium: true);
			}
		}

		private async Task Build()
		{
			if (EuroPrice > 0)
			{
				if (!(await ResourceService.Current.SpentMoney(EuroPrice)))
				{
					return;
				}
			}
			else if (!(await ComponentFactory.Resolve<IPopupService>().ShowYesNoMessageAsync("DeconstructionTitle".Translate(), "DeconstructionQuestion".Translate(), Character.Anna)))
			{
				return;
			}
			await BuildTask(premium: false);
		}

		private async Task BuildTask(bool premium)
		{
			await Finish(await OnBuild(premium));
		}

		private async Task Finish(ResponseStatus result)
		{
			if (result != ResponseStatus.OK)
			{
				await ResourceService.Current.UpdateAsync();
				Close(PopupResult.Canceled);
			}
			else
			{
				Close(PopupResult.Done);
			}
		}

		protected virtual Task<ResponseStatus> OnBuild(bool premium)
		{
			return Task.FromResult(ResponseStatus.OK);
		}

		public override void OnClose(PopupResult popupResult)
		{
			base.OnClose(popupResult);
			Dispose();
		}

		public void Dispose()
		{
			Log.Info("[-] Timer engine disposed");
			if (_timerEngine != null)
			{
				_timerEngine.Stop();
				_timerEngine.TimeChanged -= OnTimeChanged;
				_timerEngine = null;
			}
		}
	}
	public class Building
	{
		public Guid Id { get; set; }

		public float X { get; set; }

		public float Y { get; set; }

		public float Height { get; set; }

		public float Width { get; set; }

		public BuildingData Data { get; set; }

		public List<BuildingData> Subproperties { get; set; }

		public string ImageName { get; set; }

		public int Level { get; set; }

		public int MaxLevel { get; set; } = 20;

		public int CurrentMaxLevel { get; set; }

		public int MaxTier { get; set; } = 6;

		public bool HasWarning { get; set; }

		public int Tier
		{
			get
			{
				if (Level < MaxLevel)
				{
					return (int)Math.Ceiling((float)Level / (float)MaxLevel * (float)(MaxTier - 1));
				}
				return MaxTier;
			}
		}

		public bool IsUnderConstruction { get; set; }

		public string CurrentImageName
		{
			get
			{
				if (!IsUnderConstruction)
				{
					return $"{Key}{Tier:00}";
				}
				return Key;
			}
		}

		private bool HasSubproperties
		{
			get
			{
				if (Subproperties != null)
				{
					return Subproperties.Count > 0;
				}
				return false;
			}
		}

		public bool IsNotMaxLevel
		{
			get
			{
				if (!HasSubproperties)
				{
					return Level < CurrentMaxLevel;
				}
				return Subproperties.Any((BuildingData x) => x.CurrentValue < x.MaxValue);
			}
		}

		public bool IsNotMinLevel
		{
			get
			{
				if (!HasSubproperties)
				{
					return Level > 0;
				}
				return Subproperties.Any((BuildingData x) => x.CurrentValue > 0);
			}
		}

		public double TotalBuildSeconds
		{
			get
			{
				if (!HasSubproperties)
				{
					return Data.TotalBuildSeconds;
				}
				return Subproperties.Sum((BuildingData x) => x.TotalBuildSeconds);
			}
		}

		public DateTime BuildEnd
		{
			get
			{
				if (!HasSubproperties)
				{
					return Data.BuildEndValue;
				}
				return Subproperties.Max((BuildingData x) => x.BuildEndValue);
			}
		}

		private string Key => "building_" + ImageName;
	}
