		public BuildingPopupViewModel(Building building, bool buildInProgress, int speedUpCost)
			: base(building, buildInProgress, speedUpCost)
		{
			requiredOfficeLevel = building.Level + 1;
			ShowWarningCommand = new AsyncCommand(ShowWarning);
			HasWarning = building.HasWarning;
			base.CanBuild = base.CanBuild && !building.HasWarning;
			base.Size = (base.CanBuild ? PopupSize.Medium : PopupSize.Small);
			Building building2 = new Building();
			building.CopyPropertiesTo(building2);
			building2.Level = Math.Min(building.MaxLevel, building.Level + 1);
			ButtonTitle = ((building.Level == 0) ? "Build".Translate() : "Upgrade".Translate());
			base.Title = building.Data.Name;
			LevelValue = $"{building.Level} / {building.MaxLevel}";
			Description = building.Data.Description;
			ImageName = building2.CurrentImageName;
			LevelText = string.Format("{0} {1}", "Level".Translate(), building2.Level);
			base.EuroPrice = (int)building.Data.UpgradeCost;
			base.PremiumPrice = (int)building.Data.UpgradeCostPremium;
			base.Profit = FormatValue(building.Data.Profit, building.Data.ProfitSign);
			base.ProfitIncrease = FormatValue(building.Data.ProfitIncrease, building.Data.ProfitSign, "+");
			Effect = ((building.Data.ProfitSign == "€") ? "Income".Translate() : building.Data.EffectName);
			base.Cost = FormatValue(building.Data.DailyCost, "€");
			base.CostIncrease = FormatValue(building.Data.DailyCostIncrease, "€", "+");
			Duration = TimeSpan.FromMinutes((double)building.Data.Duration).ToLocalizedString(onlyDays: true);
		}

		private async Task ShowWarning()
		{
			await ComponentFactory.Resolve<IPopupService>().ShowOkMessageAsync("UpgradeUnavailable".Translate(), string.Format("BuildingRequirementText".Translate(), requiredOfficeLevel), Character.Anna);
		}

		private string FormatValue(decimal value, string sign, string prefix = "")
		{
			if (!(value > 0m))
			{
				return string.Empty;
			}
			return $"{prefix}{value:N0}{sign}  ";
		}

		protected override void OnTimeChanged()
		{
			SpeedupPrice = base.Building.Data.GetSpeedupPrice(base.SpeedupCost);
		}

		protected override string GetPremiumBuildQuestion()
		{
			return string.Format("BuildingUpgradeQuestion".Translate(), base.Building.Data.Name, base.PremiumPrice);
		}

		protected override async Task<ResponseStatus> OnBuild(bool premium)
		{
			return (await base.StadiumService.Build(base.Building.Id, premium)).Status;
		}
	}
