	public class StadiumPlaces
	{
		public BuildingData BuildingData { get; }

		public string Name { get; set; }

		public int Count { get; set; }

		public int MaxCount { get; set; }

		public int Increase { get; set; }

		public int Capacity { get; set; }

		public decimal Price { get; set; }

		public decimal PricePremium { get; set; }

		public decimal Income { get; set; }

		public decimal Outcome { get; set; }

		public decimal Time { get; set; }

		public int SpeedupPrice { get; set; }

		public bool IsIncreaseEnabled => Current < Math.Max(Count, MaxCount);

		public bool IsDecreaseEnabled => Current > ((BuildingData.Id == Guids.Building_StadiumStands) ? 100 : 0);

		public int Current => Count + Increase;

		public string IncreaseText
		{
			get
			{
				if (!BuildingData.IsUnderConstruction)
				{
					return Increase.ToSignedString();
				}
				return (BuildingData.NewValue - BuildingData.CurrentValue).ToSignedString();
			}
		}

		public string Duration
		{
			get
			{
				TimeSpan timeSpan = TimeSpan.FromMinutes((double)((decimal)Math.Abs(Increase) * Time));
				if (!(timeSpan != TimeSpan.Zero))
				{
					return string.Empty;
				}
				return timeSpan.ToLocalizedString(onlyDays: true);
			}
		}

		public StadiumPlaces(BuildingData buildingData)
		{
			BuildingData = buildingData;
			if (buildingData != null)
			{
				Name = buildingData.Name;
				Count = buildingData.CurrentValue;
				MaxCount = buildingData.MaxValue;
				Capacity = buildingData.Capacity;
				Income = buildingData.Profit;
				Outcome = buildingData.DailyCost;
				Price = buildingData.UpgradeCost;
				PricePremium = buildingData.UpgradeCostPremium;
				Time = buildingData.Duration;
			}
		}
	}
