				Set(ref _isBuildEnabled, value, "IsBuildEnabled");
			}
		}

		public StadiumPlaces Stands => _places[Guids.Building_StadiumStands];

		public StadiumPlaces Seats => _places[Guids.Building_StadiumSeats];

		public StadiumPlaces Vips => _places[Guids.Building_StadiumVips];

		public string BuildTitle
		{
			get
			{
				if (base.EuroPrice <= 0 && _places.Values.Any((StadiumPlaces x) => x.Increase != 0))
				{
					return _textDestroy;
				}
				return _textBuild;
			}
		}

		public ICommand IncreaseCommand { get; }

		public ICommand DecreaseCommand { get; }

		public StadiumPopupViewModel(string stadiumName, Building building, bool buildInProgress, int speedUpCost)
			: base(building, buildInProgress, speedUpCost)
		{
			IncreaseCommand = new Command<StadiumPlaces>(IncreaseCount);
			DecreaseCommand = new Command<StadiumPlaces>(DecreaseCount);
			base.Size = PopupSize.Medium;
			base.Title = string.Format("{0} ({1:N0} {2})", stadiumName, building.Level, "Places".Translate());
			_places = new Dictionary<Guid, StadiumPlaces>();
			foreach (BuildingData subproperty in building.Subproperties)
			{
				_places.Add(subproperty.Id, new StadiumPlaces(subproperty));
			}
			CheckProperty(Guids.Building_StadiumStands);
			CheckProperty(Guids.Building_StadiumSeats);
			CheckProperty(Guids.Building_StadiumVips);
			Refresh();
		}

		private void CheckProperty(Guid id)
		{
			if (!_places.ContainsKey(id))
			{
				_places.Add(id, new StadiumPlaces(null));
			}
		}

		private void IncreaseCount(StadiumPlaces places)
		{
			places.Increase = Math.Min(Math.Max(0, places.MaxCount - places.Count), places.Increase + places.Capacity);
			Refresh();
		}

		private void DecreaseCount(StadiumPlaces places)
		{
			places.Increase = Math.Max(-places.Count, places.Increase - places.Capacity);
			Refresh();
		}

		private void Refresh()
		{
			IsBuildEnabled = _places.Values.Any((StadiumPlaces x) => x.Increase != 0);
			base.Profit = string.Format("{0:N0}{1}", _places.Values.Sum((StadiumPlaces x) => x.Income * (decimal)x.Current), "€");
			decimal num = _places.Values.Sum((StadiumPlaces x) => x.Income * (decimal)x.Increase);
			base.ProfitIncrease = num.ToSignedString("€");
			IsProfitIncreaseGood = num > 0m;
			base.Cost = string.Format("{0:N0}{1}", _places.Values.Sum((StadiumPlaces x) => x.Outcome * (decimal)x.Current), "€");
			decimal num2 = _places.Values.Sum((StadiumPlaces x) => x.Outcome * (decimal)x.Increase);
			base.CostIncrease = num2.ToSignedString("€");
			IsCostsIncreaseGood = num2 < 0m;
			base.EuroPrice = (int)_places.Values.Sum((StadiumPlaces x) => (decimal)Math.Max(0, x.Increase) * x.Price);
			base.PremiumPrice = (int)_places.Values.Sum((StadiumPlaces x) => (decimal)Math.Max(0, x.Increase) * x.PricePremium);
			OnPropertyChanged("BuildTitle");
			RaisePlacesPropertiesChanged();
		}

		private void RaisePlacesPropertiesChanged()
		{
			OnPropertyChanged("Stands");
			OnPropertyChanged("Seats");
			OnPropertyChanged("Vips");
		}

		protected override void OnTimeChanged()
		{
			foreach (StadiumPlaces value in _places.Values)
			{
				value.SpeedupPrice = value.BuildingData.GetSpeedupPrice(base.SpeedupCost);
			}
			RaisePlacesPropertiesChanged();
		}

		protected override string GetPremiumBuildQuestion()
		{
			return string.Format("BuildingUpgradeStadiumQuestion".Translate(), base.PremiumPrice);
		}

		protected override async Task<ResponseStatus> OnBuild(bool premium)
		{
			List<StadiumPlacesOrder> list = new List<StadiumPlacesOrder>();
			foreach (Guid key in _places.Keys)
			{
				StadiumPlaces stadiumPlaces = _places[key];
				if (stadiumPlaces.Increase != 0)
				{
					list.Add(new StadiumPlacesOrder
					{
						Id = key,
						Count = stadiumPlaces.Increase
					});
				}
			}
			return (await base.StadiumService.BuildPlaces(list, premium)).Status;
		}
	}
	public class StadiumStatisticsViewModel : BaseViewModel
	{
		private List<StatisticsItem> _buildingsStatistics;

		private List<StatisticsItem> _stadiumStatistics;

		private readonly INewStadiumService _stadiumService;

		private readonly string _lastMatch = "LastMatch".Translate();

		private readonly string _average = "Average".Translate();

		private readonly string _total = "Total".Translate();

		private readonly string _level = "Level".Translate();

		public List<StatisticsItem> BuildingsStatistics
		{
			get
			{
				return _buildingsStatistics;
			}
			set
			{
				Set(ref _buildingsStatistics, value, "BuildingsStatistics");
			}
		}

		public List<StatisticsItem> StadiumStatistics
		{
			get
			{
				return _stadiumStatistics;
			}
			set
			{
				Set(ref _stadiumStatistics, value, "StadiumStatistics");
			}
		}

		public StadiumStatisticsViewModel(INewStadiumService stadiumService)
		{
			_stadiumService = stadiumService;
		}

		public override async Task Update()
		{
			base.Title = "Statistics".Translate();
			StadiumResponse stadiumResponse = await _stadiumService.GetStadium();
			Dictionary<Guid, BuildingData> buildings = stadiumResponse.Buildings.ToDictionary((BuildingData x) => x.Id);
			StadiumStatistics = new List<StatisticsItem>
			{
				new StatisticsItem("Audience".Translate(), -1L),
				new StatisticsItem(),
				new StatisticsItem(_lastMatch, stadiumResponse.VisitorsLastMatch),
				new StatisticsItem(_average, stadiumResponse.VisitorsAverage),
				new StatisticsItem(_total, stadiumResponse.VisitorsTotal),
				new StatisticsItem(),
				new StatisticsItem(),
				new StatisticsItem("AudienceEarnings".Translate(), -1L),
				new StatisticsItem(),
				new StatisticsItem(_lastMatch, stadiumResponse.EarningsLastMatch, isMoney: true),
				new StatisticsItem(_average, stadiumResponse.EarningsAverage, isMoney: true),
				new StatisticsItem(_total, stadiumResponse.EarningsTotal, isMoney: true)
			};
			List<StatisticsItem> list = new List<StatisticsItem>
			{
				new StatisticsItem(stadiumResponse.Name, -1L)
			};
			AddStadiumPlacesInfo(list, Guids.Building_StadiumStands, buildings);
			AddStadiumPlacesInfo(list, Guids.Building_StadiumSeats, buildings);
			AddStadiumPlacesInfo(list, Guids.Building_StadiumVips, buildings);
			BuildingData[] array = (from x in stadiumResponse.Buildings
				where x.Id != Guids.Building_StadiumStands && x.Id != Guids.Building_StadiumSeats && x.Id != Guids.Building_StadiumVips
				orderby x.Earnings descending, x.CurrentValue descending
				select x).ToArray();
			foreach (BuildingData buildingData in array)
			{
				AddBuildingInfo(list, buildingData.Id, buildings);
			}
			BuildingsStatistics = list;
		}

		private void AddStadiumPlacesInfo(List<StatisticsItem> list, Guid id, Dictionary<Guid, BuildingData> buildings)
		{
			if (buildings.TryGetValue(id, out var value))
			{
				list.Add(new StatisticsItem());
				list.Add(new StatisticsItem(value.Name, value.CurrentValue));
				list.Add(new StatisticsItem(_lastMatch, value.Earnings, isMoney: true));
			}
		}

		private void AddBuildingInfo(List<StatisticsItem> list, Guid id, Dictionary<Guid, BuildingData> buildings)
		{
			if (buildings.TryGetValue(id, out var value) && value.CurrentValue > 0)
			{
				list.Add(new StatisticsItem());
				list.Add(new StatisticsItem());
				list.Add(new StatisticsItem(value.Name, -1L));
				list.Add(new StatisticsItem(_level, value.CurrentValue));
				if (value.Earnings > 0)
				{
					list.Add(new StatisticsItem(_lastMatch, value.Earnings, isMoney: true));
				}
			}
		}
	}
