		public StadiumViewModel(INewStadiumService stadiumService, INavigationService navigationService, IPopupService popupService)
		{
			_stadiumService = stadiumService;
			_navigationService = navigationService;
			_popupService = popupService;
			InitBuildings();
			SelectBuildingCommand = new AsyncCommand<Building>(SelectBuilding);
			SelectedInProgressBuildingCommand = new AsyncCommand(SelectInProgressBuilding);
			SelectedBuilding = _buildingsCatalog[Guid.Empty];
			base.ShellViewModel.SetContextMenuImage(ScreenIdentifier.Stadium, 0, "menu_stadium");
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Stadium, 0, "StadiumRenameTitle".Translate(), new AsyncCommand(ChangeName));
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Stadium, 0, "StadiumRenewGrass".Translate(), new AsyncCommand(RenewGrass));
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Stadium, 0, "Statistics".Translate(), new Command(OpenStatistics));
		}

		private async Task RenewGrass()
		{
			if (_stadium != null)
			{
				RenewGrassPopupViewModel grass = new RenewGrassPopupViewModel
				{
					ImageName = _buildingsCatalog[Guid.Empty].CurrentImageName,
					Quality = _stadium.GrassQuality,
					Price = _stadium.RenewGrassCost
				};
				await _popupService.ShowPopupAsync(grass);
				_stadium.GrassQuality = (int)grass.Quality;
				if (_stadium.GrassQuality == 100)
				{
					_stadium.RenewGrassCost = 0;
				}
			}
		}

		private async Task ChangeName()
		{
			EntryPopupViewModel entry = new EntryPopupViewModel
			{
				Title = "StadiumRenameTitle".Translate(),
				Message = "StadiumRenameMessage".Translate(),
				ConfirmButtonTitle = "Change".Translate(),
				IsButtonPremium = true,
				PriceValue = _stadium.ChangeNameCost
			};
			if (await _popupService.ShowPopupAsync(entry) == PopupResult.Done && await base.ResourceService.SpentGTStars(entry.PriceValue, "StadiumRenameTitle".Translate(), string.Format("StadiumRenameQuestion".Translate(), entry.EnteredText, entry.PriceValue)))
			{
				if ((await _stadiumService.RenameStadium(entry.EnteredText)).Status == ResponseStatus.OK)
				{
					_stadium.Name = entry.EnteredText;
				}
				else
				{
					await base.ResourceService.UpdateAsync();
				}
			}
		}

		public override async Task Update()
		{
			base.Title = "Stadium".Translate();
			StopTimer();
			_stadium = await _stadiumService.GetStadium();
			UpdateStadium();
		}

		private void UpdateStadium()
		{
			_buildingsCatalog.TryGetValue(Guid.Empty, out var value);
			DateTime dateTime = default(DateTime);
			_totalBuildSeconds = 0.0;
			value.Subproperties.Clear();
			value.Level = 0;
			value.CurrentMaxLevel = 0;
			value.MaxLevel = 130000;
			value.IsUnderConstruction = false;
			foreach (BuildingData building in _stadium.Buildings)
			{
				Building value2;
				if (building.Id == Guids.Building_StadiumStands || building.Id == Guids.Building_StadiumSeats || building.Id == Guids.Building_StadiumVips)
				{
					value.Subproperties.Add(building);
					value.Level += building.CurrentValue;
					value.CurrentMaxLevel += building.MaxValue;
					value.IsUnderConstruction |= building.IsUnderConstruction;
					if (building.IsUnderConstruction)
					{
						if (dateTime < building.BuildEndValue)
						{
							dateTime = building.BuildEndValue;
						}
						_totalBuildSeconds += building.TotalBuildSeconds;
					}
				}
				else if (_buildingsCatalog.TryGetValue(building.Id, out value2))
				{
					value2.Data = building;
					value2.Level = building.CurrentValue;
					value2.IsUnderConstruction = building.IsUnderConstruction;
					value2.MaxLevel = building.MaxValue;
					value2.CurrentMaxLevel = building.MaxValue;
					value2.HasWarning = building.HasWarning;
					if (building.IsUnderConstruction)
					{
						dateTime = building.BuildEndValue;
						_totalBuildSeconds = building.TotalBuildSeconds;
						ConstructedBuildingName = building.Name;
					}
				}
			}
			if (value.IsUnderConstruction)
			{
				ConstructedBuildingName = _stadium.Name;
			}
			Buildings = Buildings.ToList();
			SetEndDate(dateTime);
			IsBuildInProgress = dateTime > DateTime.UtcNow;
			NotificationHelper.Instance.UpdateStadium(ConstructedBuildingName, dateTime);
		}

		protected override void OnTimerRefresh(TimeSpan timeLeft, bool isFinished)
		{
			IsBuildInProgress = !isFinished;
			if (_totalBuildSeconds > 0.0)
			{
				BuildProgress = (decimal)Math.Max(0.0, (_totalBuildSeconds - timeLeft.TotalSeconds) / _totalBuildSeconds * 100.0);
			}
			else
			{
				BuildProgress = 100m;
			}
			if (isFinished)
			{
				Update().FireAndForgetSafeAsync();
			}
		}

		private void OpenStatistics()
		{
			_navigationService.NavigateTo(ScreenIdentifier.Stadium_Statistics);
		}

		private async Task SelectInProgressBuilding()
		{
			Building building = Buildings.FirstOrDefault((Building x) => x.IsUnderConstruction);
			if (building != null)
			{
				await SelectBuilding(building);
			}
		}

		private async Task SelectBuilding(Building building)
		{
			SelectedBuilding = building;
			await Task.Delay(100);
			PopupResult popupResult;
			if (building.Id == Guid.Empty)
			{
				StadiumPopupViewModel popupViewModel = new StadiumPopupViewModel(_stadium.Name, building, IsBuildInProgress, _stadium.SpeedupCost);
				popupResult = await _popupService.ShowPopupAsync(popupViewModel);
			}
			else
			{
				BuildingPopupViewModel popupViewModel2 = new BuildingPopupViewModel(building, IsBuildInProgress, _stadium.SpeedupCost);
				popupResult = await _popupService.ShowPopupAsync(popupViewModel2);
			}
			if (popupResult == PopupResult.Done)
			{
				base.IsBusy = true;
				await Update();
				base.IsBusy = false;
			}
		}

