	public class PlayerRow : TableRow
	{
		private bool _isOnField;

		public SquadPlayerData Player { get; }

		public bool IsOnField
		{
			get
			{
				return _isOnField;
			}
			set
			{
				_isOnField = value;
				(base.Cells[0] as AvatarCell).AvatarVisible = !_isOnField;
				(base.Cells[1] as PlayerInfoCell).NameColor = (_isOnField ? TableCellColor.Accent : TableCellColor.Default);
			}
		}

		public PlayerRow(SquadPlayerData player, string shirtName, bool showShirt)
			: base(new AvatarCell(player.Country, player.Head, player.ID), new PlayerInfoCell(player.Name, player.Strength, player.YellowCards, player.HasRedCard, player.Injured, player.IsForSale, shirtName, player.Shirt, showShirt))
		{
			Player = player;
			UpdateBackground();
		}

		public static List<ITableRow> GetPlayersTableRows<T>(IEnumerable<T> players, Action<PlayerRow, T> setup, string shirtName, bool orderPlayers, bool showShirt) where T : SquadPlayerData
		{
			string text = string.Empty;
			List<ITableRow> list = new List<ITableRow>();
			IEnumerable<T> enumerable;
			if (!orderPlayers)
			{
				enumerable = players;
			}
			else
			{
				IEnumerable<T> enumerable2 = from x in players
					orderby x.GetPositionOrder(), x.Strength descending
					select x;
				enumerable = enumerable2;
			}
			foreach (T item in enumerable)
			{
				string shortPositionName = item.GetShortPositionName();
				if (text != shortPositionName)
				{
					text = shortPositionName;
					list.Add(new SectionRow
					{
						Name = shortPositionName
					});
				}
				PlayerRow playerRow = new PlayerRow(item, shirtName, showShirt);
				setup?.Invoke(playerRow, item);
				list.Add(playerRow);
			}
			return list;
		}

		public void SetCountry(string country)
		{
			(base.Cells[0] as AvatarCell).CountryCode = country;
		}

		public void SetName(string name)
		{
			(base.Cells[1] as PlayerInfoCell).Name = name;
		}

		public void SetInjured(int value)
		{
			(base.Cells[1] as PlayerInfoCell).Injured = value;
		}

		public void SetShirtNumber(int number)
		{
			(base.Cells[1] as PlayerInfoCell).ShirtNumber = number;
		}

		public void SetStrength(decimal strength)
		{
			(base.Cells[1] as PlayerInfoCell).Strength = strength;
		}

		public void SetSellStatus(bool isForSale)
		{
			(base.Cells[1] as PlayerInfoCell).IsForSale = isForSale;
		}

		public void UpdateBackground()
		{
			base.Background = ((Player.EndDateValue < DateTime.UtcNow) ? TableRowBackground.Warning : TableRowBackground.Default);
		}
	}
