		public string NoPlayersMessage => "NoIndividualTraining".Translate();

		public IndividualTrainingViewModel()
		{
			NextPlayerCommand = new Command(SelectNextPlayer);
			TrainCommand = new AsyncCommand<bool>(Train);
			RenewCommand = new AsyncCommand<TrainingPlayerData>(Renew);
			RenewAllCommand = new AsyncCommand(RenewAll);
			RemoveCommand = new AsyncCommand<TrainingPlayerData>(Remove);
			base.ShellViewModel.SetContextMenuImage(ScreenIdentifier.Training, 3, "menu_training");
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Training, 3, "RenewAll".Translate(), RenewAllCommand);
		}

		public override Task Init()
		{
			return Update();
		}

		public void UpdateData(IndividualTrainingData data)
		{
			FreePlayers = null;
			TrainedPlayers = null;
			SelectedPlayer = null;
			TrainPrice = data.TrainPrice;
			RenewPrice = data.RenewPrice;
			RenewAllPrice = data.RenewAllPrice;
			IsRenewAllEnabled = RenewAllPrice > 0;
			_allTrainedPlayers = null;
			_ = DateTime.UtcNow;
			if (data.Players != null)
			{
				FreePlayers = (from x in data.Players
					where x.IsFree
					orderby x.GetPositionOrder(), x.Strength descending
					select x).ToArray();
				FreePlayersItems = FreePlayers.ToComboBoxItems();
				_allTrainedPlayers = data.Players.Where((TrainingPlayerData x) => !FreePlayers.Contains(x)).ToArray();
				TrainedPlayers = (from x in _allTrainedPlayers
					orderby x.Position, x.Strength descending
					group x by x.GetPositionName()).ToArray();
				TrainedPlayersList = (from x in _allTrainedPlayers
					orderby x.Position, x.Strength descending
					select x).Select(GetRow).ToList();
				if (_trainingService.PlayerId != Guid.Empty)
				{
					SelectedPlayer = FreePlayers.FirstOrDefault((TrainingPlayerData x) => x.ID == _trainingService.PlayerId);
				}
				if (SelectedPlayer == null)
				{
					SelectedPlayer = ((FreePlayers.Length != 0) ? FreePlayers[0] : null);
				}
				if (_allTrainedPlayers.Length != 0)
				{
					SetEndDate(_allTrainedPlayers.Max((TrainingPlayerData x) => x.EndDateValue));
				}
			}
			else
			{
				FreePlayersItems = null;
				TrainedPlayersList = null;
			}
		}

		private ITableRow GetRow(TrainingPlayerData player)
		{
			DateTime endDate = player.EndDate.ParseToDate();
			return new TableRow(new AvatarCell(player.Country, player.Head), new PlayerInfoCell(player.Name, player.Strength, 0, hasRedCard: false, 0, isForSale: false, null, -1, showShirt: false, showStrengthNumber: false), new TitleSubtitleCell(player.GetShortPositionName(), (player.TotalChange > 0m) ? $"+{player.SkillChange:N2} ({player.TotalChange:N2})" : "Waiting".Translate()), new ButtonTimerCell(endDate)
			{
				Value = RenewPrice,
				Text = "Renew".Translate(),
				ButtonType = ButtonType.Premium,
				Command = RenewCommand,
				CommandParameter = player
			}, new DeclineButtonCell(RemoveCommand, player))
			{
				Background = ((!player.HasContract) ? TableRowBackground.Warning : TableRowBackground.Default)
			};
		}

		private TrainingPlayerData[] GetPlayersToRenew()
		{
			if (_allTrainedPlayers == null || _allTrainedPlayers.Length == 0)
			{
				return new TrainingPlayerData[0];
			}
			DateTime nowDate = DateTime.UtcNow;
			return _allTrainedPlayers.Where((TrainingPlayerData x) => x.HasContract && x.EndDateValue < nowDate).ToArray();
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (propertyName == "SelectedPlayer")
			{
				IsTrainButtonEnabled = SelectedPlayer != null;
				SelectedSkillIndex = SelectedPlayer?.GetMainSkillIndex() ?? 0;
				SelectedSkillName = SkillsItems[SelectedSkillIndex].Text;
				TrainingPlayerData selectedPlayer = SelectedPlayer;
				SelectedSkillValue = ((selectedPlayer != null) ? selectedPlayer.Skills[SelectedSkillIndex] : 0m);
			}
		}

		private void SelectNextPlayer()
		{
			if (FreePlayers != null && FreePlayers.Length >= 2)
			{
				int num = Array.IndexOf(FreePlayers, SelectedPlayer);
				num++;
				if (num >= FreePlayers.Length)
				{
					num = 0;
				}
				SelectedPlayer = FreePlayers[num];
			}
		}

		private async Task Train(bool skipConfirmation)
		{
			if (SelectedPlayer == null)
			{
				return;
			}
			if (!SelectedPlayer.HasContract && !TutorialManager.Instance.InProgress)
			{
				await base.PopupService.ShowOkMessageAsync("NoValidContract".Translate(), "ContractHasExpired".Translate());
				return;
			}
			string question = (skipConfirmation ? null : string.Format("AddIndividualTrainingQuestion".Translate(), SelectedPlayer.Name, TrainPrice));
			if (await base.ResourceService.SpentGTStars(TrainPrice, "IndividualTraining".Translate(), question))
			{
				base.IsBusy = true;
				IndividualTrainingInfo training = new IndividualTrainingInfo
				{
					PlayerID = SelectedPlayer.ID,
					SkillIndex = SelectedSkillIndex
				};
				UpdateData(await _trainingService.StartIndividualTraining(training));
				base.IsBusy = false;
			}
		}

		private async Task Renew(TrainingPlayerData player)
		{
			if (!player.HasContract)
			{
				await base.PopupService.ShowOkMessageAsync("NoValidContract".Translate(), "ContractHasExpired".Translate());
			}
			else if (await base.ResourceService.SpentGTStars(RenewPrice, "RenewIndividualTrainingQuestionTitle".Translate(), string.Format("RenewIndividualTrainingQuestion".Translate(), player.Name, RenewPrice)))
			{
				base.IsBusy = true;
				IndividualTrainingInfo training = new IndividualTrainingInfo
				{
					PlayerID = player.ID
				};
				UpdateData(await _trainingService.RenewIndividualTraining(training));
				base.IsBusy = false;
			}
		}

		private async Task RenewAll()
		{
			TrainingPlayerData[] playersToRenew = GetPlayersToRenew();
			if (RenewAllPrice == 0 || playersToRenew.Length == 0)
			{
				await base.PopupService.ShowOkMessageAsync("RenewAll".Translate(), "RenewAllNoPlayersMessage".Translate());
			}
			else if (await base.ResourceService.SpentGTStars(RenewAllPrice, "RenewIndividualTrainingQuestionTitle".Translate(), string.Format("RenewAllIndividualTrainingsQuestion".Translate(), RenewAllPrice)))
			{
				base.IsBusy = true;
				UpdateData(await _trainingService.RenewAllIndividualTrainings());
				base.IsBusy = false;
			}
		}

		private async Task Remove(TrainingPlayerData player)
		{
			if (await base.PopupService.ShowYesNoMessageAsync("RemoveIndividualHeadline".Translate(), string.Format("RemoveIndividualMessage".Translate(), player.Name)))
			{
				base.IsBusy = true;
				IndividualTrainingInfo training = new IndividualTrainingInfo
				{
					PlayerID = player.ID
				};
				UpdateData(await _trainingService.CancelIndividualTraining(training));
				base.IsBusy = false;
			}
		}
	}
