		public void UpdateData(TacticTrainingData data)
		{
			_data = data;
			Dictionary<Guid, TacticBonus> dictionary = _data.TacticBonusList.ToDictionary((TacticBonus x) => x.Tactic.ID);
			TacticBonus[] tacticBonusList = _data.TacticBonusList;
			for (int num = 0; num < tacticBonusList.Length; num++)
			{
				CounterTactic[] counterTactics = tacticBonusList[num].CounterTactics;
				foreach (CounterTactic counterTactic in counterTactics)
				{
					if (dictionary.TryGetValue(counterTactic.TacticId, out var value))
					{
						counterTactic.TacticName = value.Tactic.Name;
					}
				}
			}
			TacticsList = _data.TacticBonusList.Select((TacticBonus x) => x.Tactic).ToArray();
			TacticsItems = TacticsList.ToComboBoxItems((TacticData x) => x.Name);
			TacticBonusList = _data.TacticBonusList;
			SelectedTactic = TacticsList.FirstOrDefault((TacticData x) => x.ID == _data.SelectedTacticId);
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			if (propertyName == "SelectedTactic" && SelectedTactic != null && _data != null && TacticBonusList != null)
			{
				IsSaveEnabled = SelectedTactic.ID != _data.SelectedTacticId;
				SelectedBonusList = TacticBonusList.FirstOrDefault((TacticBonus x) => x.Tactic.ID == SelectedTactic.ID)?.CounterTactics;
			}
		}

		private async Task OpenTacticsPopup()
		{
			SelectionPopupViewModel selection = new SelectionPopupViewModel
			{
				Title = "Tactics",
				SelectionItems = TacticsList.Select((TacticData x) => new SelectionPopupItem
				{
					Text = x.Name,
					ImageName = $"tactic{Array.IndexOf(TacticsList, x)}"
				}).ToArray()
			};
			if (await _popupService.ShowPopupAsync(selection) == PopupResult.Done)
			{
				SelectedTactic = TacticsList[selection.SelectedIndex];
			}
		}

		private async Task Save()
		{
			base.IsBusy = true;
			IsSaveEnabled = false;
			IsSavingInProgress = true;
			UpdateData(await _trainingService.SaveTacticTraining(SelectedTactic));
			IsSavingInProgress = false;
			base.IsBusy = false;
		}
	}
