			EfficiencyText = data.EfficiencyText;
			EfficiencyValue = data.EfficiencyValue;
			UpdateStatus();
		}

		private void UpdateStatus()
		{
			if (_data.NoTraining)
			{
				TeamTrainingStatus = TeamTrainingStatus.NoTraining;
				return;
			}
			TeamTrainingStatus = ((_data.EfficiencyValue == 100) ? TeamTrainingStatus.EffectiveTraining : TeamTrainingStatus.IneffectiveTraining);
			SetEndDate(_data.BoringDateValue);
		}

		private async Task Save()
		{
			base.IsBusy = true;
			IsSaveEnabled = false;
			IsSavingInProgress = true;
			TeamTrainingInfo settings = new TeamTrainingInfo
			{
				MainSkillIndex = MainSkillIndex,
				SubSkillIndex = SubSkillIndex
			};
			UpdateData(await _trainingService.SaveTeamTraining(settings));
			IsSavingInProgress = false;
			base.IsBusy = false;
		}

		private async Task OpenMainSkillPopup()
		{
			SelectionPopupViewModel selection = GetSkillSelectionPopup("MainSkill".Translate(), MainSkills);
			if (await _popupService.ShowPopupAsync(selection) == PopupResult.Done)
			{
				MainSkillIndex = selection.SelectedIndex;
			}
		}

		private async Task OpenSubSkillPopup()
		{
			SelectionPopupViewModel selection = GetSkillSelectionPopup("SubSkill".Translate(), SubSkills, 4);
			if (await _popupService.ShowPopupAsync(selection) == PopupResult.Done)
			{
				SubSkillIndex = selection.SelectedIndex;
			}
		}

		private SelectionPopupViewModel GetSkillSelectionPopup(string title, List<ComboBoxItem> skills, int modificator = 0)
		{
			return new SelectionPopupViewModel
			{
				IsCloseButtonHidden = TutorialManager.Instance.InProgress,
				Title = title,
				SelectionItems = skills.Select((ComboBoxItem x) => new SelectionPopupItem
				{
					Text = x.Text,
					ImageName = $"skill{skills.IndexOf(x) + modificator}"
				}).ToArray()
			};
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			switch (propertyName)
			{
			case "MainSkillIndex":
			case "SubSkillIndex":
				if (_data != null)
				{
					IsSaveEnabled = _data.NoTraining || MainSkillIndex != _data.MainSkillIndex || SubSkillIndex != _data.SubSkillIndex || _forceSaveEnabled;
				}
				else
				{
					IsSaveEnabled = _forceSaveEnabled;
				}
				MainSkillName = MainSkills[MainSkillIndex].Text;
				SubSkillName = SubSkills[SubSkillIndex].Text;
				break;
			case "TimeLeft":
				DecreaseIn = base.TimeLeft.ToLocalizedString(onlyDays: true);
				if (base.TimeLeft.TotalHours > 36.0)
				{
					DecreaseStatus = GeneralStatus.OK;
				}
				else if (base.TimeLeft.TotalHours > 24.0)
				{
					DecreaseStatus = GeneralStatus.Warning;
				}
				else
				{
					DecreaseStatus = GeneralStatus.Critical;
				}
				break;
			}
		}

		public void SetForceSaveEnabled(bool value)
		{
			_forceSaveEnabled = value;
			if (_forceSaveEnabled)
			{
				IsSaveEnabled = true;
			}
		}
	}
