			}
		}

		public ICommand BookCommand { get; }

		public ICommand CancelCommand { get; }

		public ICommand UpdateCommand { get; }

		public TrainingCampViewModel()
		{
			BookCommand = new AsyncCommand<TrainingCampBookParameter>(BookCamp);
			CancelCommand = new AsyncCommand(CancelCamp);
			UpdateCommand = new AsyncCommand(UpdateCamps);
			base.ShellViewModel.SetContextMenuImage(ScreenIdentifier.Training, 2, "menu_training");
			base.ShellViewModel.AddContextMenuItem(ScreenIdentifier.Training, 2, "Update".Translate(), UpdateCommand);
		}

		public override Task Init()
		{
			return Update();
		}

		public void UpdateData(TrainingCampData data)
		{
			UpdateCampsCost = data.UpdateCampsCost;
			CampItems = data.CampItems?.OrderBy((TrainingCampItem x) => x.Identifier).ToArray();
			IsUpdateEnabled = data.IsUpdateEnabled;
			StopTimer();
			_ = DateTime.UtcNow;
			DateTime[] array = (from x in CampItems
				where x.IsBooked
				select x.BookDateValue).ToArray();
			bool isBookEnabled = true;
			if (array.Length != 0)
			{
				DateTime endDate = array.Min();
				SetEndDate(endDate);
				if (base.TimeLeft > TimeSpan.Zero)
				{
					isBookEnabled = false;
				}
			}
			IsBookEnabled = isBookEnabled;
			BookedCampIndex = Array.IndexOf<TrainingCampItem>(CampItems, CampItems.FirstOrDefault((TrainingCampItem x) => x.IsBooked));
			Log.Info($"Camp Booked Index = {BookedCampIndex}");
		}

		private async Task BookCamp(TrainingCampBookParameter parameter)
		{
			TrainingCampItem campItem = CampItems[parameter.CampIndex];
			int value = (parameter.IsPremium ? campItem.PriceStars : campItem.PriceEuro);
			if (await base.ResourceService.Spent(value, parameter.IsPremium, "Book".Translate(), string.Format("BookTrainingCampQuestion".Translate(), campItem.PriceStars)))
			{
				base.IsBusy = true;
				TrainingCampBookInfo bookInfo = new TrainingCampBookInfo
				{
					Identifier = campItem.Identifier,
					PremiumBooking = parameter.IsPremium
				};
				UpdateData(await _trainingService.BookCamp(bookInfo));
				base.IsBusy = false;
			}
		}

		private async Task CancelCamp()
		{
			base.IsBusy = true;
			UpdateData(await _trainingService.CancelCamp());
			base.IsBusy = false;
		}

		private async Task UpdateCamps()
		{
			if (await base.ResourceService.SpentGTStars(UpdateCampsCost, "Update".Translate(), string.Format("UpdateCampsQuestion".Translate(), UpdateCampsCost)))
			{
				base.IsBusy = true;
				UpdateData(await _trainingService.UpdateCamps());
				base.IsBusy = false;
			}
		}
	}
