		public TrainingViewModel(ITrainingService trainingService)
		{
			_trainingService = trainingService;
			_teamTraining = ComponentFactory.Resolve<TeamTrainingViewModel>();
			_trainingCamp = ComponentFactory.Resolve<TrainingCampViewModel>();
			_tacticTraining = ComponentFactory.Resolve<TacticTrainingViewModel>();
			_individualTraining = ComponentFactory.Resolve<IndividualTrainingViewModel>();
			base.ShellViewModel.SetCharacter(ScreenIdentifier.Training, 0, "characters_coach");
			base.ShellViewModel.SetCharacter(ScreenIdentifier.Training, 1, "characters_coach");
			base.ShellViewModel.SetCharacter(ScreenIdentifier.Training, 2, "characters_coach");
		}

		public override void ApplyBinding()
		{
			base.ApplyBinding();
			_teamTraining.ApplyBinding();
			_trainingCamp.ApplyBinding();
			_tacticTraining.ApplyBinding();
			_individualTraining.ApplyBinding();
		}

		public override async Task Update()
		{
			base.Title = "Training".Translate();
			TrainingData trainingData = await _trainingService.GetTraining();
			_teamTraining.UpdateData(trainingData.TeamTraining);
			_tacticTraining.UpdateData(trainingData.TacticTraining);
			_trainingCamp.UpdateData(trainingData.TrainingCamp);
			_individualTraining.UpdateData(trainingData.IndividualTraining);
		}
	}
