		public AuctionViewModel(IMyTransfermarketService myTransfermarketService, ITransfermarketBidService transfermarketBidService, ILocalNotificationService localNotificationService)
		{
			BidCommand = new AsyncCommand(MakeBid);
			FavoriteCommand = new AsyncCommand(AddRemoveFavorite);
			_myTransfermarketService = myTransfermarketService;
			_transfermarketBidService = transfermarketBidService;
			_localNotificationService = localNotificationService;
			_transfermarketBidService.BidUpdated += OnBidUpdated;
			_transferMarketViewModel = ComponentFactory.Resolve<TransferMarketViewModel>();
			IsBidButtonEnabled = true;
		}

		private void OnBidUpdated(object sender, TransfermarketBidEventArgs e)
		{
			if (e.BidInfo != null && Player != null && !(Player.AuctionID != e.BidInfo.AuctionID))
			{
				Player.Bid = e.BidInfo.Bid;
				Player.BidTeamID = e.BidInfo.BidTeamId;
				Player.BidTeamLogo = e.BidInfo.BidTeamLogo;
				Player.BidTeamName = e.BidInfo.BidTeamName;
				Player.BidIncrement = e.BidInfo.BidIncrement;
				Player.EndDate = e.BidInfo.EndDate;
				UpdateServiceProperties(Player);
				NewBidInfo = e.BidInfo;
				BidDifference = 0m;
				BidDifference = e.BidInfo.Bid - Bid;
				Bid = e.BidInfo.Bid;
				BidIncrement = e.BidInfo.BidIncrement;
				BidTeamName = e.BidInfo.BidTeamName;
				BidTeamLogo = e.BidInfo.BidTeamLogo;
				HasBid = true;
				UpdateBidAvailability().FireAndForgetSafeAsync();
			}
		}

		public override async Task Update()
		{
			Guid selectedAuctionId = _transferMarketViewModel.SelectedAuctionId;
			base.IsBusy = true;
			TransfermarketDetailsResponse transfermarketDetailsResponse = await _myTransfermarketService.GetDetails(selectedAuctionId);
			_myTeamId = transfermarketDetailsResponse.MyTeamId;
			BidCost = transfermarketDetailsResponse.BidCost;
			SetPlayer(transfermarketDetailsResponse.Player);
			AuctionPlayer = transfermarketDetailsResponse.AuctionPlayer;
			Skills = transfermarketDetailsResponse.AuctionPlayer.GetSkillDetails();
			await UpdateBidAvailability();
			BidDifference = 0m;
			Bid = AuctionPlayer.Bid;
			BidIncrement = AuctionPlayer.BidIncrement;
			BidTeamName = AuctionPlayer.BidTeamName ?? "NoBidsText".Translate();
			HasBid = !string.IsNullOrEmpty(AuctionPlayer.BidTeamName);
			BidTeamLogo = AuctionPlayer.BidTeamLogo;
			Seller = AuctionPlayer.OfferTeamName ?? "GTAssociation".Translate();
			base.IsBusy = false;
		}

		private async Task UpdateBidAvailability()
		{
			if (Player != null)
			{
				await base.ResourceService.UpdateAsync();
				CanMakeBid = (decimal)base.ResourceService.Money >= Player.Bid + Player.BidIncrement;
				IsBidButtonEnabled = CanMakeBid;
			}
		}

		private void SetPlayer(JsonExtendedPlayer player)
		{
			UpdateServiceProperties(player);
			Player = player;
		}

		private void UpdateServiceProperties(JsonExtendedPlayer player)
		{
			if (player != null)
			{
				IsMyBid = player.BidTeamID == _myTeamId;
				IsBidEnabled = player.OfferTeamID != _myTeamId;
				IsFavorite = player.IsFavorite;
				if (player.IsFrozen)
				{
					IsAuctionFinished = false;
					base.TimeLeft = TimeSpan.FromSeconds(10.0);
				}
				else
				{
					DateTime dateTime = player.EndDate.ParseToDate();
					IsAuctionFinished = dateTime <= DateTime.UtcNow;
					SetEndDate(dateTime);
				}
			}
		}

		protected override void OnTimerRefresh(TimeSpan timeLeft, bool isFininshed)
		{
			base.OnTimerRefresh(timeLeft, isFininshed);
			if (isFininshed)
			{
				IsAuctionFinished = true;
			}
		}

		private async Task MakeBid()
		{
			if (Player == null)
			{
				return;
			}
			IsBidButtonEnabled = false;
			if (await base.ResourceService.CheckGTStars(BidCost))
			{
				ResponseObject responseObject = await _myTransfermarketService.PlaceBid(Player.AuctionID);
				if (responseObject.Status != ResponseStatus.OK && !string.IsNullOrEmpty(responseObject.ErrorMessage))
				{
					base.PopupService.ShowOkMessage(responseObject.ErrorMessage, Character.Scout);
				}
				else
				{
					base.ResourceService.Update();
					AddNotifications();
				}
			}
			IsBidButtonEnabled = true;
		}

		private void AddNotifications()
		{
			if ((Player.EndDate.ParseToDate() - DateTime.UtcNow).TotalMinutes > 5.0)
			{
				_localNotificationService.AddTransfermarket(Player);
				NotificationHelper.Instance.AddTransfermarket(new TransfermarketPlayerData
				{
					ID = Player.ID,
					Name = Player.CurrentName,
					EndDate = Player.EndDate
				});
			}
		}

		private async Task AddRemoveFavorite()
		{
			if (Player != null)
			{
				base.IsBusy = true;
				if (IsFavorite)
				{
					await _myTransfermarketService.RemoveFavorite(Player.AuctionID);
					_localNotificationService.RemoveTransfermarket(Player);
				}
				else
				{
					await _myTransfermarketService.AddFavorite(Player.AuctionID);
					AddNotifications();
				}
				IsFavorite = !IsFavorite;
				base.IsBusy = false;
			}
		}
	}
