		private void OnBidUpdated(object sender, TransfermarketBidEventArgs e)
		{
			if (e.BidInfo != null)
			{
				NewPlayerData = new TransfermarketPlayerData
				{
					AuctionId = e.BidInfo.AuctionID,
					Bid = e.BidInfo.Bid,
					BidTeamName = e.BidInfo.BidTeamName,
					BidTeamLogo = e.BidInfo.BidTeamLogo,
					EndDate = e.BidInfo.EndDate
				};
				if (ListUpdated(PlayersList, e.BidInfo))
				{
					PlayersList = PlayersList.ToList();
				}
				if (ListUpdated(FavoritesList, e.BidInfo))
				{
					FavoritesList = FavoritesList.ToList();
				}
				if (ListUpdated(SellingsList, e.BidInfo))
				{
					SellingsList = SellingsList.ToList();
				}
			}
		}

		private bool ListUpdated(List<TransfermarketPlayerData> list, JsonRealtimeBid bidInfo)
		{
			if (list == null || bidInfo == null)
			{
				return false;
			}
			TransfermarketPlayerData transfermarketPlayerData = list.FirstOrDefault((TransfermarketPlayerData x) => x.AuctionId == bidInfo.AuctionID);
			if (transfermarketPlayerData == null)
			{
				return false;
			}
			transfermarketPlayerData.Bid = bidInfo.Bid;
			transfermarketPlayerData.BidTeamName = bidInfo.BidTeamName;
			transfermarketPlayerData.BidTeamLogo = bidInfo.BidTeamLogo;
			transfermarketPlayerData.EndDate = bidInfo.EndDate;
			return true;
		}

		private List<ITableRow> CreateTable(List<TransfermarketPlayerData> playerData)
		{
			if (playerData == null || playerData.Count == 0)
			{
				return new List<ITableRow>();
			}
			string tutorialControlId = "transfermarket_row";
			List<ITableRow> list = new List<ITableRow>();
			foreach (TransfermarketPlayerData playerDatum in playerData)
			{
				list.Add(new TableRow(new AvatarCell(playerDatum.Country, playerDatum.Head), new NameBidCell(playerDatum.Name, playerDatum.Bid, playerDatum.BidTeamName), new TextCell(playerDatum.Age.ToString(), TableCellAlignment.Center, (playerDatum.Age >= 34) ? TableCellColor.Negative : TableCellColor.Default), new TextCell(playerDatum.Talent.ToString(), TableCellAlignment.Center, (playerDatum.Talent > 8) ? TableCellColor.Highlight : TableCellColor.Default), new TextCell(playerDatum.GetShortPositionName(), TableCellAlignment.Center, TableCellColor.Accent), new StrengthCell(playerDatum.Strength), new TimerCell(playerDatum.EndDate)
				{
					Text = _auctionFinishedText
				})
				{
					Command = SelectCommand,
					CommandParameter = playerDatum,
					TutorialControlId = tutorialControlId
				});
				tutorialControlId = null;
			}
			return list;
		}

		public override async Task Update()
		{
			base.Title = "TransferMarket".Translate();
			Log.Info("TM - Update");
			await Task.WhenAll(_transfermarketBidService.Connect(), LoadData());
			TutorialManager.Instance.Continue();
		}

		protected override void OnTimerRefresh(TimeSpan timeLeft, bool isFininshed)
		{
			base.OnTimerRefresh(timeLeft, isFininshed);
			if (isFininshed && !TutorialManager.Instance.InProgress)
			{
				Log.Info("TM - On timer refresh");
				LoadData().FireAndForgetSafeAsync();
			}
		}

		private async Task LoadData()
		{
			base.IsBusy = true;
			Log.Info("TM - Load data");
			SelectedAuctionId = default(Guid);
			TransfermarketInfo request = new TransfermarketInfo
			{
				Strength = GetRequestCriteria(SelectedStrengthMin, SelectedStrengthMax, 1, 101),
				Age = GetRequestCriteria(SelectedAgeMin, SelectedAgeMax, 16, 34),
				Talent = GetRequestCriteria(SelectedTalentMin, SelectedTalentMax, 1, 10),
				Skill = GetRequestCriteria(SelectedSkillMin, SelectedSkillMax, 1, 101),
				SkillIndex = SkillIndex,
				Budget = (IsBudgetLimited ? base.ResourceService.Money : 0)
			};
			TransfermarketData transfermarketData = await _myTransfermarketService.Search(request);
			if (transfermarketData.Players.Length != 0 && transfermarketData.Players[0].IsFrozen)
			{
				Log.Info("... TM tutorial case");
				transfermarketData.Players[0].EndDate = DateTime.UtcNow.AddSeconds(50.0).ToUtcString();
				IsTableLocked = true;
				StopTimer();
			}
			else
			{
				IsTableLocked = false;
				List<TransfermarketPlayerData> list = new List<TransfermarketPlayerData>();
				list.AddRange(transfermarketData.Players);
				list.AddRange(transfermarketData.Favorites);
				list.AddRange(transfermarketData.Sellings);
				if (list.Count > 0)
				{
					SetEndDate(list.Max((TransfermarketPlayerData x) => x.EndDateValue));
				}
			}
			PlayersList = transfermarketData.Players.ToList();
			FavoritesList = transfermarketData.Favorites.ToList();
			SellingsList = transfermarketData.Sellings.ToList();
			base.IsBusy = false;
		}

		private SearchCriteria GetRequestCriteria(double selectedMin, double selectedMax, int min, int max)
		{
			int num = selectedMin.ToInt();
			int num2 = selectedMax.ToInt();
			if (num == min && num2 == max)
			{
				return null;
			}
			return new SearchCriteria(num, (num2 == 101) ? 500 : num2);
		}

		private async Task Search()
		{
			await LoadData();
			SaveSearchProperties();
			SelectedTab = 0;
			_navigationService.MoveToTab(0);
		}

		private void Reset()
		{
			Log.Info("TM - RESET");
			SelectedAgeMin = 16.0;
			SelectedAgeMax = 34.0;
			SelectedTalentMin = 1.0;
			SelectedTalentMax = 10.0;
			SelectedStrengthMin = 1.0;
			SelectedStrengthMax = 101.0;
			SelectedSkillMin = 1.0;
			SelectedSkillMax = 101.0;
			SkillIndex = -1;
			SelectedPosition = 0;
			IsBudgetLimited = false;
			WasReset++;
		}

		private async Task ResetAndSearch()
		{
			Reset();
			await Search();
		}

		private void NavigateToSearch()
		{
			_navigationService.NavigateTo(ScreenIdentifier.Transfermarket, 1);
		}

		private void NavigateToResult()
		{
			_navigationService.NavigateTo(ScreenIdentifier.Transfermarket, 0);
		}

		private void NavigateToSquad()
		{
			_navigationService.NavigateTo(ScreenIdentifier.Squad, 3);
		}

		private void LoadSearchProperties()
		{
			string text = Preferences.Get("SearchProperties", string.Empty).Decompress();
			if (!string.IsNullOrEmpty(text))
			{
				try
				{
					TransfermarketSettings transfermarketSettings = JsonConvert.DeserializeObject<TransfermarketSettings>(text);
					transfermarketSettings.CopyPropertiesTo(this);
					LoadedSettings = transfermarketSettings;
					return;
				}
				catch (Exception ex)
				{
					AppAnalytics.Instance.TrackError(ex);
				}
			}
			Reset();
		}

		private void SaveSearchProperties()
		{
			TransfermarketSettings transfermarketSettings = new TransfermarketSettings();
			this.CopyPropertiesTo(transfermarketSettings);
			string text = JsonConvert.SerializeObject((object)transfermarketSettings).Compress();
			Preferences.Set("SearchProperties", text);
		}
	}
}
