		public string HomeTeamTrikot { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string AwayTeamTrikot { get; set; }

		public string HomeTeamLogoImageName => GetTeamLogoImageName(HomeTeamLogo, small: false);

		public string AwayTeamLogoImageName => GetTeamLogoImageName(AwayTeamLogo, small: false);

		public string HomeTeamLogoSmallImageName => GetTeamLogoImageName(HomeTeamLogo, small: true);

		public string AwayTeamLogoSmallImageName => GetTeamLogoImageName(AwayTeamLogo, small: true);

		private string GetTeamLogoImageName(string logo, bool small)
		{
			if (string.IsNullOrEmpty(logo))
			{
				logo = "wappen01";
			}
			return logo + (small ? "_small" : "_normal") + ".png";
		}
	}
	[DataContract]
	public class JsonExtendedPlayer : JsonPlayer
	{
		private string _shortName;

		[DataMember(EmitDefaultValue = false)]
		public Guid AuctionID { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal Bid { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal BidIncrement { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public decimal Offer { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public Guid OfferTeamID { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string EndDate { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public Guid BidTeamID { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string BidTeamName { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string OfferTeamName { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string OfferTeamTrikot { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string OfferTeamLogo { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool HasUpgrade { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public string BidTeamLogo { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public List<Guid> BonusSkills { get; set; }

		[DataMember(EmitDefaultValue = false)]
		public bool IsFavorite { get; set; }

		public string CurrentName
		{
			get
			{
				if (!string.IsNullOrEmpty(base.CustomName))
				{
					return base.CustomName;
				}
				return base.Name;
			}
		}

		public string ShortName => _shortName ?? (_shortName = (CurrentName.Trim().Contains(" ") ? CurrentName.Trim().Split(new char[1] { ' ' }).Last() : CurrentName));

		public bool IsInjured
		{
			get
			{
				if (base.Injured.HasValue)
				{
					return base.Injured > 0;
				}
				return false;
			}
		}

		public bool IsContractValid
		{
			get
			{
				ICoreHelperService coreHelperService = ComponentFactory.Resolve<ICoreHelperService>();
				return coreHelperService.ParseDate(base.ContractEnd).Value > coreHelperService.GetDate();
			}
		}

		public bool IsReadyToPlay(bool friendly, bool ladder)
		{
			if (!IsContractValid)
			{
				return false;
			}
			if (base.HasRedCard && !ladder && !friendly)
			{
				return false;
			}
			if (IsInjured && !ladder)
			{
				return false;
			}
			return true;
		}

		public SquadPlayerData GetPlayerData()
		{
			ICoreHelperService coreHelperService = ComponentFactory.Resolve<ICoreHelperService>();
			JsonCountry jsonCountry = coreHelperService.JsonDefinitions.Countries.FirstOrDefault((JsonCountry c) => c.ID.Equals(base.CountryID));
			Guid teamID = ((OfferTeamID != Guid.Empty) ? OfferTeamID : base.TeamID);
			string homeTrikot = coreHelperService.GetHomeTrikot(teamID);
			return new SquadPlayerData
			{
				Age = base.Age,
				Body = base.SkinBody,
				Country = jsonCountry.Short.ToLower(),
				EndDate = base.ContractEnd,
				Experience = base.Experience,
				Fitness = base.Form,
				Gloves = base.SkinGloves,
				HasRedCard = base.HasRedCard,
				Head = base.SkinHead,
				ID = base.ID,
				Injured = base.Injured.GetValueOrDefault(),
				IsForSale = base.IsForSale,
				IsUpgraded = base.Upgraded,
				MarketValue = base.MarketValue,
				MaxUpgradeStrength = base.MaxUpgradeStrength,
				Name = CurrentName,
				Origin = jsonCountry.Name,
				Position = base.Position,
				Salary = base.Salary,
				ShirtName = homeTrikot,
				Shirt = base.ShirtNr.GetValueOrDefault(),
				Shoes = base.SkinShoes,
				Strength = base.Strength,
				Talent = base.Talent,
				YellowCards = base.YellowCards
			};
		}
	}
